def _mode_change_is_blocked(request_lease=None, transport_reserved=False):
    if not isinstance(transport_reserved, bool):
        raise TypeError("mode-transition transport reservation flag must be boolean")
    if request_lease is not None and not motion_request_registry.owns(request_lease):
        raise RuntimeError("mode transition requires matching motion ownership")
    if transport_reserved and request_lease is None:
        raise RuntimeError("mode transition transport requires motion ownership")
    if transport_reserved and not serial_lock.locked():
        raise RuntimeError("mode transition transport reservation is missing")

    if application_closing.is_set():
        message = "Mode change rejected during application shutdown"
    elif (
        controller_correction_requested.is_set()
        or manual_motion_pose_pending.is_set()
        or controller_position_resynchronization_required.is_set()
    ):
        message = "Mode change rejected while controller recovery is pending"
    elif (
        _virtual_motion_active(request_lease)
        or live_serial_result_pending.is_set()
        or serial_result_pending.is_set()
        or joint_motion_dispatcher.active
        or (serial_lock.locked() and not transport_reserved)
    ):
        message = "Mode change rejected while motion or controller ownership is active"
    else:
        return False
    logger.warning(message)
    _set_application_status(text=message, style="Warn.TLabel")
    return True


def _set_offline_mode_status(offline):
    if offline:
        offline_button.config(text="Go Online", style="Offline.TButton")
        message = "SYSTEM IN OFFLINE MODE"
        style = "Warn.TLabel"
    else:
        offline_button.config(text="Run Offline", style="Online.TButton")
        message = "SYSTEM IN ONLINE MODE"
        style = "OK.TLabel"
    _set_application_status(text=message, style=style)


def toggle_offline_mode():
    request_lease = _acquire_motion_request(
        "Mode transition",
        allow_uncalibrated=True,
    )
    if request_lease is None:
        message = _motion_request_rejection_message(
            "Mode change rejected while motion or recovery ownership is active"
        )
        logger.warning(message)
        _set_application_status(text=message, style="Warn.TLabel")
        return False
    try:
        with _reserve_main_serial_operation():
            if _mode_change_is_blocked(
                request_lease,
                transport_reserved=True,
            ):
                return False

            if RUN['offlineMode']:
                virtual_snapshot = list(RUN['VR_angles'])
                if requestPos() is not True:
                    RUN['VR_angles'] = virtual_snapshot
                    _set_offline_mode_status(True)
                    return False
                RUN['offlineMode'] = False
                _set_offline_mode_status(False)
                RUN['VR_angles'] = [float(CAL['J1AngCur']), float(CAL['J2AngCur']), float(CAL['J3AngCur']), float(CAL['J4AngCur']), float(CAL['J5AngCur']), float(CAL['J6AngCur'])]
                setStepMonitorsVR()
            else:
                previous_virtual_pose = list(RUN['VR_angles'])
                RUN['offlineMode'] = True
                _set_offline_mode_status(True)
                RUN['VR_angles'] = [0.000, 0.000, 0.000, 0.000, 90.000, 0.000]
                J1negLimLab.config(text=f"-{CAL['J1NegLim']}", style="Jointlim.TLabel")
                J1posLimLab.config(text=CAL['J1PosLim'], style="Jointlim.TLabel")
                J1jogslide.config(from_=-float(CAL['J1NegLim']), to=float(CAL['J1PosLim']),  length=180, orient=HORIZONTAL,  command=J1sliderUpdate)
                J2negLimLab.config(text=f"-{CAL['J2NegLim']}", style="Jointlim.TLabel")
                J2posLimLab.config(text=CAL['J2PosLim'], style="Jointlim.TLabel")
                J2jogslide.config(from_=-float(CAL['J2NegLim']), to=float(CAL['J2PosLim']),  length=180, orient=HORIZONTAL,  command=J2sliderUpdate)
                J3negLimLab.config(text=f"-{CAL['J3NegLim']}", style="Jointlim.TLabel")
                J3posLimLab.config(text=CAL['J3PosLim'], style="Jointlim.TLabel")
                J3jogslide.config(from_=-float(CAL['J3NegLim']), to=float(CAL['J3PosLim']),  length=180, orient=HORIZONTAL,  command=J3sliderUpdate)
                J4negLimLab.config(text=f"-{CAL['J4NegLim']}", style="Jointlim.TLabel")
                J4posLimLab.config(text=CAL['J4PosLim'], style="Jointlim.TLabel")
                J4jogslide.config(from_=-float(CAL['J4NegLim']), to=float(CAL['J4PosLim']),  length=180, orient=HORIZONTAL,  command=J4sliderUpdate)
                J5negLimLab.config(text=f"-{CAL['J5NegLim']}", style="Jointlim.TLabel")
                J5posLimLab.config(text=CAL['J5PosLim'], style="Jointlim.TLabel")
                J5jogslide.config(from_=-float(CAL['J5NegLim']), to=float(CAL['J5PosLim']),  length=180, orient=HORIZONTAL,  command=J5sliderUpdate)
                J6negLimLab.config(text=f"-{CAL['J6NegLim']}", style="Jointlim.TLabel")
                J6posLimLab.config(text=CAL['J6PosLim'], style="Jointlim.TLabel")
                J6jogslide.config(from_=-float(CAL['J6NegLim']), to=float(CAL['J6PosLim']),  length=180, orient=HORIZONTAL,  command=J6sliderUpdate)
                try:
                    refresh_gui_from_joint_angles(RUN['VR_angles'])
                except MotionInputError as exc:
                    RUN['offlineMode'] = False
                    RUN['VR_angles'] = previous_virtual_pose
                    setStepMonitorsVR()
                    _set_offline_mode_status(False)
                    message = f"Mode change rejected during virtual refresh: {exc}"
                    logger.error(message)
                    _set_application_status(text=message, style="Alarm.TLabel")
                    return False
            return True
    except SerialActivityRejected as exc:
        message = f"Mode change rejected: {exc}"
        logger.warning(message)
        _set_application_status(text=message, style="Warn.TLabel")
        return False
    finally:
        _finish_motion_request(request_lease)

class CustomInteractorStyle(vtk.vtkInteractorStyleTrackballCamera):
    def __init__(self, renderer):
        self.AddObserver("LeftButtonReleaseEvent", self.on_left_button_up)
        self.renderer = renderer

    def on_left_button_up(self, obj, event):
        self.OnLeftButtonUp()  # <-- CORRECT way to call the base method

def add_floor_grid(renderer, size=1000, spacing=50):
    grid = vtk.vtkPolyData()
    points = vtk.vtkPoints()
    lines = vtk.vtkCellArray()

    count = 0
    for i in range(-size, size + spacing, spacing):
        # lines parallel to X
        points.InsertNextPoint(i, -size, 0)
        points.InsertNextPoint(i, size, 0)
        lines.InsertNextCell(2)
        lines.InsertCellPoint(count)
        lines.InsertCellPoint(count + 1)
        count += 2

        # lines parallel to Y
        points.InsertNextPoint(-size, i, 0)
        points.InsertNextPoint(size, i, 0)
        lines.InsertNextCell(2)
        lines.InsertCellPoint(count)
        lines.InsertCellPoint(count + 1)
        count += 2

    grid.SetPoints(points)
    grid.SetLines(lines)

    mapper = vtk.vtkPolyDataMapper()
    mapper.SetInputData(grid)

    actor = vtk.vtkActor()
    actor.SetMapper(mapper)
    actor.GetProperty().SetColor(0.7, 0.7, 0.7)  # Light gray
    actor.GetProperty().SetLineWidth(1)

    RUN['renderer'].AddActor(actor)        

def on_close_event(obj, event):
    RUN['vtk_running'] = False
    scene = RUN.get('cad_scene')
    try:
        if scene is not None:
            scene.unbind_vtk()
    except Exception:
        logger.exception("CAD scene unbind failed during viewer close")
    finally:
        RUN['robot_link_view'] = None
        try:
            obj.GetRenderWindow().Finalize()
            obj.TerminateApp()
        except Exception:
            logger.exception("VTK viewer close failed")
    if 'cad_tree' in globals():
        _refresh_cad_controls()

def update_vtk(render_window, root_widget):
    if not RUN['vtk_running'] or render_window is not RUN.get('render_window'):
        return

    angles = tuple(
        finite_number(angle, "virtual joint angle")
        for angle in RUN['VR_angles']
    )
    angles_changed = angles != RUN.get('lastRenderedAngles')
    if angles_changed:
        RUN['robot_link_view'].update_joint_angles(angles)
        render_window.Render()
        RUN['lastRenderedAngles'] = angles

    delay_ms = 16 if angles_changed else 100
    root_widget.after(
        delay_ms,
        lambda: update_vtk(render_window, root_widget),
    )


def launch_vtk_nonblocking(root_widget):
    if RUN['vtk_running']:
        logger.warning("Virtual robot viewer is already active")
        return False

    try:
        robot_link_view = RobotLinkView(
            DIR,
            selected_bundled_tool=bundled_tool_var.get() or None,
        )
    except (OSError, ValueError) as exc:
        message = f"Virtual robot viewer unavailable: {exc}"
        logger.error(message)
        _set_application_status(text=message, style="Warn.TLabel")
        return False
    RUN['robot_link_view'] = robot_link_view
    RUN['vtk_running'] = True

    RUN['renderer'] = vtk.vtkRenderer()
    RUN['render_window'] = vtk.vtkRenderWindow() 
    RUN['render_window'].SetWindowName("AR4 Virtual Robot Viewer")
    RUN['interactor'] = vtk.vtkRenderWindowInteractor()
    RUN['render_window'].AddRenderer(RUN['renderer'])
    RUN['interactor'].SetRenderWindow(RUN['render_window'])

    style = CustomInteractorStyle(RUN['renderer'])
    RUN['interactor'].SetInteractorStyle(style)

    RUN['render_window'].SetSize(1024, 768)
    RUN['renderer'].SetBackground(vtk.vtkNamedColors().GetColor3d("LightSlateGray"))

    RUN['renderer'].AddActor(robot_link_view.root)
    scene = RUN.get('cad_scene')
    if scene is not None:
        try:
            scene.bind_vtk(
                RUN['renderer'], anchors={'tool_mount': robot_link_view.tool_mount}
            )
            if 'cad_status_var' in globals():
                cad_status_var.set("CAD scene ready")
        except Exception as exc:
            logger.error("CAD viewer binding failed: %s", exc)
            if 'cad_status_var' in globals():
                cad_status_var.set(f"CAD viewer binding failed: {exc}")
    add_floor_grid(RUN['renderer'])

    camera = RUN['renderer'].GetActiveCamera()
    RUN['renderer'].ResetCamera()
    camera.Dolly(3)
    camera.Azimuth(65)
    camera.Elevation(55)
    camera.SetViewUp(0, 0, 1)
    RUN['renderer'].ResetCameraClippingRange()

    RUN['interactor'].AddObserver("ExitEvent", on_close_event)
    RUN['interactor'].Initialize()
    RUN['render_window'].Render()
    
    set_vtk_topmost_delayed()

    RUN['VR_angles'] = [float(CAL['J1AngCur']), float(CAL['J2AngCur']), float(CAL['J3AngCur']), float(CAL['J4AngCur']), float(CAL['J5AngCur']), float(CAL['J6AngCur'])]
    setStepMonitorsVR()
    update_main_color()

    RUN['lastRenderedAngles'] = None
    update_vtk(RUN['render_window'], root_widget)
    if 'cad_tree' in globals():
        _refresh_cad_controls()
    return True





def set_vtk_topmost_delayed():
    window_title = "AR4 Virtual Robot Viewer"

    def set_topmost():
        time.sleep(0.5)
        os_type = platform.system()

        for _attempt in range(20):
            if not RUN['vtk_running']:
                return
            try:
                if os_type == 'Windows':
                    import win32con
                    import win32gui

                    hwnd = win32gui.FindWindow(None, window_title)
                    if hwnd:
                        win32gui.SetWindowPos(
                            hwnd,
                            win32con.HWND_TOPMOST,
                            0,
                            0,
                            0,
                            0,
                            win32con.SWP_NOMOVE
                            | win32con.SWP_NOSIZE
                            | win32con.SWP_NOACTIVATE,
                        )
                        return

                elif os_type == 'Linux':
                    try:
                        result = subprocess.run(
                            ['wmctrl', '-l'],
                            capture_output=True,
                            text=True,
                            check=False,
                            timeout=2,
                        )
                    except FileNotFoundError:
                        result = None

                    if result is not None and result.returncode == 0:
                        for line in result.stdout.splitlines():
                            fields = line.split(maxsplit=3)
                            if len(fields) == 4 and window_title in fields[3]:
                                mutation = subprocess.run(
                                    [
                                        'wmctrl',
                                        '-i',
                                        '-r',
                                        fields[0],
                                        '-b',
                                        'add,above',
                                    ],
                                    capture_output=True,
                                    check=False,
                                    timeout=2,
                                )
                                if mutation.returncode == 0:
                                    return
                                logger.debug(
                                    "wmctrl could not mark the VTK viewer topmost: exit %s",
                                    mutation.returncode,
                                )

                    try:
                        result = subprocess.run(
                            ['xdotool', 'search', '--name', window_title],
                            capture_output=True,
                            text=True,
                            check=False,
                            timeout=2,
                        )
                    except FileNotFoundError:
                        result = None

                    if result is not None and result.returncode == 0:
                        window_ids = result.stdout.split()
                        if window_ids:
                            mutation = subprocess.run(
                                ['xdotool', 'windowraise', window_ids[0]],
                                capture_output=True,
                                check=False,
                                timeout=2,
                            )
                            if mutation.returncode == 0:
                                return
                            logger.debug(
                                "xdotool could not raise the VTK viewer: exit %s",
                                mutation.returncode,
                            )
                else:
                    return
            except (OSError, subprocess.SubprocessError) as exc:
                logger.debug("VTK topmost attempt failed: %s", exc)

            time.sleep(0.25)

        logger.debug("VTK viewer did not become available for topmost configuration")

    threading.Thread(target=set_topmost, daemon=True).start()



def _cad_scene_for_action():
    scene, error = RUN.get('cad_scene'), RUN.get('cad_scene_error')
    if scene is None or error:
        raise CadSceneError(error or "CAD scene is unavailable")
    return scene


def _reparent_cad_scene_at_current_pose(scene, object_id, parent):
    request_lease = _acquire_motion_request("CAD reparenting", requires_kinematics=False)
    if request_lease is None:
        raise CadSceneError(_motion_request_rejection_message(
            "CAD reparenting requires idle motion",
        ))
    try:
        if _virtual_motion_active(request_lease):
            raise CadSceneError("CAD reparenting requires idle motion")
        robot_link_view = RUN['robot_link_view']
        angles = _validated_virtual_six_vector(RUN['VR_angles'], "virtual robot pose")
        RUN['lastRenderedAngles'] = None
        robot_link_view.update_joint_angles(angles)
        anchor = {'tool_mount': robot_link_view.tool_mount_world_matrix()}
        item = scene.reparent(object_id, parent, anchor_world_matrices=anchor)
        try:
            RUN['render_window'].Render()
        except Exception:
            logger.exception("CAD reparent committed; pose render failed")
        else:
            RUN['lastRenderedAngles'] = angles
        return item
    finally:
        _finish_motion_request(request_lease)


def _execute_virtual_scene_program_row(command):
    try:
        scene = _cad_scene_for_action()
        renderer = RUN.get('renderer')
        render_window = RUN.get('render_window')
        robot_link_view = RUN.get('robot_link_view')
        if (
            RUN.get('vtk_running') is not True
            or not isinstance(scene, PersistentCadScene)
            or not isinstance(robot_link_view, RobotLinkView)
            or renderer is None
            or render_window is None
            or not scene.is_bound_to(renderer)
        ):
            raise CadSceneError("Virtual Pick/Place requires an active bound viewer")
        action, object_id = _parse_virtual_scene_row(command)
        parent = {'Pick': 'tool_mount', 'Place': 'world'}[action]
        item = _reparent_cad_scene_at_current_pose(scene, object_id, parent)
    except (CadSceneError, MotionInputError) as exc:
        message = f"Virtual scene row rejected: {exc}"
        logger.error(message)
        _set_application_status(text=message, style="Alarm.TLabel")
        cad_status_var.set(message)
        return False
    try:
        _refresh_cad_controls(item.object_id)
        cad_status_var.set(f"CAD object parent is {item.parent}")
    except Exception:
        logger.exception("Virtual scene row committed; display refresh failed")
    return True

def _selected_cad_object():
    selected = cad_tree.selection()
    scene = RUN.get('cad_scene')
    if len(selected) != 1 or scene is None:
        return None
    return next((item for item in scene.objects if item.object_id == selected[0]), None)

def _set_cad_action_states(item=None):
    available = RUN.get('cad_scene') is not None and not RUN.get('cad_scene_error')
    converting = step_conversion_request is not None
    cad_buttons['import'].config(state=NORMAL if available and not converting else DISABLED)
    if converting:
        cad_buttons['cancel'].grid()
    else:
        cad_buttons['cancel'].grid_remove()
    selected = available and item is not None
    for name in ('update', 'delete'):
        cad_buttons[name].config(state=NORMAL if selected else DISABLED)
    active = selected and RUN['vtk_running'] and RUN['cad_scene'].is_bound_to(RUN.get('renderer'))
    cad_buttons['attach'].config(state=NORMAL if active and item.parent == 'world' else DISABLED)
    cad_buttons['detach'].config(state=NORMAL if active and item.parent == 'tool_mount' else DISABLED)


def _show_cad_selection(event=None):
    item = _selected_cad_object()
    if item is not None:
        for field in ('label', 'x_mm', 'y_mm', 'z_mm', 'rx_deg', 'ry_deg', 'rz_deg'):
            cad_fields[field].set(getattr(item, field))
    _set_cad_action_states(item)


def _refresh_cad_controls(select_id=None):
    current = cad_tree.selection()
    if select_id is None and len(current) == 1:
        select_id = current[0]
    rows = cad_tree.get_children()
    if rows:
        cad_tree.delete(*rows)
    scene = RUN.get('cad_scene')
    if scene is not None:
        for item in scene.objects:
            cad_tree.insert('', END, iid=item.object_id, text=item.object_id,
                            values=(item.label, item.parent))
    if select_id in cad_tree.get_children():
        cad_tree.selection_set(select_id)
    _show_cad_selection()
    error = RUN.get('cad_scene_error')
    if error:
        cad_status_var.set(error)


def _run_cad_mutation(operation, success_message, *, requires_selection=False):
    selected = cad_tree.selection()
    select_id = selected[0] if len(selected) == 1 else None
    item = None
    status = success_message
    try:
        if requires_selection and select_id is None:
            raise CadSceneError("select one CAD object")
        scene = _cad_scene_for_action()
        item = operation(scene, select_id)
        if item is not None:
            select_id = item.object_id
    except (CadSceneError, ValueError, OverflowError) as exc:
        status = f"CAD action failed: {exc}"
        logger.error("CAD action failed: %s", exc)
    finally:
        scene = RUN.get('cad_scene')
        if RUN['vtk_running'] and scene is not None and not scene.is_bound_to(RUN.get('renderer')):
            status = f"{status}; CAD viewer binding failed"
        cad_status_var.set(status)
        _refresh_cad_controls(select_id)
        if RUN['vtk_running'] and RUN.get('render_window') is not None:
            RUN['render_window'].Render()
    return item


def _run_step_conversion(source, control):
    try:
        result = convert_step(source, control=control)
    except StepConversionError as exc:
        result = str(exc)
    except Exception:
        logger.exception("Unexpected STEP conversion failure")
        result = "STEP conversion failed"
    step_conversion_event_queue.put((control, result))


def _commit_step_result(result):
    temporary_path = None
    item = None
    cleanup_failed = False
    try:
        with tempfile.NamedTemporaryFile(
            prefix="ar4-step-handoff-", suffix=".stl", delete=False,
        ) as destination:
            temporary_path = destination.name
            if destination.write(result.stl_payload) != len(result.stl_payload):
                raise OSError("temporary STEP handoff write was incomplete")
        item = _run_cad_mutation(
            lambda scene, unused: scene.import_stl(temporary_path, label=result.label),
            "STEP object imported",
        )
    finally:
        if temporary_path is not None:
            try:
                os.unlink(temporary_path)
            except FileNotFoundError:
                pass
            except OSError:
                cleanup_failed = True
                logger.exception("Unable to remove the temporary STEP handoff")
    if cleanup_failed:
        if item is not None:
            cad_status_var.set("STEP import committed; temporary cleanup failed")
        else:
            cad_status_var.set(f"{cad_status_var.get()}; temporary cleanup failed")
    return item


def _poll_step_conversion_events():
    global step_conversion_request

    _reschedule_event_poll("step-conversion")
    try:
        event = step_conversion_event_queue.get_nowait()
    except Empty:
        return
    request = step_conversion_request
    if not isinstance(event, tuple) or len(event) != 2 or event[0] is not request:
        if not application_closing.is_set():
            logger.error("Discarding an invalid or stale STEP conversion result")
    else:
        result = event[1]
        closing = application_closing.is_set()
        try:
            if closing or request.is_cancelled():
                if not closing:
                    cad_status_var.set("STEP import cancelled")
            elif isinstance(result, StepConversionResult):
                _commit_step_result(result)
            elif isinstance(result, str) and result:
                cad_status_var.set(f"STEP import failed: {result}")
            else:
                raise TypeError("STEP conversion result is invalid")
        except Exception:
            logger.exception("Unable to settle the STEP conversion result")
            if not closing:
                cad_status_var.set("STEP import failed")
        finally:
            step_conversion_request = None
            if not closing:
                _refresh_cad_controls()


def _start_step_conversion(source):
    global step_conversion_request

    if application_closing.is_set() or step_conversion_request is not None:
        return
    control = StepConversionControl()
    step_conversion_request = control
    cad_status_var.set("Converting STEP")
    _set_cad_action_states(_selected_cad_object())
    try:
        threading.Thread(
            target=_run_step_conversion,
            args=(source, control),
            name="ar4-step-conversion",
            daemon=True,
        ).start()
    except Exception:
        step_conversion_request = None
        logger.exception("Unable to start STEP conversion")
        cad_status_var.set("STEP import failed")
        _set_cad_action_states(_selected_cad_object())


def cancel_step_conversion():
    if step_conversion_request is not None:
        step_conversion_request.cancel()
        cad_status_var.set("STEP cancellation requested")


def import_cad_file():
    source = fd.askopenfilename(filetypes=[
        ("CAD files", ("*.stl", "*.step", "*.stp")),
        ("All files", "*.*"),
    ])
    if not source:
        return
    suffix = Path(source).suffix.lower()
    if suffix == ".stl":
        cad_fields['label'].set(Path(source).stem)
        _run_cad_mutation(
            lambda scene, unused: scene.import_stl(source, label=cad_fields['label'].get()),
            "CAD object imported",
        )
    elif suffix in (".step", ".stp"):
        _start_step_conversion(source)
    else:
        cad_status_var.set("CAD action failed: select an STL, STEP, or STP file")


def update_cad_object():
    def update(scene, object_id):
        values = {name: float(cad_fields[name].get()) for name in
                  ('x_mm', 'y_mm', 'z_mm', 'rx_deg', 'ry_deg', 'rz_deg')}
        return scene.update_object(object_id, label=cad_fields['label'].get(), **values)
    _run_cad_mutation(update, "CAD object updated", requires_selection=True)


def delete_cad_object():
    _run_cad_mutation(lambda scene, object_id: scene.delete_object(object_id),
                      "CAD object deleted", requires_selection=True)


def reparent_cad_object(parent):
    def reparent(scene, object_id):
        if not RUN['vtk_running'] or not scene.is_bound_to(RUN.get('renderer')):
            raise CadSceneError("attach and detach require the active viewer")
        return _reparent_cad_scene_at_current_pose(scene, object_id, parent)
    _run_cad_mutation(reparent, f"CAD object moved to {parent}", requires_selection=True)




