def startup_spinner(root, message="Please wait…"):
    win = tk.Toplevel(root)
    win.title("")
    win.transient(root)
    win.resizable(False, False)
    win.grab_set()  # modal

    # Use same icon as main window
    #win.iconbitmap(r'AR.png')
    win.iconphoto(True, tk.PhotoImage(file="AR.png"))
    ttk.Label(win, text=message, padding=12).pack()
    pb = ttk.Progressbar(win, mode="indeterminate", length=220)
    pb.pack(padx=12, pady=(0, 12))
    pb.start(12)

    # Center on parent
    root.update_idletasks()
    x = root.winfo_rootx() + (root.winfo_width() - win.winfo_reqwidth()) // 2
    y = root.winfo_rooty() + (root.winfo_height() - win.winfo_reqheight()) // 2
    win.geometry(f"+{x}+{y}")

    win.update_idletasks()
    return win, pb


def _validated_startup_command(command, expected_prefix):
    if not isinstance(command, str) or not command.startswith(expected_prefix):
        raise MotionInputError(
            f"controller startup command must begin with {expected_prefix!r}"
        )
    if not command.endswith("\n") or "\n" in command[:-1] or "\r" in command:
        raise MotionInputError(
            "controller startup command must contain one trailing line delimiter"
        )
    if len(command) > MAX_COMMAND_LENGTH:
        raise MotionInputError("controller startup command exceeds the size limit")
    try:
        command.encode("ascii")
    except UnicodeEncodeError as exc:
        raise MotionInputError(
            "controller startup command must contain ASCII characters only"
        ) from exc
    return command


def _build_startup_numeric_command(prefix, fields):
    if not isinstance(prefix, str) or not prefix or not prefix.isascii():
        raise MotionInputError("controller startup prefix must be ASCII text")
    if isinstance(fields, (str, bytes)):
        raise MotionInputError("controller startup fields must be a sequence")
    try:
        fields = iter(fields)
    except TypeError as exc:
        raise MotionInputError(
            "controller startup fields must be a sequence"
        ) from exc
    parts = [prefix]
    markers = set()
    for index, field in enumerate(fields):
        if (
            not isinstance(field, (tuple, list))
            or len(field) != 2
        ):
            raise MotionInputError(
                f"controller startup field {index} must contain a marker and value"
            )
        marker, value = field
        if (
            not isinstance(marker, str)
            or not marker
            or not marker.isascii()
            or "\n" in marker
            or "\r" in marker
        ):
            raise MotionInputError("controller startup marker must be ASCII text")
        if marker in markers:
            raise MotionInputError(
                f"controller startup marker {marker!r} is duplicated"
            )
        markers.add(marker)
        parts.append(marker)
        parts.append(
            controller_protocol_decimal(
                value,
                f"{prefix} field {marker!r}",
            )
        )
    return _validated_startup_command("".join(parts) + "\n", prefix)


def _controller_startup_mapping_snapshot(values, field_name):
    if not isinstance(values, dict):
        raise MotionInputError(f"{field_name} must be a dictionary")
    snapshot = []
    for key, value in values.items():
        if not isinstance(key, str) or not key:
            raise MotionInputError(f"{field_name} keys must be non-empty text")
        if type(value) not in (str, int, float):
            raise MotionInputError(f"{field_name} values must be scalar")
        if type(value) is float and not math.isfinite(value):
            raise MotionInputError(f"{field_name} values must be finite")
        snapshot.append((key, value))
    return tuple(sorted(snapshot))


def _controller_startup_position_snapshot(values):
    if isinstance(values, (str, bytes)):
        raise MotionInputError(
            "controller startup position must be a numeric sequence"
        )
    try:
        values = tuple(values)
    except TypeError as exc:
        raise MotionInputError(
            "controller startup position must be a numeric sequence"
        ) from exc
    if len(values) != 9:
        raise MotionInputError("controller startup position must contain 9 values")
    return tuple(
        finite_number(value, f"J{axis} controller startup position")
        for axis, value in enumerate(values, start=1)
    )


@dataclass(frozen=True)
class ControllerStartupRequest:
    auxiliary_port: Optional[str]
    update_parameters_command: str
    external_axis_command: str
    position_command: str
    semantic_update_values: object
    semantic_external_values: object
    semantic_position_target: object
    auxiliary_board: Optional[str] = None

    def __post_init__(self):
        if self.auxiliary_port is None:
            auxiliary_port = None
        elif not isinstance(self.auxiliary_port, str):
            raise MotionInputError("auxiliary controller port must be text")
        else:
            auxiliary_port = self.auxiliary_port.strip()
            if auxiliary_port in ("", "None"):
                auxiliary_port = None
        auxiliary_board = normalize_auxiliary_board_profile(
            self.auxiliary_board,
            allow_none=True,
        )
        object.__setattr__(self, "auxiliary_port", auxiliary_port)
        object.__setattr__(self, "auxiliary_board", auxiliary_board)
        object.__setattr__(
            self,
            "update_parameters_command",
            _validated_startup_command(self.update_parameters_command, "UP"),
        )
        object.__setattr__(
            self,
            "external_axis_command",
            _validated_startup_command(self.external_axis_command, "CE"),
        )
        object.__setattr__(
            self,
            "position_command",
            _validated_startup_command(self.position_command, "SP"),
        )
        object.__setattr__(
            self,
            "semantic_update_values",
            _controller_startup_mapping_snapshot(
                self.semantic_update_values,
                "controller startup update-parameter values",
            ),
        )
        object.__setattr__(
            self,
            "semantic_external_values",
            _controller_startup_mapping_snapshot(
                self.semantic_external_values,
                "controller startup external-axis values",
            ),
        )
        object.__setattr__(
            self,
            "semantic_position_target",
            _controller_startup_position_snapshot(
                self.semantic_position_target,
            ),
        )


@dataclass(frozen=True)
class ControllerStartupResult:
    position: PositionResponse
    visual_options: tuple
    auxiliary_serial: object
    controller_identity: ControllerIdentity
    home_reference: Optional[PrimaryHomeReference] = None
    auxiliary_error: Optional[str] = None
    json_bootstrap: object = None

    def __post_init__(self):
        if not isinstance(self.position, PositionResponse):
            raise ProtocolResponseError(
                "controller startup position has an invalid type"
            )
        if not isinstance(self.controller_identity, ControllerIdentity):
            raise ProtocolResponseError(
                "controller startup identity has an invalid type"
            )
        if (
            self.json_bootstrap is not None
            and type(self.json_bootstrap)
            is not JsonMainControllerPersistentStartupResult
        ):
            raise ProtocolResponseError(
                "controller JSON startup result has an invalid type"
            )
        if (
            self.home_reference is not None
            and not isinstance(self.home_reference, PrimaryHomeReference)
        ):
            raise ProtocolResponseError(
                "controller startup home reference has an invalid type"
            )
        if self.home_reference is None:
            raise ProtocolResponseError(
                "controller startup home reference is missing"
            )
        if isinstance(self.visual_options, (str, bytes)):
            raise ProtocolResponseError("visual options must be a sequence")
        try:
            visual_options = tuple(self.visual_options)
        except TypeError as exc:
            raise ProtocolResponseError("visual options must be a sequence") from exc
        if not all(
            isinstance(option, str)
            and option.endswith('.jpg')
            and os.path.basename(option) == option
            for option in visual_options
        ):
            raise ProtocolResponseError("visual options contain an invalid filename")
        auxiliary_error = self.auxiliary_error
        if auxiliary_error is not None:
            if not isinstance(auxiliary_error, str) or not auxiliary_error.strip():
                raise ProtocolResponseError(
                    "auxiliary startup error must be non-empty text or None"
                )
            auxiliary_error = auxiliary_error.strip()
        if self.auxiliary_serial is not None and auxiliary_error is not None:
            raise ProtocolResponseError(
                "auxiliary startup cannot contain both a connection and an error"
            )
        object.__setattr__(self, "visual_options", visual_options)
        object.__setattr__(self, "auxiliary_error", auxiliary_error)


def _startup_visual_options():
    if getattr(sys, 'frozen', False):
        folder = os.path.dirname(sys.executable)
    else:
        folder = os.path.dirname(os.path.realpath(__file__))
    return tuple(sorted(
        filename
        for filename in os.listdir(folder)
        if isinstance(filename, str) and filename.endswith('.jpg')
    ))


def _publish_startup_main_controller_json_stop(serial_port, physical_stop):
  if type(physical_stop) is not JsonMainControllerPhysicalStop:
    raise TypeError("controller JSON startup stop evidence is invalid")
  stop_context = _capture_startup_main_controller_stop_context(serial_port)
  return _publish_main_controller_unpositioned_stop(
    stop_context,
    physical_stop,
  )


def _close_persistent_json_startup_result(json_bootstrap):
  if json_bootstrap is None:
    return True
  if type(json_bootstrap) is not JsonMainControllerPersistentStartupResult:
    raise TypeError("controller JSON startup result is invalid")
  client = json_bootstrap.client
  client.close(timeout=JSON_COORDINATOR_DEFAULT_CLOSE_TIMEOUT_SECONDS)
  if not client.closed or getattr(client.serial_port, "is_open", False):
    raise OSError("persistent controller JSON startup remained open")
  return True


def _json_startup_position_disposition(json_bootstrap):
  if json_bootstrap is None:
    return None
  if type(json_bootstrap) is not JsonMainControllerPersistentStartupResult:
    raise TypeError("controller JSON startup result is invalid")
  json_position = json_bootstrap.position
  if type(json_position) is not JsonMainPositionResult:
    raise ProtocolResponseError("invalid JSON startup position")
  if json_position.motion_fault:
    raise ProtocolResponseError(
      "controller reported a JSON startup fault: "
      f"{json_position.motion_fault}"
    )
  return json_position


def _retain_json_startup_disposition_error(
  json_bootstrap,
  operation_error,
  context,
):
  if type(json_bootstrap) is not JsonMainControllerPersistentStartupResult:
    return operation_error
  json_position = getattr(json_bootstrap, "position", None)
  if type(json_position) is not JsonMainPositionResult:
    return operation_error
  return retain_main_controller_startup_disposition_error(
    json_position,
    operation_error,
    context,
  )


def _close_startup_auxiliary(serial_port, json_client=None):
    if serial_port is None:
        return True
    if not auxiliary_serial_lock.acquire(blocking=False):
        logger.error("Auxiliary startup cleanup could not reserve the transport")
        return False
    try:
        if RUN.get('ser2') is serial_port and json_client is None:
            return _close_serial_port('ser2', "auxiliary startup cleanup")
        if (
            getattr(serial_port, "is_open", None) is False
            and (json_client is None or json_client.closed)
        ):
            return True
        try:
            if json_client is None:
                serial_port.close()
            else:
                _require_persistent_json_client_cleanup(
                    json_client,
                    serial_port,
                    "retained auxiliary cleanup",
                )
        except Exception:
            logger.exception("Unable to close the auxiliary startup connection")
            return False
        if getattr(serial_port, "is_open", False):
            logger.error("Auxiliary startup connection remained open during cleanup")
            return False
        if RUN.get('ser2') is serial_port:
            RUN['ser2'] = None
            _clear_auxiliary_board_profile(serial_port)
        return True
    finally:
        auxiliary_serial_lock.release()


def _run_startup_auxiliary_cleanup():
    global startup_auxiliary_cleanup_worker

    while True:
        with startup_auxiliary_cleanup_lock:
            pending_connections = tuple(
                startup_auxiliary_cleanup_pending.values()
            )
            if not pending_connections:
                startup_auxiliary_cleanup_worker = None
                return

        closed_any = False
        for serial_port, json_client in pending_connections:
            if not _close_startup_auxiliary(serial_port, json_client):
                continue
            with startup_auxiliary_cleanup_lock:
                key = id(serial_port)
                pending = startup_auxiliary_cleanup_pending.get(key)
                if (
                    isinstance(pending, tuple)
                    and len(pending) == 2
                    and pending[0] is serial_port
                    and pending[1] is json_client
                ):
                    del startup_auxiliary_cleanup_pending[key]
            closed_any = True

        if not closed_any:
            time.sleep(SERIAL_SHUTDOWN_RETRY_MS / 1000.0)


def _ensure_startup_auxiliary_cleanup():
    global startup_auxiliary_cleanup_worker

    with startup_auxiliary_cleanup_lock:
        if not startup_auxiliary_cleanup_pending:
            return True
        worker = startup_auxiliary_cleanup_worker
        if worker is not None and worker.is_alive():
            return True
        try:
            worker = threading.Thread(
                target=_run_startup_auxiliary_cleanup,
                name="ar4-startup-auxiliary-cleanup",
                daemon=True,
            )
            startup_auxiliary_cleanup_worker = worker
            worker.start()
        except Exception:
            startup_auxiliary_cleanup_worker = None
            logger.exception("Unable to start auxiliary startup cleanup retry")
            return False
    return True


def _request_startup_auxiliary_cleanup(serial_port, json_client=None):
    if serial_port is None:
        return True
    if json_client is None and RUN.get('ser2') is serial_port:
        binding = RUN.get('ser2BoardProfile')
        if (
            isinstance(binding, tuple)
            and len(binding) == 3
            and binding[0] is serial_port
        ):
            json_client = binding[2]
    if _close_startup_auxiliary(serial_port, json_client):
        with startup_auxiliary_cleanup_lock:
            key = id(serial_port)
            pending = startup_auxiliary_cleanup_pending.get(key)
            if (
                isinstance(pending, tuple)
                and len(pending) == 2
                and pending[0] is serial_port
            ):
                del startup_auxiliary_cleanup_pending[key]
        return True

    # Retain the failed handle until a retry closes it; dropping the last
    # reference can leave an open OS handle outside shutdown ownership.
    with startup_auxiliary_cleanup_lock:
        startup_auxiliary_cleanup_pending[id(serial_port)] = (
            serial_port,
            json_client,
        )
    _ensure_startup_auxiliary_cleanup()
    return False


def _connect_startup_auxiliary(port, board_profile):
  if not auxiliary_serial_lock.acquire(blocking=False):
    raise MotionTransportBusy("auxiliary controller transport is busy")
  try:
    return _replace_auxiliary_serial(port, board_profile)
  finally:
    auxiliary_serial_lock.release()


def _clear_unavailable_startup_auxiliary():
  serial_port = RUN.get('ser2')
  if serial_port is None:
    _clear_auxiliary_board_profile()
    return True
  if _request_startup_auxiliary_cleanup(serial_port):
    if RUN.get('ser2') is None:
      _clear_auxiliary_board_profile()
      return True
    raise MotionTransportBusy(
      "auxiliary controller ownership changed during startup cleanup"
    )
  raise MotionTransportBusy(
    "existing auxiliary controller could not be closed before startup commit"
  )


def startup_with_spinner(
    root,
    startup_request,
    on_finished,
    on_timeout,
    on_abandoned,
    timeout=10.0,
):
    timeout = finite_number(timeout, "controller startup timeout")
    if timeout <= 0:
        raise MotionInputError("controller startup timeout must be positive")
    if not isinstance(startup_request, ControllerStartupRequest):
        raise MotionInputError(
            "startup_request must be a ControllerStartupRequest"
        )
    if not all(callable(callback) for callback in (
        on_finished,
        on_timeout,
        on_abandoned,
    )):
        raise TypeError("controller startup callbacks must be callable")

    spinner, pb = startup_spinner(root, "Please Wait.. System Starting")
    q = Queue()
    cancellation_boundary = SerialWriteCancellationBoundary(
      "controller startup"
    )
    missing = object()
    pending_result = missing
    timed_out = False
    spinner_closed = False
    cancelled = False
    work_complete = threading.Event()
    finalization_complete = threading.Event()
    scheduler_failed = threading.Event()

    def worker():
        try:
            result = startup(startup_request, cancellation_boundary)
        except BaseException as exc:
            result = exc
        q.put((time.monotonic(), result))
        work_complete.set()
        while not finalization_complete.wait(JSON_SERIAL_DEFAULT_POLL_INTERVAL_SECONDS):
            if scheduler_failed.is_set():
                try:
                    on_abandoned(result)
                except Exception:
                    logger.exception("Unable to abandon controller startup safely")
                return

    def close_spinner():
        nonlocal spinner_closed
        if spinner_closed:
            return
        spinner_closed = True
        try:
            pb.stop()
        except Exception:
            logger.exception("Unable to stop the controller startup progress bar")
        try:
            spinner.grab_release()
        except Exception:
            logger.exception("Unable to release the controller startup dialog")
        try:
            spinner.destroy()
        except Exception:
            logger.exception("Unable to destroy the controller startup dialog")

    try:
        worker_thread = Thread(target=worker, daemon=True)
    except Exception:
        close_spinner()
        raise
    deadline = time.monotonic() + timeout

    def poll_worker():
        nonlocal pending_result, timed_out
        if cancelled:
            return

        if pending_result is missing:
            try:
                pending_result = q.get_nowait()
            except Empty:
                pass

        now = time.monotonic()
        completion_time = (
            pending_result[0]
            if pending_result is not missing
            else None
        )
        deadline_exceeded = (
            completion_time > deadline
            if completion_time is not None
            else now >= deadline
        )
        if not timed_out and deadline_exceeded:
            timed_out = True
            cancellation_boundary.cancel()
            close_spinner()
            try:
                on_timeout()
            except Exception:
                logger.exception("Unable to report the controller startup timeout")

        if pending_result is not missing and work_complete.is_set():
            close_spinner()
            try:
                on_finished(pending_result[1], timed_out)
            except Exception:
                logger.exception("Unable to finalize controller startup")
            finally:
                finalization_complete.set()
            return

        try:
            root.after(10, poll_worker)
        except Exception:
            logger.exception("Unable to continue controller startup polling")
            cancellation_boundary.cancel()
            if not timed_out:
                timed_out = True
                close_spinner()
                try:
                    on_timeout()
                except Exception:
                    logger.exception("Unable to report the controller startup timeout")
            scheduler_failed.set()

    try:
        poll_job = root.after(10, poll_worker)
    except Exception:
        close_spinner()
        raise
    try:
        worker_thread.start()
    except Exception:
        cancelled = True
        finalization_complete.set()
        try:
            root.after_cancel(poll_job)
        except Exception:
            logger.exception("Unable to cancel controller startup polling")
        close_spinner()
        raise
    return worker_thread


def startup(startup_request, cancellation_boundary=None):
  if not isinstance(startup_request, ControllerStartupRequest):
    raise MotionInputError("startup_request must be a ControllerStartupRequest")
  if cancellation_boundary is None:
    cancellation_boundary = SerialWriteCancellationBoundary(
      "controller startup"
    )
  if not isinstance(
    cancellation_boundary,
    SerialWriteCancellationBoundary,
  ):
    raise TypeError("controller startup cancellation boundary is invalid")
  serial_port = RUN.get('ser')
  if serial_port is None or not getattr(serial_port, "is_open", False):
    raise ConnectionError("controller serial connection is not open")

  auxiliary_serial = None
  auxiliary_error = None
  json_bootstrap = None
  try:
    configuration = (
      _prepare_main_controller_json_startup_configuration_from_request(
        startup_request
      )
    )
    if startup_request.auxiliary_port is None:
      _clear_unavailable_startup_auxiliary()
    elif startup_request.auxiliary_board is None:
      _clear_unavailable_startup_auxiliary()
      auxiliary_error = "auxiliary-board profile must be selected"
    else:
      try:
        auxiliary_serial = _connect_startup_auxiliary(
          startup_request.auxiliary_port,
          startup_request.auxiliary_board,
        )
      except Exception as exc:
        _clear_unavailable_startup_auxiliary()
        auxiliary_error = str(exc).strip() or type(exc).__name__

    json_bootstrap = run_main_controller_json_startup(
      serial_port,
      configuration,
      cancellation_boundary,
      physical_stop_callback=(
        lambda physical_stop: _publish_startup_main_controller_json_stop(
          serial_port,
          physical_stop,
        )
      ),
      request_timeout=SERIAL_STARTUP_READ_TIMEOUT_SECONDS,
      close_timeout=JSON_COORDINATOR_DEFAULT_CLOSE_TIMEOUT_SECONDS,
    )
    if type(json_bootstrap) is not JsonMainControllerPersistentStartupResult:
      raise ProtocolResponseError(
        "controller JSON startup returned an invalid result"
      )
    controller_identity = controller_identity_from_json_hello(
      json_bootstrap.hello
    )
    json_position = _json_startup_position_disposition(json_bootstrap)
    position = _json_joint_position_response(
      "JSON startup position",
      json_position,
      speed_violation=json_position.speed_limited,
      debug=json_position.controller_debug,
      flag=json_position.motion_fault,
    )
    home_reference = PrimaryHomeReference(
      valid=json_bootstrap.home_reference.valid,
      positions=json_bootstrap.home_reference.positions_degrees,
    )
    return ControllerStartupResult(
      position=position,
      visual_options=_startup_visual_options(),
      auxiliary_serial=auxiliary_serial,
      controller_identity=controller_identity,
      home_reference=home_reference,
      auxiliary_error=auxiliary_error,
      json_bootstrap=json_bootstrap,
    )
  except BaseException as operation_error:
    retained_error = (
      _retain_json_startup_disposition_error(
        json_bootstrap,
        operation_error,
        "main-controller startup failed",
      )
      if json_bootstrap is not None
      else operation_error
    )
    cleanup_error = None
    try:
      _close_persistent_json_startup_result(json_bootstrap)
    except BaseException as exc:
      cleanup_error = exc
    if auxiliary_serial is not None:
      _request_startup_auxiliary_cleanup(auxiliary_serial)
    if cleanup_error is not None:
      raise JsonMainControllerStartupCleanupError(
        retained_error,
        cleanup_error,
        (
          json_bootstrap.client
          if type(json_bootstrap) is JsonMainControllerPersistentStartupResult
          else None
        ),
      ) from cleanup_error
    if retained_error is operation_error:
      raise
    raise retained_error from operation_error




