def _controller_json_milliunit(value, field_name):
  number = finite_number(value, field_name)
  scaled = number * 1000.0
  if not math.isfinite(scaled):
    raise MotionInputError(
      f"{field_name} cannot be represented in JSON fixed-point units"
    )
  encoded = round(scaled)
  if encoded < -(2 ** 31) or encoded > (2 ** 31) - 1:
    raise MotionInputError(
      f"{field_name} exceeds the JSON fixed-point range"
    )
  if number != 0.0 and encoded == 0:
    raise MotionInputError(
      f"{field_name} is below JSON fixed-point resolution"
    )
  representation_tolerance = 2.0 * max(
    math.ulp(scaled),
    math.ulp(float(encoded)),
  )
  if abs(scaled - encoded) > representation_tolerance:
    raise MotionInputError(
      f"{field_name} is not exactly representable in JSON fixed-point units"
    )
  controller_number(encoded / 1000.0, field_name)
  return encoded


def _prepare_main_controller_json_startup_configuration(
  update_values,
  external_values,
  position_target,
  calibration_values,
):
  if not isinstance(update_values, dict):
    raise MotionInputError("JSON update-parameter values must be a dictionary")
  if not isinstance(external_values, dict):
    raise MotionInputError("JSON external-axis values must be a dictionary")
  if not isinstance(calibration_values, dict):
    raise MotionInputError("JSON calibration values must be a dictionary")
  if isinstance(position_target, (str, bytes)):
    raise MotionInputError("JSON startup position must be a numeric sequence")
  try:
    position_target = tuple(position_target)
  except TypeError as exc:
    raise MotionInputError(
      "JSON startup position must be a numeric sequence"
    ) from exc
  if len(position_target) != 9:
    raise MotionInputError("JSON startup position must contain 9 values")

  required_update_fields = (
    'TFx',
    'TFy',
    'TFz',
    'TFrx',
    'TFry',
    'TFrz',
    *tuple(
      f'J{axis}{suffix}'
      for suffix in (
        'MotDir',
        'CalDir',
        'CalSwitch',
      )
      for axis in range(1, 10)
    ),
    *tuple(
      f'J{axis}{suffix}'
      for suffix in (
        'PosLim',
        'NegLim',
        'StepDeg',
        'DriveMS',
        'EncCPR',
        'ΘDHpar',
        'αDHpar',
        'dDHpar',
        'aDHpar',
      )
      for axis in range(1, 7)
    ),
  )
  required_external_fields = (
    'J7PosLim',
    'J8length',
    'J9length',
    *tuple(
      f'J{axis}{suffix}'
      for suffix in ('rotation', 'steps')
      for axis in range(7, 10)
    ),
  )
  missing_fields = tuple(sorted(
    (
      key
      for key in required_update_fields
      if key not in update_values
    ),
  )) + tuple(sorted(
    (
      key
      for key in required_external_fields
      if key not in external_values
    ),
  ))
  if missing_fields:
    raise MotionInputError(
      "JSON startup configuration is missing required fields: "
      + ", ".join(missing_fields)
    )

  switch_states = tuple(
    update_values[f'J{axis}CalSwitch']
    for axis in range(1, 10)
  )
  encode_calibration_switch_mask(switch_states)
  encoder_counts_per_step = tuple(
    controller_ratio(
      update_values[f'J{axis}EncCPR'],
      update_values[f'J{axis}DriveMS'],
      f"J{axis} encoder multiplier",
    )
    for axis in range(1, 7)
  )
  encoded_position = tuple(
    _controller_json_milliunit(value, f"J{axis} startup position")
    for axis, value in enumerate(position_target, start=1)
  )
  _controller_joint_calibration_from_values(
    calibration_values
  ).validate_positions(
    tuple(value / 1000.0 for value in encoded_position)
  )
  return JsonMainControllerStartupConfiguration(
    tool_translation_millimeters=tuple(
      controller_number(update_values[key], f"JSON startup {key}")
      for key in ('TFx', 'TFy', 'TFz')
    ),
    tool_rotation_degrees=tuple(
      controller_number(update_values[key], f"JSON startup {key}")
      for key in ('TFrx', 'TFry', 'TFrz')
    ),
    motor_directions=tuple(
      update_values[f'J{axis}MotDir']
      for axis in range(1, 10)
    ),
    calibration_directions=tuple(
      update_values[f'J{axis}CalDir']
      for axis in range(1, 10)
    ),
    calibration_switch_active_high=tuple(
      state == "HIGH"
      for state in switch_states
    ),
    positive_joint_limits_degrees=tuple(
      controller_number(
        update_values[f'J{axis}PosLim'],
        f"JSON startup J{axis} positive limit",
      )
      for axis in range(1, 7)
    ),
    negative_joint_limits_degrees=tuple(
      controller_number(
        update_values[f'J{axis}NegLim'],
        f"JSON startup J{axis} negative limit",
      )
      for axis in range(1, 7)
    ),
    steps_per_degree=tuple(
      controller_number(
        update_values[f'J{axis}StepDeg'],
        f"JSON startup J{axis} steps per degree",
      )
      for axis in range(1, 7)
    ),
    encoder_counts_per_step=encoder_counts_per_step,
    dh_theta_degrees=tuple(
      controller_number(
        update_values[f'J{axis}ΘDHpar'],
        f"JSON startup J{axis} DH theta",
      )
      for axis in range(1, 7)
    ),
    dh_alpha_degrees=tuple(
      controller_number(
        update_values[f'J{axis}αDHpar'],
        f"JSON startup J{axis} DH alpha",
      )
      for axis in range(1, 7)
    ),
    dh_d_millimeters=tuple(
      controller_number(
        update_values[f'J{axis}dDHpar'],
        f"JSON startup J{axis} DH d",
      )
      for axis in range(1, 7)
    ),
    dh_a_millimeters=tuple(
      controller_number(
        update_values[f'J{axis}aDHpar'],
        f"JSON startup J{axis} DH a",
      )
      for axis in range(1, 7)
    ),
    external_axis_travel_units=tuple(
      controller_number(external_values[key], f"JSON startup {key}")
      for key in ('J7PosLim', 'J8length', 'J9length')
    ),
    external_axis_drive_rotations=tuple(
      controller_number(
        external_values[f'J{axis}rotation'],
        f"JSON startup J{axis} drive rotations",
      )
      for axis in range(7, 10)
    ),
    external_axis_motor_steps=tuple(
      controller_number(
        external_values[f'J{axis}steps'],
        f"JSON startup J{axis} motor steps",
      )
      for axis in range(7, 10)
    ),
    robot_joints_millidegrees=encoded_position[:6],
    external_axes_milliunits=encoded_position[6:],
  )


def _prepare_main_controller_json_startup_configuration_from_request(
  startup_request,
):
  if not isinstance(startup_request, ControllerStartupRequest):
    raise MotionInputError(
      "controller startup request is invalid for JSON configuration"
    )
  update_values = dict(startup_request.semantic_update_values)
  external_values = dict(startup_request.semantic_external_values)
  calibration_values = dict(update_values)
  calibration_values.update(external_values)
  return _prepare_main_controller_json_startup_configuration(
    update_values,
    external_values,
    startup_request.semantic_position_target,
    calibration_values,
  )


def _prepare_controller_startup():
  auxiliary_port = com2SelectedValue.get()
  auxiliary_board = auxiliaryBoardSelectedValue.get()
  (
    update_values,
    update_command,
    external_values,
    external_command,
  ) = _prepare_controller_calibration()
  merged_values = dict(CAL)
  merged_values.update(update_values)
  merged_values.update(external_values)
  _prepare_cpp_kinematics_configuration(merged_values)
  position_target = _prepare_position_target(merged_values)
  request = ControllerStartupRequest(
    auxiliary_port=auxiliary_port,
    auxiliary_board=auxiliary_board,
    update_parameters_command=update_command,
    external_axis_command=external_command,
    position_command=_position_command_from_target(position_target),
    semantic_update_values=update_values,
    semantic_external_values=external_values,
    semantic_position_target=position_target,
  )
  return request, update_values, external_values


def _clear_controller_fault_latches_after_confirmed_startup(
  serial_port,
  position,
):
  if (
    not isinstance(position, PositionResponse)
    or position.flag
    or _current_main_controller_identity(serial_port) is None
  ):
    raise ProtocolResponseError(
      "controller fault latches require a bound fault-free startup position"
    )
  with auxiliary_stop_state_lock:
    with program_stop_state_lock:
      RUN['estopActive'] = False
      RUN['mainControllerStopPositionUnavailable'] = False
      RUN['posOutreach'] = False
      if _program_execution_stop_admission_reason_locked() is None:
        RUN['programStopStatusLatched'] = False
        RUN['programStopState'] = "completed"
  return True


def _controller_startup_cleanup_json_client(result):
  if isinstance(result, ControllerStartupResult):
    json_bootstrap = result.json_bootstrap
    client = (
      json_bootstrap.client
      if type(json_bootstrap) is JsonMainControllerPersistentStartupResult
      else None
    )
  elif isinstance(result, JsonMainControllerStartupCleanupError):
    client = result.client
  else:
    client = None
  if client is not None and type(client) is not JsonMainControllerClient:
    raise TypeError("controller startup cleanup client is invalid")
  return client


def _apply_controller_startup_result(
  startup_request,
  result,
  update_values,
  external_values,
  startup_serial,
  original_startup_timeout,
):
  calibration_applied = False
  try:
    json_bootstrap = getattr(result, "json_bootstrap", None)
    json_position = _json_startup_position_disposition(json_bootstrap)
    if result.position.flag:
      raise ProtocolResponseError(f"controller reported a startup fault: {result.position.flag}")
    staged_values = dict(CAL)
    staged_values.update(update_values)
    staged_values.update(external_values)
    staged_calibration = _controller_joint_calibration_from_values(staged_values)
    staged_calibration.validate_positions(
      result.position.joints + result.position.external
    )
    _apply_controller_calibration(update_values, external_values)
    calibration_applied = True
    applied_position = displayPosition(
      result.position.raw,
      parsed=result.position,
    )
    if applied_position is None:
      raise ProtocolResponseError(
        "controller startup position could not be applied"
      )
    if json_position is not None:
      startup_debug = result.position.debug or json_position.controller_debug
      if startup_debug != result.position.debug:
        manEntryField.delete(0, 'end')
        manEntryField.insert(0, startup_debug)
      if json_position.speed_limited and not result.position.speed_violation:
        message = (
          "Max Speed Violation - Reduce Speed Setpoint or Travel Distance"
        )
        logger.warning(message)
        value = tab8.ElogView.get(0, END)
        with open("ErrorLog", "wb") as error_log:
          pickle.dump(value, error_log)
        _set_application_status(text=message, style="Warn.TLabel")
    updateVisOp(result.visual_options)
    startup_serial.timeout = original_startup_timeout
    value = tab8.ElogView.get(0, END)
    with open("ErrorLog", "wb") as error_log:
      pickle.dump(value, error_log)
    CAL['com2Port'] = startup_request.auxiliary_port
    CAL['auxiliaryBoard'] = (
      startup_request.auxiliary_board or AUXILIARY_BOARD_NONE
    )
    if type(json_bootstrap) is not JsonMainControllerPersistentStartupResult:
      raise ProtocolResponseError(
        "controller startup lacks a persistent JSON binding"
      )
    _bind_main_controller_identity(
      startup_serial,
      result.controller_identity,
      result.home_reference,
      json_bootstrap.configuration,
      json_bootstrap.client,
    )
    _clear_controller_fault_latches_after_confirmed_startup(
      startup_serial,
      result.position,
    )
  except Exception as operation_error:
    if calibration_applied:
      try:
        _invalidate_joint_motion_state(
          "controller startup finalization failed after staged calibration "
          "was applied"
        )
      except Exception:
        logger.exception(
          "Unable to invalidate motion after controller startup finalization"
        )
    json_bootstrap = getattr(result, "json_bootstrap", None)
    retained_error = (
      _retain_json_startup_disposition_error(
        json_bootstrap,
        operation_error,
        "main-controller startup finalization failed",
      )
      if json_bootstrap is not None
      else operation_error
    )
    if retained_error is operation_error:
      raise
    raise retained_error from operation_error
  return applied_position


def _main_port_selector_value(port):
  if (
    not isinstance(port, str)
    or not port
    or port != port.strip()
  ):
    raise MotionInputError(
      "accepted main-controller port selection must be normalized text"
    )
  return port


def _commit_main_port_enrollment(port, identity):
  staged = snapshot_calibration_values(CAL)
  staged['comPort'] = _main_port_selector_value(port)
  staged['mainControllerPortIdentity'] = identity
  snapshot = normalize_calibration_data(staged)
  CAL['comPort'] = snapshot['comPort']
  CAL['mainControllerPortIdentity'] = snapshot['mainControllerPortIdentity']
  if not _retain_calibration_persistence_retry(snapshot):
    logger.error("Main-controller port enrollment persistence remains pending")


def setCom(misc=None):
  previous_main_port = CAL.get('comPort', "None")
  previous_main_port = (
    previous_main_port.strip()
    if isinstance(previous_main_port, str)
    else "None"
  ) or "None"
  restored_main_port = _main_port_selector_value(previous_main_port)
  automatic_startup = misc is None
  if automatic_startup:
    main_resolution = resolve_main_identity(
      serial_port_inventory, CAL.get('mainControllerPortIdentity', "None"),
    )
    auxiliary_resolution = resolve_auxiliary_identity(
      serial_port_inventory, CAL.get('auxiliaryControllerPortIdentity', "None"),
    )
    com2SelectedValue.set(
      auxiliary_resolution.record.device
      if auxiliary_resolution.status == "selected" else "None"
    )
    if main_resolution.status != "selected":
      com1SelectedValue.set("None")
      _set_application_status(
        f"MAIN CONTROLLER {main_resolution.status.upper()}; CONNECTION NOT STARTED",
        "Warn.TLabel",
      )
      return False
    selected_main_record = main_resolution.record
    com1SelectedValue.set(selected_main_record.device)
    auxiliary_discovery_status = auxiliary_resolution.status
  else:
    selected_main_port = _main_port_selector_value(com1SelectedValue.get())
    if selected_main_port == "None":
      selected_main_record = None
    else:
      main_resolution = resolve_selected_device(
        serial_port_inventory,
        selected_main_port,
      )
      if main_resolution.status != "selected":
        com1SelectedValue.set(restored_main_port)
        _set_application_status(
          f"MAIN CONTROLLER {main_resolution.status.upper()}; CONNECTION NOT CHANGED",
          "Warn.TLabel",
        )
        return False
      selected_main_record = main_resolution.record
    auxiliary_discovery_status = None
    selected_auxiliary_port = com2SelectedValue.get()
    if selected_main_record is not None and selected_auxiliary_port != "None":
      auxiliary_resolution = resolve_selected_device(
        serial_port_inventory, selected_auxiliary_port,
      )
      if auxiliary_resolution.status != "selected":
        com1SelectedValue.set(restored_main_port)
        _set_application_status(
          f"AUXILIARY CONTROLLER {auxiliary_resolution.status.upper()}; CONNECTION NOT CHANGED",
          "Warn.TLabel",
        )
        return False
  selected_main_port = (
    selected_main_record.device if selected_main_record else "None"
  )
  selected_main_identity = (
    port_identity(selected_main_record)
    if selected_main_record is not None
    and (
      selected_main_record.vid,
      selected_main_record.pid,
    ) == MAIN_CONTROLLER_USB_ID
    else None
  ) or "None"
  request_lease = _acquire_motion_request(
    "Controller connection change",
    allow_position_recovery=True,
    requires_kinematics=False,
  )
  if request_lease is None:
    message = _motion_request_rejection_message(
      "Controller connection change not started"
    )
    try:
      com1SelectedValue.set(restored_main_port)
    except Exception:
      logger.exception(
        "Unable to restore the accepted main-controller port selection"
      )
    _set_application_status(message, "Warn.TLabel")
    return False
  request_state = {"transferred": False}
  try:
    return _set_com_admitted(
      request_lease,
      request_state,
      previous_main_port=previous_main_port,
      selected_main_port=selected_main_port,
      selected_main_identity=selected_main_identity,
      auxiliary_discovery_status=auxiliary_discovery_status,
    )
  finally:
    if (
      not request_state["transferred"]
      and motion_request_registry.owns(request_lease)
    ):
      _finish_motion_request(request_lease)


def _set_com_admitted(
  request_lease,
  request_state,
  *,
  previous_main_port,
  selected_main_port,
  selected_main_identity,
  auxiliary_discovery_status,
):
  if (
    not isinstance(previous_main_port, str)
    or not previous_main_port
    or previous_main_port != previous_main_port.strip()
  ):
    raise MotionInputError(
      "accepted main-controller port selection must be normalized text"
    )
  restored_main_port = _main_port_selector_value(previous_main_port)

  def restore_port_selection():
    try:
      com1SelectedValue.set(restored_main_port)
    except Exception:
      logger.exception(
        "Unable to restore the accepted main-controller port selection"
      )

  if application_closing.is_set():
    restore_port_selection()
    logger.warning("Controller connection change rejected during application shutdown")
    return False
  if not serial_lock.acquire(blocking=False):
    restore_port_selection()
    message = "Controller connection change rejected while the transport is busy"
    logger.warning(message)
    _set_application_status(message, "Warn.TLabel")
    return False
  with manual_controller_cleanup_lock:
    cleanup_pending = manual_controller_cleanup_pending is not None
  if cleanup_pending:
    serial_lock.release()
    restore_port_selection()
    message = (
      "Controller connection change rejected while controller I/O "
      "cleanup is pending"
    )
    logger.warning(message)
    _set_application_status(message, "Warn.TLabel")
    return False
  try:
    activity_lease = serial_activity_registry.lease("ser")
  except SerialActivityRejected as exc:
    serial_lock.release()
    restore_port_selection()
    detail = str(exc).strip() or type(exc).__name__
    message = f"Controller connection change rejected: {detail}"
    logger.warning(message)
    _set_application_status(message, "Warn.TLabel")
    return False
  except Exception:
    serial_lock.release()
    restore_port_selection()
    raise
  release_transport = True
  try:
    baud = 9600

    existing_serial = RUN.get('ser')
    if existing_serial is not None:
      existing_was_open = getattr(existing_serial, "is_open", False)
      if not _close_serial_port(
        'ser',
        "controller connection replacement",
      ):
        raise OSError("Existing Teensy serial connection remained open")
      if existing_was_open:
        time.sleep(0.2)  # Windows can retain a just-closed COM handle briefly.

    if selected_main_port == "None":
      _commit_main_port_enrollment("None", "None")
      _set_application_status("MAIN CONTROLLER DISABLED", "Warn.TLabel")
      return True
    # Command-specific read deadlines are applied by the owned transport path.
    RUN['ser'] = serial.Serial(
      port=selected_main_port,
      baudrate=baud,
      timeout=None,
      write_timeout=SERIAL_WRITE_TIMEOUT_SECONDS,
    )
    logger.info(
      "COMMUNICATIONS STARTED WITH TEENSY 4.1 CONTROLLER on Port %s",
      selected_main_port,
    )

    _set_application_status("CONTROLLER STARTING", "Warn.TLabel")

    time.sleep(.1)
    # Prefer reset_input_buffer over deprecated flushInput
    try:
      RUN['ser'].reset_input_buffer()
      RUN['ser'].reset_output_buffer()
    except Exception as exc:
      raise OSError("Unable to reset controller serial buffers") from exc

    (
      startup_request,
      startup_update_values,
      startup_external_values,
    ) = _prepare_controller_startup()
    startup_serial = RUN['ser']
    original_startup_timeout = startup_serial.timeout
    startup_serial.timeout = SERIAL_STARTUP_READ_TIMEOUT_SECONDS

    def set_startup_status(message, style):
      try:
        _set_application_status(message, style)
      except Exception:
        logger.exception("Unable to update controller startup status")

    def report_startup_timeout():
      restore_port_selection()
      message = "CONTROLLER STARTUP TIMED OUT; WAITING FOR CLEANUP"
      logger.error(message)
      set_startup_status(message, "Alarm.TLabel")

    def finish_startup(result, timed_out):
      startup_json_client = _controller_startup_cleanup_json_client(result)
      if RUN.get('ser') is not startup_serial:
        restore_port_selection()
        logger.error("Main serial reference changed during controller startup")
        if isinstance(result, ControllerStartupResult):
          _request_startup_auxiliary_cleanup(result.auxiliary_serial)
        _poll_failed_controller_close(
          startup_serial,
          activity_lease,
          request_lease,
          startup_json_client,
        )
        return

      if (
        timed_out
        or isinstance(result, BaseException)
        or not isinstance(result, ControllerStartupResult)
      ):
        restore_port_selection()
        if isinstance(result, BaseException) and not (
          timed_out and isinstance(result, TimeoutError)
        ):
          logger.error(
            "Startup failed while initializing Teensy 4.1 controller",
            exc_info=(type(result), result, result.__traceback__),
          )
        elif not isinstance(result, (BaseException, ControllerStartupResult)):
          logger.error("Controller startup worker returned an invalid result")
        if isinstance(result, ControllerStartupResult):
          _request_startup_auxiliary_cleanup(result.auxiliary_serial)
        message = (
          "CONTROLLER STARTUP TIMED OUT; CONNECTION CLOSING"
          if timed_out
          else "UNABLE TO ESTABLISH COMMUNICATIONS WITH TEENSY 4.1 CONTROLLER"
        )
        set_startup_status(message, "Alarm.TLabel")
        _poll_failed_controller_close(
          startup_serial,
          activity_lease,
          request_lease,
          startup_json_client,
        )
        return

      try:
        if not getattr(startup_serial, "is_open", False):
          raise OSError("Teensy serial connection closed during startup")
        startup_position = _apply_controller_startup_result(
          startup_request,
          result,
          startup_update_values,
          startup_external_values,
          startup_serial,
          original_startup_timeout,
        )
        logger.info("COMMUNICATIONS STARTED WITH TEENSY 4.1 CONTROLLER")
        if result.auxiliary_error is not None:
          logger.warning(
            "Auxiliary controller unavailable during main startup: %s",
            result.auxiliary_error,
          )
        json_position = _json_startup_position_disposition(
          getattr(result, "json_bootstrap", None)
        )
        if not (
          startup_position.speed_violation
          or (
            json_position is not None
            and json_position.speed_limited
          )
        ):
          if result.auxiliary_error is not None:
            set_startup_status(
              "CONTROLLER CALIBRATION REQUIRED; "
              "AUXILIARY CONTROLLER UNAVAILABLE",
              "Warn.TLabel",
            )
          elif auxiliary_discovery_status not in (None, "selected"):
            set_startup_status(
              "CONTROLLER CALIBRATION REQUIRED; AUXILIARY CONTROLLER "
              f"{auxiliary_discovery_status.upper()}",
              "Warn.TLabel",
            )
          elif startup_request.auxiliary_port is None:
            set_startup_status(
              "CONTROLLER CALIBRATION REQUIRED; "
              "AUXILIARY CONTROLLER NOT CONFIGURED",
              "Warn.TLabel",
            )
          else:
            set_startup_status(
              "CONTROLLER CALIBRATION REQUIRED",
              "Warn.TLabel",
            )
        _commit_main_port_enrollment(
          selected_main_port,
          selected_main_identity,
        )
      except Exception:
        restore_port_selection()
        logger.exception("Unable to finalize the Teensy 4.1 controller connection")
        _request_startup_auxiliary_cleanup(result.auxiliary_serial)
        message = "UNABLE TO ESTABLISH COMMUNICATIONS WITH TEENSY 4.1 CONTROLLER"
        set_startup_status(message, "Alarm.TLabel")
        _poll_failed_controller_close(
          startup_serial,
          activity_lease,
          request_lease,
          startup_json_client,
        )
        return
      _release_async_main_serial_transport(activity_lease, request_lease)

    def abandon_startup(result):
      startup_json_client = _controller_startup_cleanup_json_client(result)
      if isinstance(result, ControllerStartupResult):
        _request_startup_auxiliary_cleanup(result.auxiliary_serial)
      _abandon_failed_controller_startup(
        startup_serial,
        activity_lease,
        request_lease,
        startup_json_client,
      )

    release_transport = False
    try:
      startup_with_spinner(
        root,
        startup_request,
        finish_startup,
        report_startup_timeout,
        abandon_startup,
        timeout=(
          SERIAL_STARTUP_READ_TIMEOUT_SECONDS
          + (
            AUXILIARY_CONTROLLER_RESET_SETTLE_SECONDS
            if (
              startup_request.auxiliary_port is not None
              and startup_request.auxiliary_board is not None
            )
            else 0.0
          )
        ),
      )
      request_state["transferred"] = True
    except Exception:
      release_transport = True
      raise
    return True

  except Exception:
    restore_port_selection()
    failed_serial = RUN.get('ser')
    if failed_serial is not None:
      release_transport = False
      _poll_failed_controller_close(
        failed_serial,
        activity_lease,
        request_lease,
      )
      request_state["transferred"] = True

    logger.exception(
      "UNABLE TO ESTABLISH COMMUNICATIONS WITH TEENSY 4.1 CONTROLLER"
    )

    _set_application_status(
      "UNABLE TO ESTABLISH COMMUNICATIONS WITH TEENSY 4.1 CONTROLLER",
      "Alarm.TLabel",
    )

    try:
      value = tab8.ElogView.get(0, END)
      pickle.dump(value, open("ErrorLog", "wb"))
    except Exception:
      logger.exception("Unable to persist the controller startup error log")
    return False
  finally:
    if release_transport:
      _release_async_main_serial_transport(activity_lease, request_lease)


def _close_auxiliary_replacement(serial_port, json_client, context):
  cleanup_error = None
  try:
    if json_client is None:
      serial_port.close()
    else:
      _require_persistent_json_client_cleanup(
        json_client,
        serial_port,
        context,
      )
  except Exception as exc:
    cleanup_error = exc
    try:
      serial_port.close()
    except Exception:
      logger.exception("Unable to close the auxiliary replacement transport")
    if json_client is not None:
      try:
        _require_persistent_json_client_cleanup(
          json_client,
          serial_port,
          f"{context} retry",
        )
      except Exception:
        logger.exception("Auxiliary replacement cleanup retry failed")
  if (
    (json_client is not None and not json_client.closed)
    or getattr(serial_port, "is_open", False)
  ):
    _request_startup_auxiliary_cleanup(serial_port, json_client)
  if (
    (json_client is not None and not json_client.closed)
    or getattr(serial_port, "is_open", False)
  ):
    raise OSError("Auxiliary replacement cleanup remained incomplete") from cleanup_error
  if cleanup_error is not None:
    logger.error(
      "Auxiliary replacement cleanup recovered after an initial failure",
      exc_info=(type(cleanup_error), cleanup_error, cleanup_error.__traceback__),
    )
  return True


def _prepare_auxiliary_serial(port, board_profile):
  if not isinstance(port, str):
    raise MotionInputError("auxiliary controller port must be text")
  port = port.strip()
  if port in ("", "None"):
    raise MotionInputError("no auxiliary controller port selected")
  board_profile = normalize_auxiliary_board_profile(board_profile)
  replacement = serial.Serial(
    port=port,
    baudrate=9600,
    timeout=SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS,
    write_timeout=SERIAL_WRITE_TIMEOUT_SECONDS,
  )
  if not getattr(replacement, "is_open", False):
    try:
      replacement.close()
    finally:
      raise OSError("Auxiliary serial connection did not open")
  json_client = None
  try:
    # Arduino USB serial adapters reset the controller when the port opens.
    # Discard bootloader-era bytes before the first strict JSON request.
    time.sleep(AUXILIARY_CONTROLLER_RESET_SETTLE_SECONDS)
    replacement.reset_input_buffer()
    replacement.reset_output_buffer()
    json_client = JsonAuxiliaryControllerClient(replacement)
    hello_ticket = json_client.request_hello(
      timeout=SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS,
    )
    _await_auxiliary_json_terminal(
      json_client,
      hello_ticket,
      "hello",
    )
  except BaseException:
    try:
      _close_auxiliary_replacement(
        replacement,
        json_client,
        "auxiliary preparation failure",
      )
    except Exception as cleanup_error:
      raise OSError(
        "Auxiliary preparation failed and cleanup remained incomplete"
      ) from cleanup_error
    raise
  return replacement, board_profile, json_client


def _publish_auxiliary_serial(replacement, board_profile, json_client):
  existing_serial = RUN.get('ser2')
  if existing_serial is not None and not _close_serial_port(
    'ser2', "auxiliary connection replacement",
  ):
    try:
      _close_auxiliary_replacement(
        replacement,
        json_client,
        "unpublished auxiliary replacement",
      )
    except Exception as cleanup_error:
      raise OSError(
        "Existing auxiliary connection remained open and replacement cleanup failed"
      ) from cleanup_error
    raise OSError("Existing auxiliary serial connection remained open")

  RUN['ser2'] = replacement
  try:
    _bind_auxiliary_board_profile(
      replacement,
      board_profile,
      json_client,
    )
  except Exception:
    _close_auxiliary_replacement(
      replacement,
      json_client,
      "auxiliary publication failure",
    )
    _clear_auxiliary_board_profile(replacement)
    if RUN.get('ser2') is replacement:
      RUN['ser2'] = None
    raise
  return replacement


def _replace_auxiliary_serial(port, board_profile):
  normalized_board = normalize_auxiliary_board_profile(board_profile)
  existing_serial = RUN.get('ser2')
  if (
    isinstance(port, str)
    and existing_serial is not None
    and getattr(existing_serial, "is_open", False)
    and getattr(existing_serial, "port", None) == port.strip()
  ):
    try:
      existing_board = _connected_auxiliary_board_profile(existing_serial)
    except (ConnectionError, MotionInputError) as exc:
      logger.warning(
        "Existing auxiliary connection cannot be reused: %s",
        exc,
      )
      existing_board = None
    if existing_board == normalized_board:
      return existing_serial
    if existing_board is not None:
      logger.warning(
        "Existing auxiliary board %s does not match selected board %s",
        existing_board,
        normalized_board,
      )
    if not _close_serial_port(
      'ser2',
      "same-port auxiliary reconnection",
    ):
      raise OSError("Existing auxiliary serial connection remained open")
  return _publish_auxiliary_serial(
    *_prepare_auxiliary_serial(port, normalized_board)
  )


def _auxiliary_output_field_bindings():
  return (
    ('DO1on', DO1onEntryField),
    ('DO1off', DO1offEntryField),
    ('DO2on', DO2onEntryField),
    ('DO2off', DO2offEntryField),
    ('DO3on', DO3onEntryField),
    ('DO3off', DO3offEntryField),
    ('DO4on', DO4onEntryField),
    ('DO4off', DO4offEntryField),
    ('DO5on', DO5onEntryField),
    ('DO5off', DO5offEntryField),
    ('DO6on', DO6onEntryField),
    ('DO6off', DO6offEntryField),
  )


def _read_auxiliary_output_field_values():
  return {
    key: field.get()
    for key, field in _auxiliary_output_field_bindings()
  }


def _replace_auxiliary_output_field_values(values):
  if not isinstance(values, dict):
    raise MotionInputError("auxiliary output values must be a dictionary")
  bindings = _auxiliary_output_field_bindings()
  previous = {
    key: field.get()
    for key, field in bindings
  }
  try:
    for key, field in bindings:
      if key not in values:
        continue
      field.delete(0, 'end')
      field.insert(0, str(values[key]))
  except Exception as exc:
    rollback_failed = False
    for key, field in bindings:
      try:
        field.delete(0, 'end')
        field.insert(0, previous[key])
      except Exception:
        rollback_failed = True
        logger.exception(
          "Unable to restore an auxiliary output field after update failure"
        )
    if rollback_failed:
      raise RuntimeError(
        "auxiliary output field update and rollback failed"
      ) from exc
    raise
  return previous


def _cancel_auxiliary_calibration_persistence_job():
  global _calibration_save_job

  pending_job = _calibration_save_job
  if pending_job is None:
    return False
  root.after_cancel(pending_job)
  if _calibration_save_job is not pending_job:
    raise RuntimeError(
      "calibration persistence job changed during auxiliary fencing"
    )
  _calibration_save_job = None
  return True


def _begin_auxiliary_calibration_persistence_fence(calibration_snapshot):
  global _calibration_save_snapshot

  if not isinstance(calibration_snapshot, dict):
    raise MotionInputError("auxiliary calibration snapshot must be a dictionary")
  if not isinstance(_calibration_dirty, bool):
    raise RuntimeError("calibration persistence dirty state is invalid")
  if _calibration_save_job is not None and not _calibration_dirty:
    logger.error(
      "Cancelling an auxiliary calibration persistence job without dirty state"
    )
  _cancel_auxiliary_calibration_persistence_job()
  if not _calibration_dirty:
    _calibration_save_snapshot = None
    return False, None
  if _calibration_save_snapshot is None:
    persistence_snapshot = dict(calibration_snapshot)
  else:
    persistence_snapshot = normalize_calibration_data(
      snapshot_calibration_values(_calibration_save_snapshot)
    )
  return True, persistence_snapshot


def _reconcile_auxiliary_calibration_persistence_after_settle_failure(
  persistence_required,
  persistence_snapshot,
  safe_snapshot,
):
  global _calibration_dirty, _calibration_save_job
  global _calibration_save_snapshot

  if not isinstance(persistence_required, bool):
    raise TypeError("calibration persistence requirement must be boolean")
  safe_snapshot = normalize_calibration_data(
    snapshot_calibration_values(safe_snapshot)
  )
  if persistence_snapshot is not None:
    persistence_snapshot = normalize_calibration_data(
      snapshot_calibration_values(persistence_snapshot)
    )
  if not persistence_required and persistence_snapshot is not None:
    raise TypeError(
      "clean calibration persistence cannot carry a recovery snapshot"
    )
  pending_job = _calibration_save_job
  _calibration_dirty = False
  _calibration_save_snapshot = None
  cancellation_failed = False
  if pending_job is not None:
    try:
      root.after_cancel(pending_job)
    except Exception:
      cancellation_failed = True
      logger.exception(
        "Unable to cancel calibration persistence after auxiliary settle failure"
      )
      if _calibration_save_job is None:
        _calibration_save_job = pending_job
    else:
      if _calibration_save_job is not pending_job:
        cancellation_failed = True
        logger.error(
          "Calibration persistence ownership changed during settle recovery"
        )
      else:
        _calibration_save_job = None
    if cancellation_failed:
      # An armed callback needs a verified payload and dirty state until firing.
      _calibration_dirty = True
      _calibration_save_snapshot = (
        persistence_snapshot
        if persistence_required and persistence_snapshot is not None
        else safe_snapshot
      )
      return False
  if not persistence_required:
    return True
  retained = _retain_calibration_persistence_retry(
    persistence_snapshot
  )
  if not isinstance(retained, bool):
    raise RuntimeError(
      "calibration persistence retention returned an invalid result"
    )
  return retained


def _finish_auxiliary_calibration_persistence_fence(
  previous_dirty,
  previous_persistence_snapshot,
  state_changed,
  state_verified,
):
  global _calibration_dirty, _calibration_save_snapshot

  if not isinstance(previous_dirty, bool):
    raise TypeError("prior calibration persistence state must be boolean")
  if previous_dirty:
    if not isinstance(previous_persistence_snapshot, dict):
      raise TypeError(
        "prior calibration persistence snapshot must be a dictionary"
      )
  elif previous_persistence_snapshot is not None:
    raise TypeError(
      "clean calibration persistence cannot carry a pending snapshot"
    )
  if not isinstance(state_changed, bool):
    raise TypeError("auxiliary configuration change state must be boolean")
  if not isinstance(state_verified, bool):
    raise TypeError("auxiliary configuration verification state must be boolean")
  if not state_verified:
    _cancel_auxiliary_calibration_persistence_job()
    if previous_dirty:
      retained = _retain_calibration_persistence_retry(
        previous_persistence_snapshot
      )
      if not isinstance(retained, bool):
        raise RuntimeError(
          "calibration persistence retention returned an invalid result"
        )
      if not retained:
        raise RuntimeError(
          "auxiliary calibration persistence retry was not retained"
        )
      return
    _calibration_dirty = False
    _calibration_save_snapshot = None
    return
  _cancel_auxiliary_calibration_persistence_job()
  if state_changed:
    retained = _retain_calibration_persistence_retry()
    if not isinstance(retained, bool):
      raise RuntimeError(
        "calibration persistence retention returned an invalid result"
      )
    if not retained:
      raise RuntimeError(
        "auxiliary calibration persistence retry was not retained"
      )
    return
  if previous_dirty:
    retained = _retain_calibration_persistence_retry(
      previous_persistence_snapshot
    )
    if not isinstance(retained, bool):
      raise RuntimeError(
        "calibration persistence retention returned an invalid result"
      )
    if not retained:
      raise RuntimeError(
        "auxiliary calibration persistence retry was not retained"
      )
    return
  _calibration_dirty = False
  _calibration_save_snapshot = None


def _apply_auxiliary_configuration_snapshot_contents(
  calibration_snapshot,
  output_values,
  port,
  board,
):
  if not isinstance(calibration_snapshot, dict):
    raise MotionInputError("auxiliary calibration snapshot must be a dictionary")
  if not isinstance(output_values, dict):
    raise MotionInputError("auxiliary output snapshot must be a dictionary")
  if not isinstance(port, str):
    raise MotionInputError("auxiliary port snapshot must be text")
  normalized_board = normalize_auxiliary_board_profile(
    board,
    allow_none=True,
  ) or AUXILIARY_BOARD_NONE
  normalized_calibration = normalize_calibration_data(
    calibration_snapshot
  )
  normalized_output_values = {
    key: str(output_values.get(key, ""))
    for key, _ in _auxiliary_output_field_bindings()
  }

  errors = []
  try:
    apply_calibration(normalized_calibration, CAL)
    for key in tuple(CAL):
      if key not in normalized_calibration:
        del CAL[key]
  except Exception as exc:
    errors.append(f"live calibration update failed: {exc}")
  try:
    _replace_auxiliary_output_field_values(normalized_output_values)
  except Exception as exc:
    errors.append(f"output field update failed: {exc}")
  try:
    com2SelectedValue.set(port)
  except Exception as exc:
    errors.append(f"port selection update failed: {exc}")
  try:
    auxiliaryBoardSelectedValue.set(normalized_board)
  except Exception as exc:
    errors.append(f"board selection update failed: {exc}")
  if errors:
    raise RuntimeError("; ".join(errors))
  return True


def _apply_auxiliary_configuration_snapshot(
  calibration_snapshot,
  output_values,
  port,
  board,
  require_stop_admission=False,
):
  if not isinstance(require_stop_admission, bool):
    raise TypeError("auxiliary stop-admission requirement must be boolean")

  with manual_auxiliary_state_lock:
    if not require_stop_admission:
      return _apply_auxiliary_configuration_snapshot_contents(
        calibration_snapshot,
        output_values,
        port,
        board,
      )
    with auxiliary_stop_state_lock:
      with program_stop_state_lock:
        stop_reason = _stop_admission_reason_locked(
          "AUXILIARY CONFIGURATION"
        )
        if stop_reason is not None:
          raise MotionInputError(stop_reason)
        return _apply_auxiliary_configuration_snapshot_contents(
          calibration_snapshot,
          output_values,
          port,
          board,
        )


def _verify_auxiliary_configuration_snapshot(
  calibration_snapshot,
  output_values,
  port,
  board,
):
  expected_calibration = normalize_calibration_data(calibration_snapshot)
  observed_calibration = normalize_calibration_data(
    snapshot_calibration_values(CAL)
  )
  if observed_calibration != expected_calibration:
    raise RuntimeError(
      "live calibration does not match the auxiliary configuration"
    )
  expected_output_values = {
    key: str(output_values.get(key, ""))
    for key, _ in _auxiliary_output_field_bindings()
  }
  observed_output_values = _read_auxiliary_output_field_values()
  if observed_output_values != expected_output_values:
    raise RuntimeError(
      "output fields do not match the auxiliary configuration"
    )
  observed_port = com2SelectedValue.get()
  if observed_port != port:
    raise RuntimeError(
      "port selection does not match the auxiliary configuration"
    )
  expected_board = normalize_auxiliary_board_profile(
    board,
    allow_none=True,
  ) or AUXILIARY_BOARD_NONE
  observed_board = normalize_auxiliary_board_profile(
    auxiliaryBoardSelectedValue.get(),
    allow_none=True,
  ) or AUXILIARY_BOARD_NONE
  if observed_board != expected_board:
    raise RuntimeError(
      "board selection does not match the auxiliary configuration"
    )
  return True


@_synchronous_motion_request(
  "Auxiliary connection change",
  requires_kinematics=False,
)
def setCom2(misc=None):
  if application_closing.is_set():
    logger.warning(
      "Auxiliary connection change rejected during application shutdown"
    )
    return False
  selected_port = com2SelectedValue.get()
  if not isinstance(selected_port, str):
    raise MotionInputError("auxiliary controller port must be text")
  selected_port = selected_port.strip()
  selected_record = None
  if selected_port not in ("", "None"):
    selected_resolution = resolve_selected_device(
      serial_port_inventory,
      selected_port,
    )
    if selected_resolution.status != "selected":
      com2SelectedValue.set(CAL.get('com2Port', "None"))
      _set_application_status(
        f"AUXILIARY CONTROLLER {selected_resolution.status.upper()}; CONNECTION NOT CHANGED",
        "Warn.TLabel",
      )
      return False
    selected_record = selected_resolution.record
    selected_port = selected_record.device
  if not auxiliary_serial_lock.acquire(blocking=False):
    logger.warning("Auxiliary connection change rejected while the transport is busy")
    return False
  try:
    with manual_auxiliary_state_lock:
      with auxiliary_stop_state_lock:
        with program_stop_state_lock:
          stop_reason = _stop_admission_reason_locked(
            "AUXILIARY CONFIGURATION"
          )
  except Exception:
    logger.exception(
      "Auxiliary connection change could not verify stop admission"
    )
    auxiliary_serial_lock.release()
    return False
  if stop_reason is not None:
    logger.warning(stop_reason)
    auxiliary_serial_lock.release()
    return False
  try:
    previous_calibration = normalize_calibration_data(
      snapshot_calibration_values(CAL)
    )
    previous_output_values = _read_auxiliary_output_field_values()
  except Exception:
    logger.exception(
      "Auxiliary connection change found invalid live configuration values"
    )
    auxiliary_serial_lock.release()
    return False
  try:
    (
      previous_persistence_dirty,
      previous_persistence_snapshot,
    ) = (
      _begin_auxiliary_calibration_persistence_fence(
        previous_calibration
      )
    )
  except Exception:
    logger.exception(
      "Auxiliary connection change could not fence calibration persistence"
    )
    auxiliary_serial_lock.release()
    return False
  previous_serial = RUN.get('ser2')
  staged_calibration = None
  connection_change_completed = False
  prepared_auxiliary_connection = None
  try:
    if selected_port in ("", "None"):
      selected_port = None
    selected_board = normalize_auxiliary_board_profile(
      auxiliaryBoardSelectedValue.get(),
      allow_none=True,
    )
    committed_port = selected_port or "None"
    committed_board = selected_board or AUXILIARY_BOARD_NONE
    staged_calibration = dict(previous_calibration)
    staged_calibration.update(previous_output_values)
    staged_calibration['com2Port'] = committed_port
    identity = (
      port_identity(selected_record)
      if selected_record and selected_board
      else None
    )
    staged_calibration['auxiliaryControllerPortIdentity'] = identity or "None"
    staged_calibration = reconcile_auxiliary_output_assignments(
      staged_calibration,
      committed_board,
    )
    staged_calibration = normalize_calibration_data(staged_calibration)
    if selected_port is not None and selected_board is not None:
      if (
        previous_serial is not None
        and getattr(previous_serial, "is_open", False)
        and getattr(previous_serial, "port", None) == selected_port
      ):
        with manual_auxiliary_state_lock:
          with auxiliary_stop_state_lock:
            with program_stop_state_lock:
              stop_reason = _stop_admission_reason_locked(
                "AUXILIARY CONFIGURATION"
              )
              if stop_reason is not None:
                raise MotionInputError(stop_reason)
              if RUN.get('ser2') is not previous_serial:
                raise RuntimeError(
                  "auxiliary connection changed before same-port reconnect"
                )
              if not _close_serial_port(
                'ser2',
                "same-port auxiliary reconnection",
              ):
                raise OSError(
                  "Existing auxiliary serial connection remained open"
                )
          previous_serial = None
      # Opening an Arduino serial adapter resets the controller. Complete
      # boot settlement before entering the physical-stop publication lock.
      prepared_auxiliary_connection = _prepare_auxiliary_serial(
        selected_port,
        selected_board,
      )
    with manual_auxiliary_state_lock:
      with auxiliary_stop_state_lock:
        with program_stop_state_lock:
          stop_reason = _stop_admission_reason_locked(
            "AUXILIARY CONFIGURATION"
          )
          if stop_reason is not None:
            raise MotionInputError(stop_reason)

          # Stop admission, transport replacement, and live publication share
          # one boundary. A physical stop therefore observes either the prior
          # bound controller or the verified replacement, never staged UI data.
          if selected_port is None or selected_board is None:
            if RUN.get('ser2') is not None and not _close_serial_port(
              'ser2',
              "auxiliary configuration change",
            ):
              raise OSError("Unable to close the prior auxiliary connection")
            _clear_auxiliary_board_profile()
            connection_change_completed = True
          else:
            replacement, profile, json_client = prepared_auxiliary_connection
            prepared_auxiliary_connection = None
            _publish_auxiliary_serial(
              replacement,
              profile,
              json_client,
            )
            connection_change_completed = True

          _apply_auxiliary_configuration_snapshot_contents(
            staged_calibration,
            staged_calibration,
            committed_port,
            committed_board,
          )
          _verify_auxiliary_configuration_snapshot(
            staged_calibration,
            staged_calibration,
            committed_port,
            committed_board,
          )

    if selected_port is None or selected_board is None:
      logger.warning(
        "Auxiliary controller disabled until both a COM port and board profile "
        "are selected"
      )
    else:
      logger.info(
        "COMMUNICATIONS STARTED WITH %s ARDUINO IO BOARD on port: %s",
        selected_board,
        selected_port,
      )
      if RUN['offlineMode']:
        _set_offline_mode_status(True)
      elif _current_main_controller_identity() is None:
        _set_application_status(
          "AUXILIARY CONTROLLER CONNECTED; MAIN CONTROLLER UNAVAILABLE",
          "Warn.TLabel",
        )
      elif not _current_session_primary_calibration_ready():
        _set_application_status(
          "CONTROLLER CALIBRATION REQUIRED",
          "Warn.TLabel",
        )
      else:
        _set_application_status("SYSTEM READY", "OK.TLabel")

    _finish_auxiliary_calibration_persistence_fence(
      previous_persistence_dirty,
      previous_persistence_snapshot,
      True,
      True,
    )
    try:
      value = tab8.ElogView.get(0, END)
      pickle.dump(value, open("ErrorLog", "wb"))
    except Exception:
      logger.exception("Unable to persist the auxiliary connection log")
    return True
  except Exception as e:
    if prepared_auxiliary_connection is not None:
      replacement, _profile, json_client = prepared_auxiliary_connection
      try:
        _close_auxiliary_replacement(
          replacement,
          json_client,
          "abandoned auxiliary replacement",
        )
      except Exception:
        logger.exception("Unable to close the abandoned auxiliary replacement")
    try:
      _cancel_auxiliary_calibration_persistence_job()
    except Exception:
      logger.exception(
        "Unable to cancel auxiliary calibration persistence during recovery"
      )
    active_serial = RUN.get('ser2')
    if (
      not connection_change_completed
      and active_serial is not None
      and active_serial is not previous_serial
    ):
      _close_serial_port(
        'ser2',
        "failed auxiliary connection replacement",
      )
    if connection_change_completed and staged_calibration is not None:
      target_calibration = staged_calibration
      target_output_values = staged_calibration
      target_port = staged_calibration['com2Port']
      target_board = staged_calibration['auxiliaryBoard']
      apply_target = False
      persistence_state_changed = True
    else:
      target_calibration = previous_calibration
      target_output_values = previous_output_values
      target_port = previous_calibration.get('com2Port', "None")
      target_board = previous_calibration.get(
        'auxiliaryBoard',
        AUXILIARY_BOARD_NONE,
      )
      apply_target = True
      persistence_state_changed = False

    target_verified = False
    if apply_target:
      try:
        _apply_auxiliary_configuration_snapshot(
          target_calibration,
          target_output_values,
          target_port,
          target_board,
        )
      except Exception:
        logger.exception(
          "Unable to apply auxiliary recovery configuration"
        )
    try:
      _verify_auxiliary_configuration_snapshot(
        target_calibration,
        target_output_values,
        target_port,
        target_board,
      )
      target_verified = True
    except Exception:
      logger.exception(
        "Auxiliary recovery verification failed"
      )

    if not target_verified:
      active_serial = RUN.get('ser2')
      if active_serial is not None:
        _close_serial_port(
          'ser2',
          "failed auxiliary configuration recovery",
        )
      else:
        _clear_auxiliary_board_profile()
      try:
        target_calibration = previous_calibration
        target_output_values = previous_output_values
        target_port = previous_calibration.get('com2Port', "None")
        target_board = previous_calibration.get(
          'auxiliaryBoard',
          AUXILIARY_BOARD_NONE,
        )
        _apply_auxiliary_configuration_snapshot(
          target_calibration,
          target_output_values,
          target_port,
          target_board,
        )
        _verify_auxiliary_configuration_snapshot(
          target_calibration,
          target_output_values,
          target_port,
          target_board,
        )
        target_verified = True
        persistence_state_changed = False
      except Exception:
        logger.exception(
          "Unable to restore the prior auxiliary configuration"
        )
        active_serial = RUN.get('ser2')
        if active_serial is not None:
          _close_serial_port(
            'ser2',
            "failed prior auxiliary configuration restoration",
          )
        else:
          _clear_auxiliary_board_profile()

    try:
      _finish_auxiliary_calibration_persistence_fence(
        previous_persistence_dirty,
        previous_persistence_snapshot,
        persistence_state_changed,
        target_verified,
      )
    except Exception:
      logger.exception(
        "Unable to settle auxiliary calibration persistence"
      )
      persistence_required = (
        persistence_state_changed or previous_persistence_dirty
      ) if target_verified else previous_persistence_dirty
      persistence_snapshot = (
        None
        if target_verified and persistence_state_changed
        else previous_persistence_snapshot
      )
      try:
        persistence_reconciled = (
          _reconcile_auxiliary_calibration_persistence_after_settle_failure(
            persistence_required,
            persistence_snapshot,
            (
              target_calibration
              if target_verified
              else previous_calibration
            ),
          )
        )
        if persistence_reconciled is not True:
          logger.error(
            "Auxiliary calibration persistence reconciliation did not complete"
          )
      except Exception:
        logger.exception(
          "Unable to reconcile calibration persistence after settle failure"
        )
    if not target_verified:
      logger.error(
        "AUXILIARY CONFIGURATION RECOVERY FAILED; OUTPUT PROFILE DISABLED "
        "AND THE UNVERIFIED STATE WILL NOT BE PERSISTED"
      )
    if connection_change_completed:
      logger.error(
        "AUXILIARY CONNECTION CHANGED BUT FOLLOW-UP FAILED: %s",
        e,
      )
    else:
      logger.error(
        "UNABLE TO ESTABLISH COMMUNICATIONS WITH ARDUINO IO BOARD: %s",
        e,
      )
    try:
      value = tab8.ElogView.get(0, END)
      pickle.dump(value, open("ErrorLog", "wb"))
    except Exception:
      logger.exception("Unable to persist the auxiliary connection failure log")
    return False
  finally:
    auxiliary_serial_lock.release()
    
