ROW_EXECUTION_COMPLETE = "complete"
ROW_EXECUTION_PENDING = "pending"
ROW_EXECUTION_REJECTED = "rejected"
VIRTUAL_COMPLETION_POLL_MS = 10
VIRTUAL_COMPLETION_BASE_TIMEOUT_SECONDS = 120
VIRTUAL_COMPLETION_SAFETY_SCALE = 1.25
VIRTUAL_JOINT_SECONDS_SCALE = 4.5
VIRTUAL_CARTESIAN_SECONDS_SCALE = 4.7
VIRTUAL_TOOL_SECONDS_SCALE = 5.1
LIVE_TOOL_JOG_INCREMENT = 0.25
@dataclass(frozen=True)
class ProgramMotionPoseSnapshot:
  controller_positions: Optional[tuple]
  virtual_pose: tuple


@dataclass(frozen=True)
class ProgramJsonCartesianMotion:
  command_name: str
  motion_commands: tuple
  control_points: tuple = ()
  roundings_millimeters: tuple = ()

  def __post_init__(self):
    if (
      not isinstance(self.motion_commands, tuple)
      or not isinstance(self.control_points, tuple)
      or not isinstance(self.roundings_millimeters, tuple)
      or any(
        not isinstance(command, str) or not command.endswith("\n")
        for command in self.motion_commands
      )
    ):
      raise MotionInputError("program JSON Cartesian motion shape is invalid")
    command_count = len(self.motion_commands)
    if self.command_name == "move_arc":
      shape_valid = (
        command_count == 1
        and self.motion_commands[0].startswith("MJ")
        and len(self.control_points) == 1
        and not self.roundings_millimeters
      )
    elif self.command_name == "move_circle":
      shape_valid = (
        command_count == 1
        and self.motion_commands[0].startswith("MJ")
        and len(self.control_points) == 2
        and not self.roundings_millimeters
      )
    elif self.command_name == "move_spline":
      shape_valid = (
        1 <= command_count <= 6
        and all(command.startswith("ML") for command in self.motion_commands)
        and not self.control_points
        and len(self.roundings_millimeters) == command_count
        and self.roundings_millimeters[-1] == 0.0
      )
    else:
      shape_valid = False
    if not shape_valid:
      raise MotionInputError("program JSON Cartesian motion shape is invalid")
    for point in self.control_points:
      if not isinstance(point, tuple) or len(point) != 3:
        raise MotionInputError("program JSON motion control point is invalid")
      for value in point:
        finite_number(value, "program JSON motion control-point coordinate")
    for rounding in self.roundings_millimeters:
      if finite_number(rounding, "program spline rounding") < 0:
        raise MotionInputError("program spline rounding must be non-negative")


def _motion_command_source_opcode(command):
  if isinstance(command, ProgramJsonCartesianMotion):
    return {
      "move_arc": "MA",
      "move_circle": "MC",
      "move_spline": "MS",
    }[command.command_name]
  if not isinstance(command, str) or len(command) < 2:
    raise MotionInputError("motion source command is invalid")
  return command[:2]


def _motion_command_display_text(command):
  if isinstance(command, ProgramJsonCartesianMotion):
    return command.command_name
  if not isinstance(command, str):
    raise MotionInputError("motion display command is invalid")
  return command


@dataclass(frozen=True)
class MainControllerStopContext:
  serial_port: object
  connection_epoch: int
  confirmed_position_generation: int

  def __post_init__(self):
    if self.serial_port is None:
      raise MotionInputError(
        "main controller stop context requires a serial connection"
      )
    for name, value in (
      ("connection epoch", self.connection_epoch),
      (
        "confirmed position generation",
        self.confirmed_position_generation,
      ),
    ):
      if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 0
      ):
        raise MotionInputError(
          f"main controller stop {name} is invalid"
        )


@dataclass(frozen=True)
class MainControllerStopEvent:
  context: MainControllerStopContext
  position: object = None
  physical_stop: object = None
  upgrades_unpositioned_stop: bool = False

  def __post_init__(self):
    if not isinstance(self.context, MainControllerStopContext):
      raise MotionInputError(
        "main controller stop event requires a session context"
      )
    positioned = self.position is not None
    unpositioned = self.physical_stop is not None
    if positioned == unpositioned:
      raise MotionInputError(
        "main controller stop event requires exactly one evidence variant"
      )
    if type(self.upgrades_unpositioned_stop) is not bool:
      raise MotionInputError(
        "main controller stop position-upgrade state is invalid"
      )
    if self.upgrades_unpositioned_stop and not positioned:
      raise MotionInputError(
        "main controller stop position upgrade requires positioned evidence"
      )
    if positioned and not position_response_is_physical_estop(self.position):
      raise MotionInputError(
        "main controller stop event requires a physical-stop position"
      )
    if (
      unpositioned
      and type(self.physical_stop) is not JsonMainControllerPhysicalStop
    ):
      raise MotionInputError(
        "unpositioned main controller stop evidence is invalid"
      )


class MainControllerIdleStopOwnership:
  def __init__(self, activity_registry, transport_lock, control_mode):
    if not callable(getattr(activity_registry, "finish_control", None)):
      raise TypeError(
        "idle main-controller stop ownership requires an activity registry"
      )
    if not all(
      callable(getattr(transport_lock, method, None))
      for method in ("locked", "release")
    ):
      raise TypeError(
        "idle main-controller stop ownership requires a transport lock"
      )
    if control_mode != SerialActivityRegistry.CONTROL_EXCLUSIVE:
      raise MotionInputError(
        "idle main-controller stop ownership must be exclusive"
      )
    self._activity_registry = activity_registry
    self._transport_lock = transport_lock
    self._control_mode = control_mode
    self._transport_owned = True
    self._state_lock = threading.Lock()

  @property
  def complete(self):
    with self._state_lock:
      return self._control_mode is None and not self._transport_owned

  def release(self):
    with self._state_lock:
      if self._control_mode is None and not self._transport_owned:
        return False
      if self._control_mode is not None:
        self._activity_registry.finish_control(
          "ser",
          self._control_mode,
        )
        self._control_mode = None
      if self._transport_owned:
        if not self._transport_lock.locked():
          raise RuntimeError(
            "idle main-controller stop transport was already released"
          )
        self._transport_lock.release()
        self._transport_owned = False
    return True


@dataclass(frozen=True)
class MainControllerIdleStopReadResult:
  serial_port: object
  ownership: MainControllerIdleStopOwnership
  position: Optional[PositionResponse] = None
  physical_stop: object = None
  error: Optional[str] = None

  def __post_init__(self):
    if self.serial_port is None:
      raise MotionInputError(
        "idle main-controller stop result requires a serial connection"
      )
    if not isinstance(self.ownership, MainControllerIdleStopOwnership):
      raise MotionInputError(
        "idle main-controller stop result requires transport ownership"
      )
    if (
      self.position is not None
      and (
        not position_response_is_physical_estop(self.position)
        or self.position.flag != CONTROLLER_ESTOP_EVENT_FLAG
      )
    ):
      raise MotionInputError(
        "idle main-controller stop result position is invalid"
      )
    if (
      self.physical_stop is not None
      and type(self.physical_stop) is not JsonMainControllerPhysicalStop
    ):
      raise MotionInputError(
        "idle main-controller JSON stop result is invalid"
      )
    if self.position is not None and self.physical_stop is not None:
      raise MotionInputError(
        "idle main-controller stop result has conflicting evidence"
      )
    if self.error is not None and (
      not isinstance(self.error, str)
      or not self.error
      or self.error != self.error.strip()
      or "\r" in self.error
      or "\n" in self.error
    ):
      raise MotionInputError(
        "idle main-controller stop result error is invalid"
      )
    if (
      self.position is None
      and self.physical_stop is None
      and self.error is None
    ):
      raise MotionInputError(
        "idle main-controller stop result requires evidence or an error"
      )


def _apply_valid_position_response(response):
  if isinstance(response, PositionResponse):
    parsed = response
  else:
    try:
      parsed = parse_position_response(response)
    except ProtocolResponseError:
      displayPosition(response)
      return None
  applied_position = displayPosition(parsed.raw, parsed=parsed)
  if applied_position is None or applied_position.flag:
    return None
  return applied_position


def _capture_main_controller_stop_context(serial_port):
  with controller_identity_state_lock:
    binding = main_controller_identity_binding
    connection_epoch = main_controller_connection_epoch
    generation = confirmed_position_generation
    if (
      not isinstance(binding, MainControllerIdentityBinding)
      or binding.serial_port is not serial_port
      or RUN.get('ser') is not serial_port
      or not getattr(serial_port, "is_open", False)
    ):
      raise ConnectionError(
        "main controller stop context requires the active bound connection"
      )
    for name, value in (
      ("connection epoch", connection_epoch),
      ("confirmed position generation", generation),
    ):
      if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 0
      ):
        raise RuntimeError(
          f"main controller stop {name} is invalid"
        )
  return MainControllerStopContext(
    serial_port,
    connection_epoch,
    generation,
  )


def _capture_startup_main_controller_stop_context(serial_port):
  with controller_identity_state_lock:
    binding = main_controller_identity_binding
    connection_epoch = main_controller_connection_epoch
    generation = confirmed_position_generation
    if (
      binding is not None
      or RUN.get('ser') is not serial_port
      or not getattr(serial_port, "is_open", False)
    ):
      raise ConnectionError(
        "startup stop context requires the active unbound connection"
      )
    for name, value in (
      ("connection epoch", connection_epoch),
      ("confirmed position generation", generation),
    ):
      if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 0
      ):
        raise RuntimeError(
          f"startup main controller stop {name} is invalid"
        )
  return MainControllerStopContext(
    serial_port,
    connection_epoch,
    generation,
  )


def _reserve_auxiliary_stop_request_locked(on_reserved=None):
  global auxiliary_stop_next_request_id
  global auxiliary_stop_pending_request_id

  if on_reserved is not None and not callable(on_reserved):
    raise TypeError("auxiliary stop reservation callback must be callable")
  for name, request_id in (
    ("pending", auxiliary_stop_pending_request_id),
    ("active", auxiliary_stop_active_request_id),
    ("main-controller", main_controller_auxiliary_stop_request_id),
  ):
    if (
      request_id is not None
      and (
        isinstance(request_id, bool)
        or not isinstance(request_id, int)
        or request_id <= 0
      )
    ):
      raise RuntimeError(f"auxiliary stop {name} request ID is invalid")
  if (
    auxiliary_stop_pending_request_id is not None
    and auxiliary_stop_active_request_id is not None
  ):
    raise RuntimeError(
      "auxiliary stop cannot be pending and active simultaneously"
    )
  if (
    isinstance(auxiliary_stop_next_request_id, bool)
    or not isinstance(auxiliary_stop_next_request_id, int)
    or auxiliary_stop_next_request_id < 0
  ):
    raise RuntimeError("auxiliary stop request counter is invalid")

  request_id = (
    auxiliary_stop_active_request_id
    if auxiliary_stop_active_request_id is not None
    else auxiliary_stop_pending_request_id
  )
  if (
    request_id is not None
    and main_controller_auxiliary_stop_request_id is not None
    and request_id != main_controller_auxiliary_stop_request_id
  ):
    raise RuntimeError(
      "auxiliary stop ownership conflicts with the main-controller "
      "physical-stop request"
    )
  if (
    request_id is None
    and main_controller_auxiliary_stop_request_id is not None
  ):
    request_id = main_controller_auxiliary_stop_request_id
    if on_reserved is not None:
      on_reserved(request_id)
    auxiliary_stop_pending_request_id = request_id
    auxiliary_stop_requested.set()
    return request_id
  if request_id is None:
    request_id = auxiliary_stop_next_request_id + 1
    if on_reserved is not None:
      on_reserved(request_id)
    auxiliary_stop_next_request_id = request_id
    auxiliary_stop_pending_request_id = request_id
    auxiliary_stop_requested.set()
  elif on_reserved is not None:
    on_reserved(request_id)
  return request_id


def _clear_manual_auxiliary_stop_barrier_if_settled():
  with manual_auxiliary_state_lock:
    with auxiliary_stop_state_lock:
      with program_stop_state_lock:
        program_request_id = RUN.get('programStopRequestId')
        if (
          program_request_id is not None
          and (
            isinstance(program_request_id, bool)
            or not isinstance(program_request_id, int)
            or program_request_id <= 0
          )
        ):
          raise RuntimeError("program stop request ID is invalid")
        settled = (
          auxiliary_stop_pending_request_id is None
          and auxiliary_stop_active_request_id is None
          and main_controller_auxiliary_stop_request_id is None
          and not auxiliary_stop_requested.is_set()
          and program_request_id is None
        )
        if settled:
          manual_auxiliary_stop_barrier.clear()
  return settled


def _latch_main_controller_stop_state(
  position=None,
  *,
  unpositioned_stop=None,
):
  global main_controller_auxiliary_stop_request_id

  positioned = position is not None
  unpositioned = unpositioned_stop is not None
  if positioned == unpositioned:
    raise MotionInputError(
      "main controller stop state requires exactly one stop evidence variant"
    )
  if positioned and not position_response_is_physical_estop(position):
    raise MotionInputError(
      "main controller stop state requires a physical-stop position"
    )
  if (
    unpositioned
    and type(unpositioned_stop) is not JsonMainControllerPhysicalStop
  ):
    raise MotionInputError(
      "main controller unpositioned stop evidence is invalid"
    )
  discarded = 0
  repaired_program_request = False
  with manual_auxiliary_state_lock:
    # Share the final auxiliary-write boundary so barrier publication orders
    # before every later ordinary write commitment.
    manual_auxiliary_stop_barrier.set()
    _cancel_active_program_execution()
    with auxiliary_stop_state_lock:
      with program_stop_state_lock:
        # Configuration commits hold the same outer lock, so this snapshot is
        # always wholly before or wholly after a port/profile transition.
        try:
          auxiliary_stop_not_required = _auxiliary_stop_not_required()
        except Exception:
          auxiliary_stop_not_required = False
          logger.exception(
            "Unable to determine whether the physical E-stop requires an "
            "auxiliary STOP; fail-safe reservation retained"
          )

        position_unavailable = RUN.get(
          'mainControllerStopPositionUnavailable',
          False,
        )
        if not isinstance(position_unavailable, bool):
          raise RuntimeError(
            "main controller stop position-availability latch is invalid"
          )
        RUN['estopActive'] = True
        RUN['mainControllerStopPositionUnavailable'] = (
          position_unavailable or unpositioned
        )
        manual_auxiliary_stop_barrier.set()
        if not isinstance(manual_auxiliary_request_queue, list):
          raise RuntimeError("manual auxiliary request queue is invalid")
        discarded = len(manual_auxiliary_request_queue)
        manual_auxiliary_request_queue.clear()
        program_request_id = RUN.get('programStopRequestId')
        if (
          program_request_id is not None
          and (
            isinstance(program_request_id, bool)
            or not isinstance(program_request_id, int)
            or program_request_id <= 0
          )
        ):
          RUN['programStopRequestId'] = None
          repaired_program_request = True
        physical_request_id = main_controller_auxiliary_stop_request_id
        if (
          physical_request_id is not None
          and (
            isinstance(physical_request_id, bool)
            or not isinstance(physical_request_id, int)
            or physical_request_id <= 0
          )
        ):
          raise RuntimeError(
            "main-controller auxiliary stop request ID is invalid"
          )
        should_reserve_auxiliary_stop = (
          not auxiliary_stop_not_required
          or physical_request_id is not None
          or auxiliary_stop_pending_request_id is not None
          or auxiliary_stop_active_request_id is not None
        )
        if should_reserve_auxiliary_stop:
          request_id = _reserve_auxiliary_stop_request_locked()
          if physical_request_id is None:
            main_controller_auxiliary_stop_request_id = request_id
        else:
          request_id = None

        if request_id is not None:
          RUN['programStopRequestId'] = request_id
          stop_state = "pending"
        elif RUN.get('programStopRequestId') is not None:
          stop_state = "pending"
        else:
          stop_state = "completed"

  if discarded:
    logger.warning(
      "Discarded %s queued manual auxiliary command(s): "
      "main controller reported a physical E-stop",
      discarded,
    )
  if repaired_program_request:
    logger.error(
      "Discarded an invalid prior program-stop request ID while "
      "latching a physical E-stop"
    )
  try:
    _set_program_stop_status(stop_state)
  except Exception:
    logger.exception(
      "Unable to publish the latched physical E-stop status"
    )
  return True


def _complete_main_controller_stop_publication(event, detail):
  if not isinstance(event, MainControllerStopEvent):
    raise MotionInputError("main controller stop event is invalid")
  if (
    not isinstance(detail, str)
    or not detail
    or detail != detail.strip()
    or "\r" in detail
    or "\n" in detail
  ):
    raise MotionInputError("main controller stop detail is invalid")
  main_controller_stop_event_queue.put(event)
  try:
    _try_dispatch_auxiliary_stop()
  except Exception:
    logger.exception(
      "Unable to dispatch the reserved physical E-stop auxiliary STOP"
    )
  try:
    _invalidate_joint_motion_state(detail)
  except Exception:
    logger.exception(
      "Unable to invalidate joint motion after physical E-stop publication"
    )
  return True


def _publish_main_controller_stop(context, position):
  event = MainControllerStopEvent(context, position)
  _latch_main_controller_stop_state(position)
  return _complete_main_controller_stop_publication(
    event,
    f"controller reported physical E-stop: {position.flag}",
  )


def _publish_main_controller_unpositioned_stop(context, physical_stop):
  event = MainControllerStopEvent(
    context,
    physical_stop=physical_stop,
  )
  _latch_main_controller_stop_state(unpositioned_stop=physical_stop)
  return _complete_main_controller_stop_publication(
    event,
    "controller reported physical E-stop during correlated JSON ownership; "
    "controller position is unavailable",
  )


def _publish_main_controller_stop_position_upgrade(context, position):
  event = MainControllerStopEvent(
    context,
    position,
    upgrades_unpositioned_stop=True,
  )
  main_controller_stop_event_queue.put(event)
  return True


def _main_controller_idle_stop_error_detail(error):
  if not isinstance(error, BaseException):
    raise TypeError("idle main-controller stop error must be an exception")
  detail = " ".join(str(error).split())
  return detail or type(error).__name__


def _queue_main_controller_idle_stop_result(
  serial_port,
  ownership,
  *,
  position=None,
  physical_stop=None,
  error=None,
):
  if not isinstance(ownership, MainControllerIdleStopOwnership):
    raise TypeError(
      "idle main-controller stop result ownership is invalid"
    )
  error_detail = (
    None
    if error is None
    else _main_controller_idle_stop_error_detail(error)
  )
  if (
    position is None
    and physical_stop is None
    and error_detail is None
    and not ownership.complete
  ):
    try:
      if ownership.release() is not True:
        raise RuntimeError(
          "idle main-controller stop ownership was already released"
        )
    except Exception as cleanup_error:
      cleanup_detail = _main_controller_idle_stop_error_detail(cleanup_error)
      error_detail = (
        f"{error_detail}; ownership cleanup failed: {cleanup_detail}"
        if error_detail is not None
        else f"ownership cleanup failed: {cleanup_detail}"
      )
  if position is None and physical_stop is None and error_detail is None:
    return False
  try:
    main_controller_idle_stop_result_queue.put(
      MainControllerIdleStopReadResult(
        serial_port,
        ownership,
        position=position,
        physical_stop=physical_stop,
        error=error_detail,
      )
    )
  except Exception:
    if not ownership.complete:
      try:
        ownership.release()
      except Exception:
        logger.exception(
          "Unable to release idle main-controller event ownership "
          "after result publication failed"
        )
    raise
  return True


def _quarantine_main_controller_idle_stop_failure(serial_port, error):
  detail = _main_controller_idle_stop_error_detail(error)
  try:
    quarantine_serial_transport(
      serial_port,
      "idle main-controller event framing is untrusted",
    )
  except Exception as quarantine_error:
    quarantine_detail = _main_controller_idle_stop_error_detail(
      quarantine_error
    )
    return RuntimeError(
      f"{detail}; transport quarantine failed: {quarantine_detail}"
    )
  return RuntimeError(detail)


def _consume_main_controller_idle_json_stop(
  serial_port,
  context,
  json_client,
):
  if (
    not isinstance(json_client, JsonMainControllerClient)
    or json_client.serial_port is not serial_port
  ):
    raise ProtocolResponseError(
      "idle main-controller JSON ownership is invalid"
    )
  delivery = None
  while delivery is None:
    delivery = json_client.pop_delivery()
    if delivery is not None:
      break
    polled = json_client.poll()
    if not polled and not json_client.has_unread_input:
      raise ProtocolResponseError(
        "idle main-controller JSON buffer lacked a complete frame"
      )
  _validate_json_joint_motion_event(delivery)
  physical_stop = JsonMainControllerPhysicalStop(
    "idle",
    "emergency_stop_event",
  )
  _publish_main_controller_unpositioned_stop(context, physical_stop)

  while True:
    extra = json_client.pop_delivery()
    if extra is None:
      polled = json_client.poll()
      if not polled and not json_client.has_unread_input:
        break
      continue
    raise ProtocolResponseError(
      "idle main-controller JSON stop contained additional data"
    )
  if json_client.release_reader() is not True:
    raise ProtocolResponseError(
      "idle main-controller JSON reader ownership was not released"
    )
  quarantine_serial_transport(
    serial_port,
    "idle main-controller JSON physical E-stop requires reconnection",
  )
  return physical_stop


def _consume_main_controller_idle_stop(
  serial_port,
  context,
  json_client,
):
  return _consume_main_controller_idle_json_stop(
    serial_port,
    context,
    json_client,
  )


def _run_main_controller_idle_stop_reader(
  serial_port,
  context,
  ownership,
  json_client,
):
  position = None
  physical_stop = None
  error = None
  try:
    result = _consume_main_controller_idle_stop(
      serial_port,
      context,
      json_client,
    )
    if isinstance(result, PositionResponse):
      position = result
    elif type(result) is JsonMainControllerPhysicalStop:
      physical_stop = result
    else:
      raise ProtocolResponseError(
        "idle main-controller reader returned invalid stop evidence"
      )
  except Exception as exc:
    error = exc
  _queue_main_controller_idle_stop_result(
    serial_port,
    ownership,
    position=position,
    physical_stop=physical_stop,
    error=error,
  )


def _try_start_main_controller_idle_stop_reader():
  serial_port = RUN.get('ser')
  if (
    serial_port is None
    or not getattr(serial_port, "is_open", False)
    or serial_transport_quarantined(serial_port)
  ):
    return False
  if not serial_lock.acquire(blocking=False):
    return False

  try:
    if (
      RUN.get('ser') is not serial_port
      or not getattr(serial_port, "is_open", False)
      or serial_transport_quarantined(serial_port)
    ):
      serial_lock.release()
      return False
    control_mode = serial_activity_registry.reserve_emergency_control("ser")
  except Exception:
    serial_lock.release()
    raise
  if control_mode is None:
    serial_lock.release()
    return False
  if control_mode != SerialActivityRegistry.CONTROL_EXCLUSIVE:
    try:
      serial_activity_registry.finish_control("ser", control_mode)
    finally:
      serial_lock.release()
    return False

  ownership = MainControllerIdleStopOwnership(
    serial_activity_registry,
    serial_lock,
    control_mode,
  )
  try:
    context = _capture_main_controller_stop_context(serial_port)
    binding = _current_main_controller_identity(serial_port)
    if binding is None or not isinstance(
      binding.json_client,
      JsonMainControllerClient,
    ):
      raise ProtocolResponseError(
        "idle JSON controller stop lost controller ownership"
      )
    json_client = binding.json_client
  except ConnectionError:
    _queue_main_controller_idle_stop_result(serial_port, ownership)
    return False
  except Exception as exc:
    failure = _quarantine_main_controller_idle_stop_failure(
      serial_port,
      exc,
    )
    _queue_main_controller_idle_stop_result(
      serial_port,
      ownership,
      error=failure,
    )
    return False

  try:
    pending_bytes = serial_port.in_waiting
    if (
      isinstance(pending_bytes, bool)
      or not isinstance(pending_bytes, int)
      or pending_bytes < 0
    ):
      raise ProtocolResponseError(
        "idle main-controller byte count is invalid"
      )
  except Exception as exc:
    failure = _quarantine_main_controller_idle_stop_failure(
      serial_port,
      exc,
    )
    _queue_main_controller_idle_stop_result(
      serial_port,
      ownership,
      error=failure,
    )
    return False
  if pending_bytes == 0:
    _queue_main_controller_idle_stop_result(serial_port, ownership)
    return False

  try:
    worker = threading.Thread(
      target=_run_main_controller_idle_stop_reader,
      args=(serial_port, context, ownership, json_client),
      name="ar4-main-controller-idle-stop",
      daemon=True,
    )
    worker.start()
  except Exception as exc:
    failure = _quarantine_main_controller_idle_stop_failure(
      serial_port,
      exc,
    )
    _queue_main_controller_idle_stop_result(
      serial_port,
      ownership,
      error=failure,
    )
    return False
  return True


def _apply_main_controller_idle_stop_results():
  global main_controller_idle_stop_pending_result

  applied = False
  while True:
    result = main_controller_idle_stop_pending_result
    if result is None:
      try:
        result = main_controller_idle_stop_result_queue.get_nowait()
      except Empty:
        break
      main_controller_idle_stop_pending_result = result
    if not isinstance(result, MainControllerIdleStopReadResult):
      raise RuntimeError(
        "idle main-controller stop reader emitted an invalid result"
      )
    if not result.ownership.complete:
      if result.ownership.release() is not True:
        raise RuntimeError(
          "idle main-controller stop ownership could not be settled"
        )
    if (
      RUN.get('ser') is result.serial_port
      and not getattr(result.serial_port, "is_open", False)
    ):
      _require_main_controller_identity_cleanup(
        result.serial_port,
        "idle main-controller stop handling",
      )
    if result.error is not None:
      message = (
        "IDLE MAIN-CONTROLLER EVENT MONITOR FAILED: "
        f"{result.error}"
      )
      logger.error(message)
      _set_application_status(message, "Alarm.TLabel")
      _invalidate_joint_motion_state(message)
    applied = True
    main_controller_idle_stop_pending_result = None
  return applied


def _manual_controller_error_detail(error, fallback):
  if (
    not isinstance(fallback, str)
    or not fallback.strip()
    or fallback != fallback.strip()
    or len(fallback) > MAX_RESPONSE_PAYLOAD_LENGTH
  ):
    raise TypeError("manual controller error fallback must be normalized text")
  try:
    detail = " ".join(str(error).split())
  except Exception:
    return fallback
  if not detail or len(detail) > MAX_RESPONSE_PAYLOAD_LENGTH:
    return fallback
  return detail


def _set_manual_controller_feedback(message):
  if (
    not isinstance(message, str)
    or not message.strip()
    or message != message.strip()
    or "\r" in message
    or "\n" in message
  ):
    raise TypeError("manual controller feedback must be normalized text")
  MBoutputEntryField.delete(0, 'end')
  MBoutputEntryField.insert(0, message)
  return True


def _render_manual_controller_rejection(message):
  _set_manual_controller_feedback(message)
  _set_manual_controller_status(message, "Alarm.TLabel")
  return False


def _set_manual_controller_status(message, style):
  return _set_manual_auxiliary_status(message, style)


def _manual_controller_operation():
  with manual_controller_state_lock:
    request = manual_controller_active_request
    activity_lease = manual_controller_activity_lease
  if not isinstance(request, ManualControllerRequest):
    raise RuntimeError("manual controller active request is invalid")
  if not callable(getattr(activity_lease, "close", None)):
    raise RuntimeError("manual controller activity lease is invalid")
  return request, activity_lease


def _close_manual_controller_cleanup_transport(request, context):
  if not isinstance(request, ManualControllerRequest):
    raise TypeError("manual controller cleanup request is invalid")
  if (
    not isinstance(context, str)
    or not context.strip()
    or context != context.strip()
    or "\r" in context
    or "\n" in context
  ):
    raise TypeError("manual controller cleanup context is invalid")
  quarantine_serial_transport(
    request.serial_port,
    f"{context} requires controller reconnection",
  )
  if getattr(request.serial_port, "is_open", False):
    raise RuntimeError(
      "manual controller cleanup transport remained open"
    )
  current_port = RUN.get('ser')
  if current_port is not None and current_port is not request.serial_port:
    raise RuntimeError(
      "manual controller cleanup connection ownership changed"
    )
  _require_main_controller_identity_cleanup(
    request.serial_port,
    context,
  )
  return True


def _retain_manual_controller_cleanup(cleanup):
  global manual_controller_cleanup_pending

  if not isinstance(cleanup, ManualControllerCleanup):
    raise TypeError("retained manual controller cleanup is invalid")
  if cleanup.complete:
    raise RuntimeError(
      "completed manual controller cleanup cannot be retained"
    )
  with manual_controller_cleanup_lock:
    existing = manual_controller_cleanup_pending
    if existing is not None and existing is not cleanup:
      raise RuntimeError("manual controller cleanup ownership collided")
    manual_controller_cleanup_pending = cleanup
  return True


def _manual_controller_connection_trusted(request):
  if not isinstance(request, ManualControllerRequest):
    raise TypeError("manual controller trust request is invalid")
  return (
    RUN.get('ser') is request.serial_port
    and getattr(request.serial_port, "is_open", False)
    and not serial_transport_quarantined(request.serial_port)
  )


def _finalize_manual_controller_cleanup(cleanup):
  if not isinstance(cleanup, ManualControllerCleanup):
    raise TypeError("manual controller settlement cleanup is invalid")
  if not cleanup.resources_released:
    raise RuntimeError(
      "manual controller settlement requires released resources"
    )

  def replace_connection_loss():
    current_port = RUN.get('ser')
    if current_port not in (None, cleanup.request.serial_port):
      raise RuntimeError(
        "manual controller connection changed during settlement"
      )
    if getattr(cleanup.request.serial_port, "is_open", False):
      quarantine_serial_transport(
        cleanup.request.serial_port,
        "manual controller connection lost during settlement",
      )
    _require_main_controller_identity_cleanup(
      cleanup.request.serial_port,
      "manual controller connection-loss settlement",
    )
    _invalidate_joint_motion_state(
      "manual controller connection lost during result settlement"
    )
    cleanup.replace_settlement(
      "none",
      ManualControllerPresentation(
        (
          "Controller connection lost during result settlement; "
          "reconnect required"
        ),
        "CONTROLLER CONNECTION LOST; RECONNECTION REQUIRED",
        "Alarm.TLabel",
      ),
    )

  action = cleanup.settlement_action
  if (
    action in ("dispatch", "dispatch-ready")
    and not _manual_controller_connection_trusted(cleanup.request)
  ):
    replace_connection_loss()

  presentation = cleanup.settlement_presentation
  if presentation is not None:
    _set_manual_controller_feedback(presentation.feedback)
    _set_manual_controller_status(
      presentation.status,
      presentation.style,
    )

  action = cleanup.settlement_action
  if (
    action in ("dispatch", "dispatch-ready")
    and not _manual_controller_connection_trusted(cleanup.request)
  ):
    replace_connection_loss()
    presentation = cleanup.settlement_presentation
    _set_manual_controller_feedback(presentation.feedback)
    _set_manual_controller_status(
      presentation.status,
      presentation.style,
    )

  if cleanup.settle() is not True:
    raise RuntimeError(
      "manual controller settlement ownership was already released"
    )
  return True


def _retry_manual_controller_cleanup():
  global manual_controller_cleanup_pending

  with manual_controller_cleanup_lock:
    cleanup = manual_controller_cleanup_pending
  if cleanup is None:
    return True
  if not isinstance(cleanup, ManualControllerCleanup):
    raise RuntimeError("pending manual controller cleanup is invalid")
  try:
    if cleanup.release() is not True:
      raise RuntimeError("manual controller resource cleanup did not settle")
    if _finalize_manual_controller_cleanup(cleanup) is not True:
      raise RuntimeError("manual controller result settlement did not finish")
    if not cleanup.complete:
      raise RuntimeError("manual controller cleanup remained incomplete")
  except Exception as exc:
    cleanup.record_failure(exc)
    return False
  with manual_controller_cleanup_lock:
    if manual_controller_cleanup_pending is not cleanup:
      raise RuntimeError("manual controller cleanup ownership changed")
    manual_controller_cleanup_pending = None
  return True


def _release_manual_controller_operation(
  *,
  close_required=False,
  close_context="manual controller cleanup",
  settlement_action="none",
  settlement_presentation=None,
):
  with manual_controller_cleanup_lock:
    pending_cleanup = manual_controller_cleanup_pending
  if pending_cleanup is not None:
    if not isinstance(pending_cleanup, ManualControllerCleanup):
      raise RuntimeError("pending manual controller cleanup is invalid")
    request = pending_cleanup.request
    if close_required:
      pending_cleanup.require_close(close_context)
    if not _retry_manual_controller_cleanup():
      detail = (
        pending_cleanup.last_error
        or "cleanup retry failed without details"
      )
      raise RuntimeError(
        f"manual controller cleanup remains pending: {detail}"
      )
    return request

  request, activity_lease = _manual_controller_operation()
  cleanup = ManualControllerCleanup(
    request,
    activity_lease,
    close_required=close_required,
    close_context=close_context,
    settlement_action=settlement_action,
    settlement_presentation=settlement_presentation,
  )
  _retain_manual_controller_cleanup(cleanup)
  if not _retry_manual_controller_cleanup():
    detail = (
      cleanup.last_error
      or "cleanup retry failed without details"
    )
    raise RuntimeError(
      f"manual controller cleanup retained for retry: {detail}"
    )
  return request


def _exchange_manual_controller_request(request, serial_write_started_event,
                                        unpositioned_stop_event):
  if not isinstance(request, ManualControllerRequest):
    raise TypeError("manual controller worker request is invalid")
  if (
    not callable(getattr(serial_write_started_event, "set", None))
    or not callable(getattr(serial_write_started_event, "is_set", None))
  ):
    raise TypeError(
      "manual controller serial write event is invalid"
    )
  if RUN.get('ser') is not request.serial_port:
    raise ConnectionError(
      "manual controller connection changed before request dispatch"
    )
  opcode = request.command[:2]
  if opcode in ("BA", "BH", "BB", "BC", "BD"):
    value = _exchange_main_controller_modbus_read(
      request.command,
      write_started_event=serial_write_started_event,
      completed_stop_event=unpositioned_stop_event,
    )
  elif opcode in ("BE", "BF"):
    value = _exchange_main_controller_modbus_write(
      request.command,
      write_started_event=serial_write_started_event,
      completed_stop_event=unpositioned_stop_event,
    )
  else:
    raise MotionInputError("manual controller command lacks a JSON route")
  outcome = classify_controller_modbus_terminal_response(
    request.command,
    value,
  )
  return ManualControllerResult(
    request.request_id,
    outcome,
    value,
    serial_write_started_event.is_set(),
    unpositioned_stop_observed=unpositioned_stop_event.is_set(),
  )


def _run_manual_controller_request(request):
  serial_write_started_event = threading.Event()
  unpositioned_stop_event = threading.Event()
  try:
    result = _exchange_manual_controller_request(
      request,
      serial_write_started_event,
      unpositioned_stop_event,
    )
  except BaseException as exc:
    message = _manual_controller_error_detail(
      exc,
      "manual controller command failed without details",
    )
    request_id = getattr(request, "request_id", None)
    if (
      isinstance(request_id, bool)
      or not isinstance(request_id, int)
      or request_id <= 0
    ):
      manual_controller_event_queue.put(None)
      return
    serial_write_started = serial_write_started_event.is_set()
    outcome = "failed"
    if (
      serial_write_started
      and isinstance(request, ManualControllerRequest)
      and controller_modbus_command_is_write(request.command)
    ):
      outcome = "indeterminate"
    result = ManualControllerResult(
      request_id,
      outcome,
      message,
      serial_write_started,
      unpositioned_stop_observed=unpositioned_stop_event.is_set(),
    )
  manual_controller_event_queue.put(result)


def _start_manual_controller_request(command):
  global manual_controller_active_request
  global manual_controller_activity_lease
  global manual_controller_next_request_id
  global manual_controller_program_admission_active

  if application_closing.is_set():
    return _render_manual_controller_rejection(
      "CONTROLLER I/O REJECTED DURING SHUTDOWN"
    )
  if RUN['offlineMode']:
    return _render_manual_controller_rejection(
      "CONTROLLER I/O REQUIRES AN ONLINE CONTROLLER"
    )
  if _program_execution_active():
    return _render_manual_controller_rejection(
      "CONTROLLER I/O REJECTED WHILE A PROGRAM IS RUNNING"
    )
  with manual_controller_cleanup_lock:
    cleanup_pending = manual_controller_cleanup_pending is not None
  if cleanup_pending:
    return _render_manual_controller_rejection(
      "CONTROLLER I/O REJECTED WHILE CLEANUP IS PENDING"
    )
  try:
    validate_controller_modbus_command(command)
    mutates_external_state = controller_modbus_command_is_write(command)
  except Exception as exc:
    detail = _manual_controller_error_detail(
      exc,
      "command validation failed without details",
    )
    return _render_manual_controller_rejection(
      f"Controller I/O rejected: {detail}"
    )

  if not serial_lock.acquire(blocking=False):
    return _render_manual_controller_rejection(
      "CONTROLLER I/O REJECTED WHILE TRANSPORT IS BUSY"
    )

  activity_lease = None
  state_assigned = False
  program_admission_assigned = False
  try:
    with program_execution_state_lock:
      if (
        program_execution_active_request is not None
        or gcode_conversion_active.is_set()
        or gcode_storage_program_admission_active
        or manual_controller_program_admission_active
      ):
        raise SerialActivityRejected(
          "manual controller I/O rejected during program activity"
        )
      if mutates_external_state:
        with auxiliary_stop_state_lock:
          with program_stop_state_lock:
            stop_reason = _stop_admission_reason_locked(
              "CONTROLLER WRITE"
            )
        if stop_reason is not None:
          raise SerialActivityRejected(stop_reason)
      manual_controller_program_admission_active = True
      program_admission_assigned = True
    serial_port = RUN.get('ser')
    with manual_controller_state_lock:
      if (
        manual_controller_active_request is not None
        or manual_controller_activity_lease is not None
      ):
        raise RuntimeError("manual controller request ownership is already active")
      if (
        isinstance(manual_controller_next_request_id, bool)
        or not isinstance(manual_controller_next_request_id, int)
        or manual_controller_next_request_id < 0
      ):
        raise RuntimeError("manual controller request counter is invalid")
      request_id = manual_controller_next_request_id + 1
      request = ManualControllerRequest(
        request_id,
        serial_port,
        command,
      )
      worker = threading.Thread(
        target=_run_manual_controller_request,
        args=(request,),
        daemon=True,
      )
      activity_lease = serial_activity_registry.lease("ser")
      manual_controller_next_request_id = request_id
      manual_controller_active_request = request
      manual_controller_activity_lease = activity_lease
      state_assigned = True
    serial_result_pending.set()
    worker.start()
  except Exception as exc:
    if state_assigned:
      try:
        _release_manual_controller_operation()
      except Exception:
        logger.exception(
          "Unable to release failed manual controller startup ownership"
        )
    else:
      if serial_lock.locked():
        serial_lock.release()
      if activity_lease is not None:
        try:
          if activity_lease.close() is not True:
            raise RuntimeError("serial activity lease was already released")
        except Exception:
          logger.exception(
            "Unable to release failed manual controller startup activity"
          )
      if program_admission_assigned:
        with program_execution_state_lock:
          manual_controller_program_admission_active = False
    detail = _manual_controller_error_detail(
      exc,
      "worker startup failed without details",
    )
    message = f"Unable to start controller I/O worker: {detail}"
    logger.exception(message)
    return _render_manual_controller_rejection(message)

  cmdSentEntryField.delete(0, 'end')
  cmdSentEntryField.insert(0, command)
  _set_manual_controller_status(
    "CONTROLLER I/O IN PROGRESS",
    "Warn.TLabel",
  )
  return True


def _request_manual_modbus(opcode):
  try:
    command = build_controller_modbus_command(
      opcode,
      MBslaveEntryField.get(),
      MBaddressEntryField.get(),
      MBoperValEntryField.get(),
    )
  except Exception as exc:
    detail = _manual_controller_error_detail(
      exc,
      "entry validation failed without details",
    )
    message = f"Controller I/O rejected: {detail}"
    logger.error(message)
    return _render_manual_controller_rejection(message)
  return _start_manual_controller_request(command)


@_synchronous_motion_request(
  "Program controller command",
  rejection_result=(ROW_EXECUTION_REJECTED, None),
  requires_kinematics=False,
  inherited_lease_keyword="request_lease",
)
@_tracked_serial_operation(
  "ser",
  rejection_result=(ROW_EXECUTION_REJECTED, None),
)
def _execute_row_main_command(
  command,
  *,
  request_lease=None,
  controller_wait_seconds=None,
  **response_contract,
):
  execution_request = _active_program_execution_request()
  if _program_execution_request_cancelled(execution_request):
    _abort_program_row_execution()
    return ROW_EXECUTION_REJECTED, None
  cancellation_options = (
    "write_started_event",
    "cancellation_event",
    "write_boundary_lock",
  )
  if any(option in response_contract for option in cancellation_options):
    raise MotionInputError(
      "program row response contract cannot replace cancellation ownership"
    )
  write_started_event = threading.Event()
  try:
    if command in (
      "read_encoders",
      "set_encoders",
      "test_limit_switches",
    ):
      if controller_wait_seconds is not None or response_contract:
        raise MotionInputError(
          "controller diagnostics do not accept wait or response contracts"
        )
      response = _exchange_main_controller_diagnostic(
        command,
        write_started_event=write_started_event,
        write_cancellation_boundary=execution_request.cancellation_boundary,
      )
    elif isinstance(command, str) and command[:2] in ("BA", "BH", "BB", "BC", "BD"):
      if controller_wait_seconds is not None or response_contract:
        raise MotionInputError("Modbus reads reject response contracts")
      response = _exchange_main_controller_modbus_read(
        command,
        write_started_event=write_started_event,
        write_cancellation_boundary=execution_request.cancellation_boundary,
      )
    elif isinstance(command, str) and command[:2] in ("SC", "SO"):
      if controller_wait_seconds is not None or response_contract:
        raise MotionInputError("Modbus writes reject response contracts")
      response = _exchange_main_controller_modbus_write(
        command,
        write_started_event=write_started_event,
        write_cancellation_boundary=execution_request.cancellation_boundary,
      )
    elif isinstance(command, str) and command[:2] in ("WH", "WJ", "WK"):
      if controller_wait_seconds is not None or set(response_contract) != {
        "response_timeout"
      }:
        raise MotionInputError(
          "Modbus waits require one response-timeout contract"
        )
      response = _exchange_main_controller_modbus_wait(
        command,
        response_timeout=response_contract["response_timeout"],
        write_started_event=write_started_event,
        write_cancellation_boundary=execution_request.cancellation_boundary,
      )
    elif controller_wait_seconds is not None:
      if set(response_contract) != {"response_timeout"}:
        raise MotionInputError(
          "controller wait requires one response-timeout contract"
        )
      response = _exchange_main_controller_wait(
        command,
        controller_wait_seconds,
        response_timeout=response_contract["response_timeout"],
        write_started_event=write_started_event,
        write_cancellation_boundary=execution_request.cancellation_boundary,
      )
    else:
      raise MotionInputError("program controller command lacks a JSON route")
  except Exception as exc:
    detail = " ".join(str(exc).split()) or type(exc).__name__
    if write_started_event.is_set() and isinstance(command, str) and (
      command[:2] in ("BE", "BF", "SC", "SO")):
      reason = f"program Modbus {command[:2]} external write outcome is unknown"
      cleanup_errors = []
      try:
        if not _close_serial_port('ser', reason, quarantine=True):
          cleanup_errors.append("main controller cleanup remains pending")
      except Exception as cleanup_exc:
        cleanup_detail = (
          " ".join(str(cleanup_exc).split())
          or type(cleanup_exc).__name__
        )
        cleanup_errors.append(cleanup_detail)
      try:
        _invalidate_joint_motion_state(reason)
      except Exception as cleanup_exc:
        cleanup_detail = (
          " ".join(str(cleanup_exc).split())
          or type(cleanup_exc).__name__
        )
        cleanup_errors.append(cleanup_detail)
      message = (
        f"Program Modbus {command[:2]} write outcome unknown ({detail}); "
        "reconnect and verify external device state"
      )
      if cleanup_errors:
        message = f"{message}; cleanup pending: {'; '.join(cleanup_errors)}"
    else:
      message = f"Program controller command failed: {detail}"
    logger.exception(message)
    _queue_program_execution_status(message, "Alarm.TLabel")
    return ROW_EXECUTION_REJECTED, None
  if _program_execution_request_cancelled(execution_request):
    _abort_program_row_execution()
    return ROW_EXECUTION_REJECTED, None
  return ROW_EXECUTION_COMPLETE, response


def _execute_row_main_response(
  command,
  **response_contract,
):
  execution_state, response = _execute_row_main_command(
    command,
    **response_contract,
  )
  if execution_state != ROW_EXECUTION_COMPLETE:
    _finish_execute_row()
    return execution_state, None
  return execution_state, response


def _reject_indeterminate_program_modbus_write(command, response):
  if not controller_modbus_command_is_write(command):
    raise MotionInputError(
      "indeterminate program Modbus settlement requires a write command"
    )
  if (
    not isinstance(response, str)
    or not response
    or response != response.strip()
    or "\r" in response
    or "\n" in response
    or len(response) > MAX_RESPONSE_PAYLOAD_LENGTH
  ):
    raise ProtocolResponseError(
      "indeterminate program Modbus response is invalid"
    )
  try:
    response.encode("ascii")
  except UnicodeEncodeError as exc:
    raise ProtocolResponseError(
      "indeterminate program Modbus response must contain ASCII text"
    ) from exc

  opcode = command[:2]
  reason = f"program Modbus {opcode} external write outcome is unknown"
  cleanup_errors = []
  try:
    if not _close_serial_port('ser', reason, quarantine=True):
      cleanup_errors.append("main controller cleanup remains pending")
  except Exception as exc:
    detail = " ".join(str(exc).split()) or type(exc).__name__
    cleanup_errors.append(detail)
  try:
    _invalidate_joint_motion_state(reason)
  except Exception as exc:
    detail = " ".join(str(exc).split()) or type(exc).__name__
    cleanup_errors.append(detail)

  message = (
    f"Program Modbus {opcode} write outcome unknown ({response}); "
    "reconnect and verify external device state"
  )
  if cleanup_errors:
    message = f"{message}; cleanup pending: {'; '.join(cleanup_errors)}"
  logger.error(message)
  _set_application_status(message, "Alarm.TLabel")
  _finish_execute_row()
  return ROW_EXECUTION_REJECTED, None


def _execute_row_main_modbus_write_response(command):
  if (
    not controller_modbus_command_is_write(command)
    or command[:2] not in ("SC", "SO")
  ):
    raise MotionInputError(
      "program Modbus write response requires an SC or SO command"
    )
  execution_state, response = _execute_row_main_command(command)
  if execution_state != ROW_EXECUTION_COMPLETE:
    _finish_execute_row()
    return execution_state, None
  outcome = classify_controller_modbus_terminal_response(command, response)
  if outcome == "completed":
    return execution_state, response
  if outcome == "indeterminate":
    return _reject_indeterminate_program_modbus_write(command, response)
  if outcome != "rejected":
    raise RuntimeError("program Modbus write outcome is invalid")
  message = f"Program controller write rejected: {response}"
  logger.error(message)
  _set_application_status(message, "Alarm.TLabel")
  _finish_execute_row()
  return ROW_EXECUTION_REJECTED, None


def _apply_controller_position_response(response):
  if type(response) is PositionResponse:
    if position_response_is_physical_estop(response):
      return False
    applied = displayPosition(response.raw, parsed=response)
    return applied is not None and not response.flag
  if isinstance(response, str) and response.startswith("E"):
    _invalidate_joint_motion_state(f"controller rejected request: {response}")
    ErrorHandler(response)
    return False
  return _apply_valid_position_response(response) is not None


def _finish_execute_row():
  try:
    RUN['VR_angles'] = [
      float(CAL['J1AngCur']),
      float(CAL['J2AngCur']),
      float(CAL['J3AngCur']),
      float(CAL['J4AngCur']),
      float(CAL['J5AngCur']),
      float(CAL['J6AngCur']),
    ]
    setStepMonitorsVR()
  finally:
    _abort_program_row_execution()


def _abort_program_row_execution():
  with program_stop_state_lock:
    RUN['progRunning'] = False
    RUN['rowinproc'] = 0


def _reject_cancelled_program_row(execution_request):
  if not _program_execution_request_cancelled(execution_request):
    return False
  _abort_program_row_execution()
  return True


def _execute_row_auxiliary_command(
  command,
  *,
  control_injectable=False,
  response_timeout=SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS,
):
  if not isinstance(control_injectable, bool):
    raise TypeError("control_injectable must be boolean")
  response_timeout = finite_number(
    response_timeout,
    "auxiliary response timeout",
  )
  if response_timeout <= 0:
    raise MotionInputError("auxiliary response timeout must be positive")
  try:
    with _tracked_auxiliary_operation(
      control_injectable=control_injectable,
    ):
      if _active_program_execution_cancelled():
        raise SerialActivityRejected(
          "program auxiliary command cancelled by stop admission"
        )
      serial_port = RUN.get('ser2')
      profile = _connected_auxiliary_board_profile(serial_port)
      if command == "TG\n":
        validate_auxiliary_gripper_current_command(command, profile)
        command_name, parameters = "test_gripper_amps", {}
      elif command.startswith("SV"):
        validate_auxiliary_servo_command(command, profile)
        channel, position = parse_auxiliary_servo_command(command)
        command_name = "servo"
        parameters = {"channel": channel, "position": position}
      elif (match := re.fullmatch(r"JFX([0-9]+)\n", command)) is not None:
        validate_auxiliary_input_command(command, profile)
        command_name, parameters = "input_read", {"pin": int(match.group(1))}
      elif (
        match := re.fullmatch(r"WIA([0-9]+)B([01])C([0-9]+)\n", command)
      ) is not None:
        validate_auxiliary_wait_command(command, profile)
        command_name = "wait_input"
        parameters = {
          "pin": int(match.group(1)),
          "state": match.group(2) == "1",
          "timeout_seconds": int(match.group(3)),
        }
      elif command.startswith(("ONX", "OFX")):
        validate_auxiliary_output_command(command, profile)
        opcode, pin = parse_auxiliary_output_command(command)
        command_name = "set_output"
        parameters = {"pin": pin, "state": opcode == "ON"}
      else:
        raise MotionInputError("program auxiliary command is unsupported")
      if control_injectable != (command_name == "wait_input"):
        raise MotionInputError("auxiliary wait stop ownership is invalid")
      result = _exchange_json_auxiliary_command(
        command_name,
        parameters,
        response_timeout,
        serial_port,
      )
      if command_name == "input_read":
        if type(result) is not JsonAuxiliaryInputResult:
          raise ProtocolResponseError("auxiliary input result is invalid")
        response = "T" if result.state else "F"
      elif command_name == "test_gripper_amps":
        if type(result) is not JsonAuxiliaryCurrentResult:
          raise ProtocolResponseError("auxiliary current result is invalid")
        response = f"{result.amps:.3f}"
      else:
        response = result if command_name == "wait_input" else "Done"
  except SerialActivityRejected as exc:
    logger.warning("Program auxiliary command rejected: %s", exc)
    _finish_execute_row()
    return ROW_EXECUTION_REJECTED, None
  except ProtocolResponseError as exc:
    message = f"Program auxiliary response rejected: {exc}"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
    _finish_execute_row()
    return ROW_EXECUTION_REJECTED, None
  except Exception as exc:
    message = f"Program auxiliary command failed: {exc}"
    logger.exception(message)
    _set_application_status(message, "Alarm.TLabel")
    _finish_execute_row()
    return ROW_EXECUTION_REJECTED, None
  return ROW_EXECUTION_COMPLETE, response


def _auxiliary_wait_timeout_seconds(value):
  if isinstance(value, bool):
    raise MotionInputError("auxiliary wait timeout must be an integer")
  text = str(value).strip()
  if not re.fullmatch(r"[0-9]+", text):
    raise MotionInputError(
      "auxiliary wait timeout must be a positive integer"
    )
  timeout = int(text)
  if timeout == 0:
    raise MotionInputError("auxiliary wait timeout must be a positive integer")
  if timeout > AUXILIARY_WAIT_MAXIMUM_SECONDS:
    raise MotionInputError("auxiliary wait timeout exceeds the firmware range")
  return timeout


def _main_modbus_wait_timeout_seconds(value):
  if isinstance(value, bool):
    raise MotionInputError("controller Modbus wait timeout must be an integer")
  text = str(value).strip()
  if not re.fullmatch(r"[0-9]+", text):
    raise MotionInputError(
      "controller Modbus wait timeout must be a positive integer"
    )
  timeout = int(text)
  if timeout == 0:
    raise MotionInputError(
      "controller Modbus wait timeout must be a positive integer"
    )
  if timeout > MAIN_MODBUS_WAIT_MAX_SECONDS:
    raise MotionInputError(
      "controller Modbus wait timeout exceeds the firmware range"
    )
  return timeout


def _execute_program_modbus_wait(command, opcode, execution_request):
  contract = {
    "WH": ("Wait MBhold", "Input", 65535),
    "WJ": ("Wait MBcoil", "Coil", 1),
    "WK": ("Wait MBinput", "Input", 1),
  }.get(opcode)
  if contract is None or not isinstance(command, str):
    raise MotionInputError("program Modbus wait contract is invalid")
  prefix, address_label, maximum_expected = contract
  match = re.fullmatch(
    rf"{prefix} - SlaveID \((?P<slave>[0-9]+)\) - "
    rf"{address_label} # (?P<address>[0-9]+) = "
    r"(?P<expected>[0-9]+) : Timeout = (?P<timeout>[0-9]+)",
    command,
  )
  if match is None:
    raise MotionInputError("program Modbus wait framing is invalid")
  if _reject_cancelled_program_row(execution_request):
    return ROW_EXECUTION_REJECTED
  if RUN['offlineMode']:
    _set_application_status(
      text="IO not supported in offline programming mode",
      style="Alarm.TLabel",
    )
    _finish_execute_row()
    return ROW_EXECUTION_REJECTED
  if RUN['moveInProc'] == 1:
    RUN['moveInProc'] = 2
  expected = int(match.group("expected"))
  if expected > maximum_expected:
    raise MotionInputError("program Modbus wait value is out of range")
  timeout = _main_modbus_wait_timeout_seconds(match.group("timeout"))
  controller_command = (
    f"{opcode}A{match.group('slave')}B{match.group('address')}"
    f"C{expected}D{timeout}\n"
  )
  serial_event_queue.put(
    ("started", controller_command, None, None, False, None, None)
  )
  execution_state, _ = _execute_row_main_response(
    controller_command,
    response_timeout=timeout + SERIAL_RESPONSE_MARGIN_SECONDS,
  )
  return execution_state


def _parse_program_modbus_condition(command, command_type):
  contract = {
    "If MBc": ("BB", "If MBcoil", "Coil", False),
    "If MBi": ("BC", "If MBinput", "Input", False),
    "If MBh": ("BH", "If MBhold reg", "Reg", True),
    "If MBI": ("BD", "If MBInput Reg", "Input Reg", True),
  }.get(command_type)
  if contract is None:
    raise MotionInputError("program Modbus condition framing is invalid")
  opcode, prefix, address_label, has_quantity = contract
  quantity_pattern = (
    r" Num Reg's \((?P<quantity>[0-9]+)\)" if has_quantity else ""
  )
  match = re.fullmatch(
    rf"{prefix} - SlaveID \((?P<slave>[0-9]+)\)"
    rf"{quantity_pattern} - {address_label} # "
    r"(?P<address>[0-9]+) = (?P<expected>[0-9]+) : "
    r"(?P<action>Call Prog .+|Jump to Tab \d+|Stop)",
    command,
  )
  if match is None:
    raise MotionInputError("program Modbus condition framing is invalid")
  quantity = match.groupdict().get("quantity") or "1"
  try:
    subcommand = build_controller_modbus_command(
      opcode, match.group("slave"), match.group("address"), quantity,
    )
  except MotionInputError as exc:
    if quantity.isdigit() and int(quantity) > 1:
      raise MotionInputError(
        "Modbus condition quantity must equal one"
      ) from exc
    raise
  action_text = match.group("action")
  if action_text == "Stop":
    action = ("stop", None)
  elif action_text.startswith("Call Prog "):
    action = ("call_program", action_text.removeprefix("Call Prog ") + ".ar4")
  else:
    action = ("jump_tab", action_text.removeprefix("Jump to Tab "))
  return subcommand, match.group("expected"), action


def _settle_program_modbus_condition(
  succeeded, expected, response, action, execution_request, selected_row,
  caller_program=None,
):
  if not succeeded or _reject_cancelled_program_row(execution_request):
    return False
  if response != expected:
    return True
  action_name, action_value = action
  if action_name == "call_program":
    return _call_program_from_current_row(
      action_value, execution_request, selected_row,
      caller_program=caller_program,
    )
  if action_name == "jump_tab":
    index = _program_tab_row_index(tab1.progView.get(0, "end"), action_value) - 1
    tab1.progView.selection_clear(0, END)
    tab1.progView.select_set(index)
  elif action_name == "stop" and action_value is None:
    stopProg()
  else:
    raise MotionInputError("program Modbus condition action is invalid")
  return True


def _main_timed_wait_seconds(value):
  wait_seconds = finite_number(value, "controller timed wait")
  if wait_seconds < 0:
    raise MotionInputError("controller timed wait must be non-negative")
  if wait_seconds > JSON_CONTROLLER_WAIT_MAXIMUM_SECONDS:
    raise MotionInputError("controller timed wait exceeds the firmware range")
  encoded = controller_protocol_decimal(wait_seconds, "controller timed wait")
  encoded_seconds = float(encoded)
  return encoded_seconds, encoded


def _finish_step_reverse_selection(sel_row):
  last = tab1.progView.index('end')
  for row in range(0, sel_row):
    tab1.progView.itemconfig(row, {'fg': "#9E9E9E"})
  tab1.progView.itemconfig(sel_row, {'fg': "#FF0000"})
  for row in range(sel_row + 1, last):
    tab1.progView.itemconfig(row, {'fg': "#EE5C42"})
  tab1.progView.selection_clear(0, END)
  sel_row -= 1
  tab1.progView.select_set(sel_row)
  try:
    selected_row = tab1.progView.curselection()[0]
    curRowEntryField.delete(0, 'end')
    curRowEntryField.insert(0, selected_row)
  except Exception:
    curRowEntryField.delete(0, 'end')
    curRowEntryField.insert(0, "---")


def _validated_program_row_content(command):
  if re.match(r"Virtual(?:\s|$)", command.strip()) and not _program_row_is_supported(command):
    raise MotionInputError("Virtual scene program row is not canonical")
  return command


def _tk_program_rows_snapshot():
  if threading.get_ident() != application_tk_thread_id:
    raise RuntimeError("program rows must be captured on the Tk event thread")
  raw_rows = tab1.progView.get(0, "end")
  if isinstance(raw_rows, (str, bytes, bytearray)) or not isinstance(
    raw_rows,
    (tuple, list),
  ):
    raise RuntimeError("robot program rows are not a sequence")
  return tuple(
    _validated_program_row_content(_decode_program_row_content(row)).strip()
    for row in raw_rows
  )


def _apply_program_selection_event(event):
  if not isinstance(event, ProgramSelectionEvent):
    raise TypeError("program selection event is invalid")
  if threading.get_ident() != application_tk_thread_id:
    raise RuntimeError(
      "program selection commitment must run on the Tk event thread"
    )
  if (
    application_closing.is_set()
    or _program_execution_request_cancelled(event.execution_request)
  ):
    return ProgramSelectionResult(False)

  selected_rows = tuple(tab1.progView.curselection())
  if len(selected_rows) > 1:
    raise RuntimeError(
      "program execution requires at most one selected row"
    )
  last_row = tab1.progView.index('end')
  if (
    isinstance(last_row, bool)
    or not isinstance(last_row, int)
    or last_row <= 0
  ):
    raise RuntimeError("robot program view has no executable rows")
  if selected_rows and (
    isinstance(selected_rows[0], bool)
    or not isinstance(selected_rows[0], int)
    or not 0 <= selected_rows[0] < last_row
  ):
    raise RuntimeError("robot program selection is out of range")

  if event.action == PROGRAM_SELECTION_EXECUTE_VIRTUAL_SCENE:
    snapshot = event.span_snapshot
    if tuple(selected_rows) != (snapshot.selected_row,):
      raise RuntimeError("program selection changed before Virtual scene execution")
    if _tk_program_rows_snapshot() != snapshot.rows:
      raise RuntimeError("robot program changed before Virtual scene execution")
    return ProgramSelectionResult(
      _execute_virtual_scene_program_row(snapshot.selected_command)
    )

  if event.action == PROGRAM_SELECTION_CAPTURE_SPAN:
    if len(selected_rows) != 1:
      raise RuntimeError(
        "program span capture requires exactly one selected row"
      )
    rows = _tk_program_rows_snapshot()
    if len(rows) != last_row:
      raise RuntimeError("robot program row count changed during capture")
    snapshot = ProgramRowSpanSnapshot(
      rows,
      selected_rows[0],
      "".join(
        str(CAL[f'J{axis}OpenLoopVal'].get())
        for axis in range(1, 7)
      ),
      str(CAL['DisableWristRotVal'].get()),
    )
    try:
      tab1.progView.see(snapshot.selected_row + 2)
    except Exception:
      logger.exception("Unable to scroll the robot program view")
    return ProgramSelectionResult(True, span_snapshot=snapshot)

  if event.action == PROGRAM_SELECTION_COMMIT_SPAN:
    snapshot = event.span_snapshot
    if tuple(selected_rows) != (snapshot.selected_row,):
      raise RuntimeError(
        "robot program selection changed before span commitment"
      )
    if _tk_program_rows_snapshot() != snapshot.rows:
      raise RuntimeError("robot program changed before span commitment")
    tab1.progView.selection_clear(0, END)
    tab1.progView.select_set(event.final_row)
    if tuple(tab1.progView.curselection()) != (event.final_row,):
      raise RuntimeError("completed program span could not be selected")
    try:
      tab1.progView.see(event.final_row + 2)
    except Exception:
      logger.exception("Unable to scroll the robot program view")
    return ProgramSelectionResult(True)

  if event.action == PROGRAM_SELECTION_INITIALIZE_RUN:
    for row in range(0, last_row):
      tab1.progView.itemconfig(row, {'fg': "#FFFFFF"})
    if not selected_rows:
      if last_row <= 1:
        raise RuntimeError("robot program view has no executable row")
      tab1.progView.selection_clear(0, END)
      tab1.progView.select_set(1)
      if tuple(tab1.progView.curselection()) != (1,):
        raise RuntimeError("program execution could not select the first row")
    return ProgramSelectionResult(True)

  if event.action == PROGRAM_SELECTION_PREPARE_RUN:
    if selected_rows:
      return ProgramSelectionResult(True)
    if tab1.lastProg == "":
      index = _program_row_index(
        tab1.progView.get(0, "end"),
        "## START PROGRAM LOOP ##",
      )
      tab1.progView.selection_clear(0, END)
      tab1.progView.select_set(index)
      if tuple(tab1.progView.curselection()) != (index,):
        raise RuntimeError(
          "program execution could not select the program-loop entry"
        )
      return ProgramSelectionResult(True)
    if (
      not isinstance(tab1.lastProg, str)
      or not tab1.lastProg
      or "\r" in tab1.lastProg
      or "\n" in tab1.lastProg
      or isinstance(tab1.lastRow, bool)
      or not isinstance(tab1.lastRow, int)
      or tab1.lastRow < -1
    ):
      raise RuntimeError("program caller return state is invalid")
    return ProgramSelectionResult(
      True,
      (tab1.lastProg, tab1.lastRow + 1),
    )

  if event.action != PROGRAM_SELECTION_ADVANCE:
    raise RuntimeError("program selection action was not implemented")
  if len(selected_rows) != 1:
    raise RuntimeError(
      "completed program row does not have one selected row"
    )
  selected_row = selected_rows[0]

  next_row = selected_row + 1
  tab1.progView.selection_clear(0, END)
  if next_row < last_row:
    tab1.progView.select_set(next_row)
    expected_selection = (next_row,)
    displayed_row = next_row
  else:
    expected_selection = ()
    displayed_row = "---"
  if tuple(tab1.progView.curselection()) != expected_selection:
    raise RuntimeError(
      "program selection did not advance after the completed row"
    )

  try:
    curRowEntryField.delete(0, 'end')
    curRowEntryField.insert(0, displayed_row)
  except Exception:
    logger.exception("Unable to update the current program-row display")

  if event.style_rows:
    try:
      for row in range(0, selected_row):
        tab1.progView.itemconfig(row, {'fg': "#1E90FF"})
      tab1.progView.itemconfig(selected_row, {'fg': "#0561BD"})
      for row in range(selected_row + 1, last_row):
        tab1.progView.itemconfig(row, {'fg': "#9E9E9E"})
    except Exception:
      logger.exception("Unable to update Step Forward row styling")
  return ProgramSelectionResult(True)


def _settle_program_selection(event):
  if not isinstance(event, ProgramSelectionEvent):
    raise TypeError("program selection event is invalid")
  try:
    result = _apply_program_selection_event(event)
  except Exception as exc:
    event.settle(error=exc)
    logger.exception("Unable to apply a program selection event")
    return False
  except BaseException as exc:
    event.settle(
      error=RuntimeError(
        "program selection event aborted by "
        f"{type(exc).__name__}"
      )
    )
    raise
  event.settle(result=result)
  return True


def _poll_program_selection_events():
  try:
    _apply_requested_robot_program_return_state_clear()
    while True:
      try:
        event = program_selection_event_queue.get_nowait()
      except Empty:
        break
      _settle_program_selection(event)
  except Exception:
    logger.exception("Unable to settle a program selection event")
  finally:
    _reschedule_event_poll("program-selection")


def _dispatch_program_selection(event):
  if not isinstance(event, ProgramSelectionEvent):
    raise TypeError("program selection dispatch is invalid")
  if threading.get_ident() == application_tk_thread_id:
    _settle_program_selection(event)
    return event.wait()
  with application_lifecycle_lock:
    if application_closing.is_set():
      event.settle(result=ProgramSelectionResult(False))
    else:
      program_selection_event_queue.put(event)
  return event.wait()


def _virtual_motion_active(ignored_request_lease=None):
  if (
    ignored_request_lease is not None
    and not motion_request_registry.owns(ignored_request_lease)
  ):
    raise RuntimeError("ignored virtual-motion request lease is not active")
  with offline_live_jog_state_lock:
    if offline_live_jog_operation is not None:
      return True
  return (
    (
      motion_request_registry.active
      and ignored_request_lease is None
    )
    or offline_live_jog_lock.locked()
    or live_jog_lock.locked()
    or live_cartesian_lock.locked()
    or live_tool_lock.locked()
    or drive_lock.locked()
  )


def _motion_request_rejection_message(fallback):
  if not isinstance(fallback, str) or not fallback:
    raise TypeError("motion request rejection fallback must be non-empty text")
  reason = getattr(motion_request_admission_state, "rejection_reason", None)
  if isinstance(reason, str) and reason:
    return reason
  return fallback


def _motion_request_rejection_is_deferrable():
  return getattr(
    motion_request_admission_state,
    "rejection_deferrable",
    True,
  ) is True


def _reject_motion_request(name, reason, *, deferrable=True):
  if not isinstance(deferrable, bool):
    raise TypeError("motion rejection deferral flag must be boolean")
  message = f"{name} not started; {reason}"
  motion_request_admission_state.rejection_reason = message
  motion_request_admission_state.rejection_deferrable = deferrable
  logger.warning(message)
  return None


def _acquire_motion_request(
  name,
  allow_position_recovery=False,
  requires_kinematics=True,
  allow_gcode_conversion=False,
  allow_uncalibrated=False,
):
  if not isinstance(allow_position_recovery, bool):
    raise TypeError("position-recovery admission flag must be boolean")
  if not isinstance(requires_kinematics, bool):
    raise TypeError("kinematics admission flag must be boolean")
  if not isinstance(allow_gcode_conversion, bool):
    raise TypeError("G-code conversion admission flag must be boolean")
  if not isinstance(allow_uncalibrated, bool):
    raise TypeError("uncalibrated admission flag must be boolean")
  motion_request_admission_state.rejection_reason = None
  motion_request_admission_state.rejection_deferrable = True
  if application_closing.is_set():
    return _reject_motion_request(name, "application shutdown is active")
  conversion_active = gcode_conversion_active.is_set()
  if conversion_active and not allow_gcode_conversion:
    return _reject_motion_request(
      name,
      "G-code conversion owns motion admission",
    )
  if allow_gcode_conversion and not conversion_active:
    return _reject_motion_request(
      name,
      "G-code conversion admission is unavailable",
    )
  if requires_kinematics and not kinematics_configuration_ready.is_set():
    return _reject_motion_request(
      name,
      "native kinematics configuration is unavailable",
    )
  if (
    requires_kinematics
    and not allow_uncalibrated
    and not RUN['offlineMode']
    and _current_main_controller_identity() is not None
    and not _current_session_primary_calibration_ready()
  ):
    return _reject_motion_request(
      name,
      "current controller session requires J1-J6 calibration",
      deferrable=False,
    )
  if not allow_position_recovery and (
    manual_motion_pose_pending.is_set()
    or controller_position_resynchronization_required.is_set()
  ):
    return _reject_motion_request(
      name,
      "controller position resynchronization is required",
    )
  lease = motion_request_registry.acquire(name)
  if lease is None:
    owner = motion_request_registry.active_name
    return _reject_motion_request(
      name,
      f"{owner or 'another request'} owns motion",
    )
  return lease


def _finish_motion_request(
  request_lease,
  completion_callback=None,
  succeeded=None,
):
  if not isinstance(request_lease, MotionRequestLease):
    raise TypeError("motion request completion requires a valid lease")
  if completion_callback is not None and not callable(completion_callback):
    raise TypeError("motion request completion callback must be callable")
  if completion_callback is not None and not isinstance(succeeded, bool):
    raise TypeError("motion request callback requires a boolean result")
  if request_lease.close() is not True:
    raise RuntimeError("motion request result reused a released lease")
  try:
    if completion_callback is not None:
      completion_callback(succeeded)
  finally:
    virtual_motion_event_queue.put(("motion-released", None))
  return True


def _manual_motion_request(name):
  def decorate(callback):
    @wraps(callback)
    def guarded(*args, **kwargs):
      # Admission precedes coordinate reads; only an admitted virtual request
      # transfers this lease beyond the callback's synchronous lifetime.
      request_lease = _acquire_motion_request(name)
      if request_lease is None:
        message = _motion_request_rejection_message(
          f"{name} not started; another motion request is active"
        )
        _set_application_status(message, "Warn.TLabel")
        return False
      if getattr(manual_motion_request_state, "lease", None) is not None:
        _finish_motion_request(request_lease)
        raise RuntimeError("nested manual motion request is not supported")
      manual_motion_request_state.lease = request_lease
      manual_motion_request_state.transferred = False
      try:
        return callback(*args, **kwargs)
      finally:
        transferred = manual_motion_request_state.transferred
        manual_motion_request_state.lease = None
        manual_motion_request_state.transferred = False
        if not transferred and motion_request_registry.owns(request_lease):
          _finish_motion_request(request_lease)
    return guarded
  return decorate


def _start_manual_motion(
  physical_command,
  motion_name,
  virtual_dispatch,
  virtual_command,
):
  request_lease = getattr(manual_motion_request_state, "lease", None)
  if not motion_request_registry.owns(request_lease):
    raise RuntimeError("manual motion requires matching request ownership")
  if not callable(virtual_dispatch):
    raise TypeError("manual virtual dispatch must be callable")

  try:
    virtual_wrist_config = parse_motion_wrist_config(
      virtual_command,
      virtual=True,
    )
    if physical_command is not None:
      physical_wrist_config = parse_motion_wrist_config(
        physical_command,
        virtual=False,
      )
      if physical_wrist_config != virtual_wrist_config:
        raise MotionInputError(
          "physical and virtual wrist configurations must match"
        )
  except (TypeError, ValueError, MotionInputError) as exc:
    message = f"{motion_name} rejected because the wrist mode is invalid: {exc}"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
    return False

  try:
    if RUN['offlineMode']:
      saved_controller_positions = None
      saved_virtual_pose = tuple(
        finite_number(value, f"saved virtual joint {axis}")
        for axis, value in enumerate(RUN['VR_angles'], start=1)
      )
      if len(saved_virtual_pose) != 6:
        raise MotionInputError("saved virtual pose must contain six joints")
    else:
      saved_controller_positions = _current_joint_positions()
      saved_virtual_pose = saved_controller_positions[:6]
  except (KeyError, TypeError, ValueError, MotionInputError) as exc:
    message = f"{motion_name} rejected because the confirmed pose is invalid: {exc}"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
    return False

  def apply_confirmed_pose(controller_positions, virtual_pose):
    try:
      if controller_positions is not None and (
        joint_motion_dispatcher.synchronize(controller_positions) is not True
      ):
        raise MotionQueueFault(
          "joint dispatcher rejected confirmed-position synchronization"
        )
      if controller_positions is None:
        if refresh_gui_from_joint_angles(virtual_pose) is not True:
          raise MotionQueueFault("virtual GUI rejected confirmed position")
      elif _try_set_virtual_joint_target(virtual_pose) is not True:
        raise MotionQueueFault("virtual model rejected confirmed position")
    except (KeyError, TypeError, ValueError, MotionInputError, MotionQueueFault) as exc:
      logger.error("Unable to restore confirmed manual-motion pose: %s", exc)
      return False
    return True

  def require_controller_resynchronization():
    _require_controller_position_resynchronization()

  def restore_untransmitted_preview():
    restored = apply_confirmed_pose(
      saved_controller_positions,
      saved_virtual_pose,
    )
    if not restored and not RUN['offlineMode']:
      require_controller_resynchronization()
    return restored

  try:
    virtual_completion_timeout = _virtual_completion_timeout(virtual_command)
    virtual_operation = virtual_dispatch(virtual_command)
  except Exception as exc:
    restore_untransmitted_preview()
    message = f"{motion_name} virtual preview did not start: {exc}"
    logger.exception(message)
    _set_application_status(message, "Alarm.TLabel")
    return False
  if not isinstance(virtual_operation, VirtualMotionOperation):
    restore_untransmitted_preview()
    message = f"{motion_name} virtual preview did not publish an operation"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
    return False
  if virtual_operation.completed:
    virtual_succeeded, virtual_error = virtual_operation.result()
    if not virtual_succeeded:
      restore_untransmitted_preview()
      message = f"{motion_name} virtual preview failed: {virtual_error}"
      logger.error(message)
      _set_application_status(message, "Alarm.TLabel")
      return False

  virtual_completion_deadline = time.monotonic() + virtual_completion_timeout
  controller_write_started = (
    threading.Event()
    if physical_command is not None
    else None
  )
  controller_state = {
    "succeeded": physical_command is None,
    "speed_violation": False,
    "position_known": physical_command is None,
    "confirmed_position_unchanged": False,
    "error": None,
  }
  if physical_command is not None:
    manual_motion_pose_pending.set()

  def reconcile_manual_motion(succeeded):
    pose_confirmed = True
    try:
      if physical_command is None:
        if succeeded:
          pose_confirmed = apply_confirmed_pose(
            None,
            tuple(RUN['VR_angles']),
          )
        else:
          pose_confirmed = restore_untransmitted_preview()
      elif controller_state["position_known"]:
        if controller_state["confirmed_position_unchanged"]:
          pose_confirmed = restore_untransmitted_preview()
        else:
          try:
            controller_positions = _current_joint_positions()
          except (KeyError, TypeError, ValueError, MotionInputError) as exc:
            logger.error("Unable to read confirmed controller pose: %s", exc)
            pose_confirmed = False
          else:
            pose_confirmed = apply_confirmed_pose(
              controller_positions,
              controller_positions[:6],
            )
      elif not controller_write_started.is_set():
        pose_confirmed = restore_untransmitted_preview()
      else:
        pose_confirmed = False

      if physical_command is not None:
        if pose_confirmed:
          controller_position_resynchronization_required.clear()
        else:
          require_controller_resynchronization()
    finally:
      manual_motion_pose_pending.clear()

    return succeeded and pose_confirmed

  def complete_manual_motion(succeeded):
    if succeeded:
      if not controller_state["speed_violation"]:
        _set_application_status("SYSTEM READY", "OK.TLabel")
      return
    if controller_position_resynchronization_required.is_set():
      message = (
        f"{motion_name} failed; controller position resynchronization is required"
      )
    elif controller_state["error"] is not None:
      message = f"{motion_name} failed: {controller_state['error']}"
    else:
      message = f"{motion_name} failed during controller or virtual settlement"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")

  def settle(controller_result):
    if physical_command is None:
      if controller_result is not None:
        raise RuntimeError(
          "offline manual motion received a physical controller result"
        )
      controller_state["succeeded"] = True
      controller_state["speed_violation"] = False
      controller_state["position_known"] = True
      controller_state["confirmed_position_unchanged"] = False
      controller_state["error"] = None
    else:
      if controller_result is not None and not isinstance(
        controller_result,
        (PositionResponse, JointMotionExchangeResult),
      ):
        raise RuntimeError(
          "manual motion completion returned an invalid controller result"
        )
      if isinstance(controller_result, JointMotionExchangeResult):
        position = controller_result.position
        physical_stop = position_response_is_physical_estop(position)
        controller_state["succeeded"] = (
          controller_result.error is None and not physical_stop
        )
        controller_state["speed_violation"] = (
          position is not None and position.speed_violation
        )
        controller_state["position_known"] = (
          not physical_stop
          and (
            position is not None
            or controller_result.confirmed_position_unchanged
          )
        )
        controller_state["confirmed_position_unchanged"] = (
          controller_result.confirmed_position_unchanged
        )
        controller_state["error"] = controller_result.error
      else:
        controller_state["succeeded"] = controller_result is not None
        controller_state["speed_violation"] = (
          controller_result is not None
          and controller_result.speed_violation
        )
        controller_state["position_known"] = controller_result is not None
        controller_state["confirmed_position_unchanged"] = False
        controller_state["error"] = None
    _complete_program_motion_when_virtual_idle(
      complete_manual_motion,
      request_lease,
      virtual_operation,
      virtual_completion_timeout,
      controller_succeeded=controller_state["succeeded"],
      deadline=virtual_completion_deadline,
      settlement_callback=reconcile_manual_motion,
    )

  manual_motion_request_state.transferred = True
  if physical_command is None:
    settle(None)
    return True

  try:
    if physical_command.startswith(("MJ", "ML", "MV")):
      motion_starter = _start_cartesian_motion
    elif physical_command.startswith("JT"):
      motion_starter = _start_tool_jog
    elif physical_command.startswith("RJ"):
      motion_starter = _start_program_joint_motion
    else:
      raise MotionInputError("manual motion command lacks a JSON route")
    controller_started = motion_starter(
      physical_command,
      motion_name,
      completion_callback=settle,
      request_lease=request_lease,
      write_started_event=controller_write_started,
    )
  except Exception:
    logger.exception("%s controller worker failed during startup", motion_name)
    controller_started = False
  if not controller_started:
    settle(None)
  return controller_started


def _virtual_completion_timeout(command):
  timing = parse_virtual_command_timing(command)
  minimum_ramp_full_scale_seconds, millimeter_motion_distance_bound = (
    _configured_motion_timeout_bounds()
  )
  timeout = motion_timing_response_timeout(
    timing,
    VIRTUAL_COMPLETION_BASE_TIMEOUT_SECONDS,
    minimum_ramp_full_scale_seconds,
    millimeter_motion_distance_bound,
    margin_seconds=SERIAL_RESPONSE_MARGIN_SECONDS,
  )
  if timing.mode == "s":
    simulated_duration = timing.speed * max(
      VIRTUAL_JOINT_SECONDS_SCALE,
      VIRTUAL_CARTESIAN_SECONDS_SCALE,
      VIRTUAL_TOOL_SECONDS_SCALE,
    )
    timeout = max(
      timeout,
      simulated_duration * VIRTUAL_COMPLETION_SAFETY_SCALE
      + SERIAL_RESPONSE_MARGIN_SECONDS,
    )
  return timeout


def _finish_settled_motion_request(
  completion_callback,
  request_lease,
  succeeded,
  settlement_callback=None,
):
  if not isinstance(succeeded, bool):
    raise TypeError("motion settlement result must be boolean")
  if settlement_callback is not None:
    if not callable(settlement_callback):
      raise TypeError("motion settlement callback must be callable")
    try:
      succeeded = settlement_callback(succeeded)
    except BaseException:
      logger.exception("Unable to reconcile motion state before ownership release")
      succeeded = False
    if not isinstance(succeeded, bool):
      logger.error("Motion settlement callback returned a non-boolean result")
      succeeded = False
  return _finish_motion_request(
    request_lease,
    completion_callback,
    succeeded,
  )


def _complete_program_motion_when_virtual_idle(
  completion_callback,
  request_lease,
  operation,
  timeout,
  controller_succeeded=True,
  deadline=None,
  timed_out=False,
  settlement_callback=None,
):
  if not isinstance(operation, VirtualMotionOperation):
    logger.error("Virtual program motion did not publish an operation result")
    _finish_settled_motion_request(
      completion_callback,
      request_lease,
      False,
      settlement_callback,
    )
    return
  if deadline is None:
    deadline = time.monotonic() + timeout
  if not timed_out and time.monotonic() >= deadline:
    logger.error("Virtual program motion did not finish before timeout")
    timed_out = True
  if not operation.completed:
    try:
      root.after(
        VIRTUAL_COMPLETION_POLL_MS,
        lambda: _complete_program_motion_when_virtual_idle(
          completion_callback,
          request_lease,
          operation,
          timeout,
          controller_succeeded,
          deadline,
          timed_out,
          settlement_callback,
        ),
      )
    except Exception:
      logger.exception("Unable to schedule virtual program completion")
      fallback_started = _start_program_completion_fallback(
        completion_callback,
        request_lease,
        operation,
        controller_succeeded,
        deadline,
        timed_out,
        settlement_callback,
      )
      if not fallback_started:
        _finish_settled_motion_request(
          completion_callback,
          request_lease,
          _program_completion_fallback_result(
            operation,
            controller_succeeded,
            deadline,
            timed_out,
          ),
          settlement_callback,
        )
    return
  succeeded, error = operation.result()
  if not succeeded:
    logger.error("Virtual program motion failed: %s", error)
  _finish_settled_motion_request(
    completion_callback,
    request_lease,
    controller_succeeded is True and succeeded and not timed_out,
    settlement_callback,
  )


def _program_completion_fallback_result(
  operation,
  controller_succeeded,
  deadline,
  timed_out,
):
  while not operation.completed:
    if not timed_out and time.monotonic() >= deadline:
      logger.error("Virtual program motion did not finish before timeout")
      timed_out = True
    operation.wait(JSON_SERIAL_DEFAULT_POLL_INTERVAL_SECONDS)
  if not timed_out and time.monotonic() >= deadline:
    logger.error("Virtual program motion did not finish before timeout")
    timed_out = True
  succeeded, error = operation.result()
  if not succeeded:
    logger.error("Virtual program motion failed: %s", error)
  return controller_succeeded is True and succeeded and not timed_out


def _run_program_completion_fallback(
  completion_callback,
  request_lease,
  operation,
  controller_succeeded,
  deadline,
  timed_out,
  settlement_callback,
):
  succeeded = _program_completion_fallback_result(
    operation,
    controller_succeeded,
    deadline,
    timed_out,
  )
  virtual_motion_event_queue.put((
    "program-completion",
    (
      completion_callback,
      request_lease,
      succeeded,
      settlement_callback,
    ),
  ))


def _start_program_completion_fallback(
  completion_callback,
  request_lease,
  operation,
  controller_succeeded,
  deadline,
  timed_out,
  settlement_callback,
):
  try:
    thread = threading.Thread(
      target=_run_program_completion_fallback,
      args=(
        completion_callback,
        request_lease,
        operation,
        controller_succeeded,
        deadline,
        timed_out,
        settlement_callback,
      ),
      daemon=True,
    )
    thread.start()
  except Exception:
    logger.exception("Unable to retain virtual program completion ownership")
    return False
  return True


def _wait_for_virtual_motion_operation(operation, timeout, deadline=None):
  if not isinstance(operation, VirtualMotionOperation):
    logger.error("Virtual program motion did not publish an operation result")
    return False
  if deadline is None:
    deadline = time.monotonic() + timeout
  timed_out = False
  while not operation.completed:
    remaining = deadline - time.monotonic()
    if not timed_out and remaining <= 0:
      logger.error("Virtual program motion did not finish before timeout")
      timed_out = True
    operation.wait(JSON_SERIAL_DEFAULT_POLL_INTERVAL_SECONDS)
  if not timed_out and time.monotonic() >= deadline:
    logger.error("Virtual program motion did not finish before timeout")
    timed_out = True
  succeeded, error = operation.result()
  if not succeeded:
    logger.error("Virtual program motion failed: %s", error)
  return succeeded and not timed_out


def _complete_step_reverse_motion(sel_row, succeeded):
  _finish_execute_row()
  if succeeded:
    _finish_step_reverse_selection(sel_row)


def _start_program_controller_exchange(
  command, operation_name, completion_callback, *,
  controller_wait_seconds=None, response_timeout=None,
  settlement_callback_factory=None,
):
  if not isinstance(operation_name, str) or not operation_name or (
    operation_name != operation_name.strip()
  ):
    raise TypeError("program controller operation name is invalid")
  if not callable(completion_callback):
    raise TypeError("program controller completion callback is invalid")
  if settlement_callback_factory is not None and not callable(
    settlement_callback_factory
  ):
    raise TypeError("program controller settlement factory is invalid")
  request_lease = _acquire_motion_request(operation_name, requires_kinematics=False)
  if request_lease is None:
    message = _motion_request_rejection_message(
      f"{operation_name} not started; motion admission was rejected"
    )
    _set_application_status(message, "Warn.TLabel")
    return False

  def exchange_worker():
    succeeded = False
    settlement_callback = None
    try:
      exchange_options = {"request_lease": request_lease}
      if controller_wait_seconds is not None or response_timeout is not None:
        exchange_options.update(
          controller_wait_seconds=controller_wait_seconds, response_timeout=response_timeout,
        )
      execution_state, value = _execute_row_main_command(command, **exchange_options)
      succeeded = execution_state == ROW_EXECUTION_COMPLETE
      if succeeded and settlement_callback_factory is not None:
        settlement_callback = settlement_callback_factory(value)
        if not callable(settlement_callback):
          raise RuntimeError("program controller settlement is invalid")
    except BaseException:
      succeeded = False
      settlement_callback = None
      logger.exception("Program controller exchange worker failed")
      _queue_program_execution_status(f"{operation_name.upper()} FAILED", "Alarm.TLabel")
    finally:
      virtual_motion_event_queue.put((
        "program-completion",
        (completion_callback, request_lease, succeeded, settlement_callback),
      ))

  try:
    threading.Thread(target=exchange_worker, daemon=True).start()
  except Exception:
    logger.exception("Unable to start program controller exchange worker")
    _finish_motion_request(request_lease)
    _set_application_status(f"UNABLE TO START {operation_name.upper()}", "Alarm.TLabel")
    return False
  return True


def _start_controller_motion(
  command,
  motion_name,
  *,
  exchange,
  completion_callback=None,
  request_lease=None,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if not motion_request_registry.owns(request_lease):
    raise RuntimeError("controller motion requires matching request ownership")
  if start_send_serial_thread(
    command,
    completion_callback=completion_callback,
    write_started_event=write_started_event,
    write_cancellation_boundary=write_cancellation_boundary,
    exchange=exchange,
  ):
    return True
  message = f"{motion_name} not started; controller transport is unavailable"
  logger.warning(message)
  _set_application_status(text=message, style="Warn.TLabel")
  return False


