def _configuration_number(key):
  try:
    raw_value = CAL[key]
  except (KeyError, TypeError) as exc:
    raise MotionInputError(f"invalid controller timing configuration {key!r}") from exc
  return finite_number(raw_value, f"controller timing configuration {key!r}")


def _runtime_number(key):
  try:
    raw_value = RUN[key]
  except (KeyError, TypeError) as exc:
    raise MotionInputError(f"invalid controller runtime value {key!r}") from exc
  return finite_number(raw_value, f"controller runtime value {key!r}")


def _configured_motion_timeout_bounds():
  axis_step_ranges = []
  for axis in range(1, 7):
    positive_limit = _configuration_number(f'J{axis}PosLim')
    negative_limit = _configuration_number(f'J{axis}NegLim')
    steps_per_degree = _configuration_number(f'J{axis}StepDeg')
    if positive_limit < 0 or negative_limit < 0 or steps_per_degree <= 0:
      raise MotionInputError(f"J{axis} motion timing configuration is out of range")
    axis_step_ranges.append(
      (positive_limit + negative_limit) * steps_per_degree
    )

  external_lengths = []
  for axis, length_key in ((7, 'J7PosLim'), (8, 'J8length'), (9, 'J9length')):
    length = _configuration_number(length_key)
    rotation = _configuration_number(f'J{axis}rotation')
    steps = _configuration_number(f'J{axis}steps')
    if length < 0 or rotation <= 0 or steps <= 0:
      raise MotionInputError(f"J{axis} motion timing configuration is out of range")
    external_lengths.append(length)
    axis_step_ranges.append(length * (steps / rotation))

  maximum_steps = max(axis_step_ranges)
  minimum_step_delay = _runtime_number('minSpeedDelay')
  if minimum_step_delay <= 0:
    raise MotionInputError("controller minimum step delay must be positive and finite")
  distribution_delay = (
    minimum_step_delay
    + FIRMWARE_DISTRIBUTION_DELAY_MICROSECONDS * FIRMWARE_AXIS_COUNT
  )
  minimum_ramp_full_scale_seconds = (
    maximum_steps * distribution_delay / 1_000_000.0
  )
  if (
    not math.isfinite(minimum_ramp_full_scale_seconds)
    or minimum_ramp_full_scale_seconds <= 0
  ):
    raise MotionInputError("configured full-scale motion duration is invalid")

  link_extent = sum(
    abs(_configuration_number(f'J{axis}{parameter}DHpar'))
    for axis in range(1, 7)
    for parameter in ('a', 'd')
  )
  tool_extent = math.sqrt(sum(
    _configuration_number(key) ** 2
    for key in ('TFx', 'TFy', 'TFz')
  ))
  maximum_radius = link_extent + tool_extent + sum(external_lengths)
  millimeter_motion_distance_bound = max(
    2.0 * math.pi * maximum_radius,
    minimum_ramp_full_scale_seconds * FIRMWARE_MAX_MILLIMETERS_PER_SECOND,
  )
  if (
    not math.isfinite(millimeter_motion_distance_bound)
    or millimeter_motion_distance_bound <= 0
  ):
    raise MotionInputError("configured Cartesian path bound is invalid")

  return minimum_ramp_full_scale_seconds, millimeter_motion_distance_bound


def _controller_response_timeout(command):
  if isinstance(command, ProgramJsonCartesianMotion):
    if command.command_name != "move_spline":
      return _controller_response_timeout(command.motion_commands[0])
    minimum_ramp_full_scale_seconds, millimeter_motion_distance_bound = (
      _configured_motion_timeout_bounds()
    )
    deadline = sum(
      command_response_timeout(
        segment,
        SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
        minimum_ramp_full_scale_seconds,
        millimeter_motion_distance_bound,
        margin_seconds=0.0,
      )
      for segment in command.motion_commands
    ) + SERIAL_RESPONSE_MARGIN_SECONDS
    if not math.isfinite(deadline) or deadline <= 0:
      raise MotionInputError("derived spline response deadline is invalid")
    return deadline
  timing = parse_command_timing(command)
  if timing is None:
    return SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS

  minimum_ramp_full_scale_seconds, millimeter_motion_distance_bound = (
    _configured_motion_timeout_bounds()
  )
  return command_response_timeout(
    command,
    SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
    minimum_ramp_full_scale_seconds,
    millimeter_motion_distance_bound,
    margin_seconds=SERIAL_RESPONSE_MARGIN_SECONDS,
  )


def _canonicalize_main_serial_command(command):
  if isinstance(command, ProgramJsonCartesianMotion):
    return ProgramJsonCartesianMotion(
      command.command_name,
      tuple(
        _canonicalize_main_serial_command(segment)
        for segment in command.motion_commands
      ),
      command.control_points,
      command.roundings_millimeters,
    )
  calibration = None
  if isinstance(command, str) and command[:2] in (
    "MJ", "ML", "MV", "RJ", "WC",
  ):
    calibration = _current_controller_joint_calibration()
  return canonicalize_serial_command(command, calibration)


def _raise_auxiliary_stop_acknowledgement_timeout():
  serial_port = RUN.get('ser2')
  if serial_port is not None:
    try:
      quarantine_serial_transport(
        serial_port,
        "auxiliary stop acknowledgement deadline expired",
      )
    except Exception:
      logger.exception("Unable to close auxiliary transport after stop timeout")
  raise SerialTransportTimeout(
    "auxiliary stop acknowledgement deadline expired"
  )


def _begin_auxiliary_stop_owner_wait():
  global auxiliary_stop_acknowledgement_deadline
  global auxiliary_stop_owner_waiting

  with auxiliary_stop_state_lock:
    if auxiliary_stop_owner_waiting:
      raise RuntimeError("auxiliary stop owner wait was already active")
    auxiliary_stop_acknowledgement_deadline = None
    auxiliary_stop_owner_waiting = True


def _publish_auxiliary_stop_owner_result(
  succeeded,
  value,
  *,
  stop_transmitted=False,
):
  global auxiliary_stop_acknowledgement_deadline
  global auxiliary_stop_owner_result
  global auxiliary_stop_owner_waiting

  validation_error = None
  if not isinstance(succeeded, bool):
    validation_error = "auxiliary stop owner result must use a boolean status"
  elif not isinstance(stop_transmitted, bool):
    validation_error = "auxiliary stop transmission state must be boolean"
  elif not isinstance(value, str):
    validation_error = "auxiliary stop owner result must contain text"
  else:
    value = value.strip()
    if succeeded and value not in AUXILIARY_STOP_OWNER_RESPONSES:
      validation_error = "unexpected auxiliary wait terminal response"
    elif not value:
      value = "auxiliary wait owner ended without a terminal response"

  with auxiliary_stop_state_lock:
    if not auxiliary_stop_owner_waiting:
      raise RuntimeError("auxiliary stop owner wait was not active")
    request_id = auxiliary_stop_active_request_id
    if (
      validation_error is None
      and succeeded
      and request_id is not None
      and not stop_transmitted
    ):
      return False
    auxiliary_stop_owner_waiting = False
    if request_id is not None:
      if auxiliary_stop_owner_result is not None:
        raise RuntimeError("auxiliary stop owner result was already published")
      if validation_error is not None:
        auxiliary_stop_owner_result = (request_id, False, validation_error)
      else:
        auxiliary_stop_owner_result = (request_id, succeeded, value)
      auxiliary_stop_owner_result_event.set()
    auxiliary_stop_injected_event.clear()
    auxiliary_stop_acknowledgement_deadline = None
  if validation_error is not None:
    raise ProtocolResponseError(validation_error)
  return True


def _run_auxiliary_stop_safe(request_id, control_mode):
  global auxiliary_stop_acknowledgement_deadline
  global auxiliary_stop_active_request_id
  global auxiliary_stop_owner_result

  terminal_type = "completed"
  terminal_value = ""
  auxiliary_serial_event_queue.put(("started", request_id, "stop"))
  try:
    if control_mode == SerialActivityRegistry.CONTROL_INJECT:
      acknowledgement_deadline = (
        time.monotonic() + SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS
      )
      with auxiliary_stop_state_lock:
        if auxiliary_stop_active_request_id != request_id:
          raise RuntimeError("auxiliary stop request ownership changed before wait")
        auxiliary_stop_acknowledgement_deadline = acknowledgement_deadline
      auxiliary_stop_injected_event.set()
      while True:
        remaining = acknowledgement_deadline - time.monotonic()
        if remaining <= 0:
          _raise_auxiliary_stop_acknowledgement_timeout()
        if auxiliary_stop_owner_result_event.wait(
          min(JSON_SERIAL_DEFAULT_POLL_INTERVAL_SECONDS, remaining)
        ):
          break
      with auxiliary_stop_state_lock:
        owner_result = auxiliary_stop_owner_result
        if (
          not isinstance(owner_result, tuple)
          or len(owner_result) != 3
          or owner_result[0] != request_id
          or not isinstance(owner_result[1], bool)
          or not isinstance(owner_result[2], str)
        ):
          raise RuntimeError("auxiliary stop owner result is invalid")
        _, owner_succeeded, terminal_value = owner_result
        auxiliary_stop_owner_result = None
        auxiliary_stop_owner_result_event.clear()
      if not owner_succeeded:
        raise RuntimeError(terminal_value)
    elif control_mode == SerialActivityRegistry.CONTROL_EXCLUSIVE:
      acquired = auxiliary_serial_lock.acquire()
      if acquired is False:
        raise RuntimeError("auxiliary stop transport acquisition failed")
      try:
        _exchange_json_auxiliary_command(
          "stop",
          {},
          SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS,
          RUN.get('ser2'),
        )
      finally:
        auxiliary_serial_lock.release()
      terminal_value = "Stopped"
    else:
      raise RuntimeError("auxiliary stop received an invalid control mode")
  except Exception as exc:
    terminal_type = "failed"
    terminal_value = str(exc).strip() or "auxiliary stop failed without details"

  cleanup_errors = []
  try:
    serial_activity_registry.finish_control("ser2", control_mode)
  except Exception as exc:
    cleanup_errors.append(f"control ownership cleanup failed: {exc}")
  with auxiliary_stop_state_lock:
    if auxiliary_stop_active_request_id != request_id:
      cleanup_errors.append("auxiliary stop request ownership changed unexpectedly")
    else:
      auxiliary_stop_active_request_id = None
    if (
      isinstance(auxiliary_stop_owner_result, tuple)
      and auxiliary_stop_owner_result[0] == request_id
    ):
      auxiliary_stop_owner_result = None
      auxiliary_stop_owner_result_event.clear()
    if (
      not auxiliary_stop_owner_waiting
      or auxiliary_stop_acknowledgement_deadline is None
    ):
      auxiliary_stop_injected_event.clear()
      auxiliary_stop_acknowledgement_deadline = None
    try:
      _settle_main_controller_auxiliary_stop_request_locked(
        request_id,
        terminal_type == "completed" and not cleanup_errors,
      )
    except Exception as exc:
      cleanup_errors.append(
        "main-controller auxiliary stop settlement failed: "
        f"{exc}"
      )
  if cleanup_errors:
    terminal_type = "failed"
    cleanup_message = "; ".join(cleanup_errors)
    terminal_value = (
      f"{terminal_value}; {cleanup_message}"
      if terminal_value
      else cleanup_message
    )
  auxiliary_serial_event_queue.put(
    (terminal_type, request_id, terminal_value)
  )


def _auxiliary_stop_not_required():
  # A live or retained handle remains stop-relevant even if persisted
  # configuration is absent or damaged. The configuration fallback preserves
  # a required-stop failure when a configured controller is unavailable.
  if RUN.get('ser2') is not None:
    return False
  if RUN['offlineMode']:
    return True
  configured_port = CAL.get('com2Port')
  configured_board = CAL.get('auxiliaryBoard')
  return (
    configured_port is None
    or configured_port == ""
    or configured_port == "None"
    or configured_board is None
    or configured_board == ""
    or configured_board == AUXILIARY_BOARD_NONE
  )


def _auxiliary_stop_shutdown_pending():
  with auxiliary_stop_state_lock:
    return (
      auxiliary_stop_requested.is_set()
      or auxiliary_stop_pending_request_id is not None
      or auxiliary_stop_active_request_id is not None
      or main_controller_auxiliary_stop_request_id is not None
    )


def _serial_shutdown_ready_for_close():
  if not serial_lock.locked() or not auxiliary_serial_lock.locked():
    raise RuntimeError(
      "serial shutdown readiness requires both transport reservations"
    )
  if (
    main_controller_stop_pending_event is not None
    or not main_controller_stop_event_queue.empty()
  ):
    return False
  with auxiliary_stop_state_lock:
    stop_pending = (
      auxiliary_stop_requested.is_set()
      or auxiliary_stop_pending_request_id is not None
      or auxiliary_stop_active_request_id is not None
      or main_controller_auxiliary_stop_request_id is not None
    )
    return not stop_pending and serial_activity_registry.idle()


def _settle_main_controller_auxiliary_stop_request_locked(
  request_id,
  acknowledged,
):
  global auxiliary_stop_pending_request_id
  global main_controller_auxiliary_stop_request_id

  if (
    isinstance(request_id, bool)
    or not isinstance(request_id, int)
    or request_id <= 0
  ):
    raise MotionInputError(
      "main-controller auxiliary stop settlement ID is invalid"
    )
  if not isinstance(acknowledged, bool):
    raise MotionInputError(
      "main-controller auxiliary stop acknowledgement must be boolean"
    )
  if main_controller_auxiliary_stop_request_id != request_id:
    return False
  if acknowledged:
    if (
      auxiliary_stop_active_request_id is not None
      or auxiliary_stop_pending_request_id is not None
    ):
      raise RuntimeError(
        "main-controller auxiliary stop acknowledgement preceded "
        "request release"
      )
    main_controller_auxiliary_stop_request_id = None
    return True
  if (
    auxiliary_stop_active_request_id is not None
    and auxiliary_stop_active_request_id != request_id
  ):
    raise RuntimeError(
      "main-controller auxiliary stop retry conflicts with an active "
      "request"
    )
  if (
    auxiliary_stop_pending_request_id is not None
    and auxiliary_stop_pending_request_id != request_id
  ):
    raise RuntimeError(
      "main-controller auxiliary stop retry conflicts with a pending "
      "request"
    )
  auxiliary_stop_pending_request_id = request_id
  auxiliary_stop_requested.set()
  return True


def _settle_main_controller_auxiliary_stop_request(
  request_id,
  acknowledged,
):
  with auxiliary_stop_state_lock:
    return _settle_main_controller_auxiliary_stop_request_locked(
      request_id,
      acknowledged,
    )


def _try_dispatch_auxiliary_stop():
  global auxiliary_stop_acknowledgement_deadline
  global auxiliary_stop_active_request_id
  global main_controller_auxiliary_stop_request_id
  global auxiliary_stop_owner_result
  global auxiliary_stop_pending_request_id

  with auxiliary_stop_state_lock:
    request_id = auxiliary_stop_pending_request_id
    if (
      request_id is None
      or auxiliary_stop_active_request_id is not None
      or auxiliary_stop_acknowledgement_deadline is not None
    ):
      return False
    if _auxiliary_stop_not_required():
      auxiliary_stop_pending_request_id = None
      auxiliary_stop_requested.clear()
      if main_controller_auxiliary_stop_request_id == request_id:
        main_controller_auxiliary_stop_request_id = None
      auxiliary_serial_event_queue.put(
        ("completed", request_id, "AUXILIARY STOP NOT REQUIRED")
      )
      return False
    control_mode = serial_activity_registry.reserve_emergency_control("ser2")
    if control_mode is None:
      return False
    if (
      control_mode == SerialActivityRegistry.CONTROL_INJECT
      and not auxiliary_stop_owner_waiting
    ):
      serial_activity_registry.finish_control("ser2", control_mode)
      return False
    auxiliary_stop_pending_request_id = None
    auxiliary_stop_active_request_id = request_id
    auxiliary_stop_owner_result = None
    auxiliary_stop_owner_result_event.clear()
    auxiliary_stop_injected_event.clear()
    auxiliary_stop_acknowledgement_deadline = None
    auxiliary_stop_requested.clear()

  try:
    thread = threading.Thread(
      target=_run_auxiliary_stop_safe,
      args=(request_id, control_mode),
      daemon=True,
    )
    thread.start()
  except Exception as exc:
    failure = f"unable to start auxiliary stop worker: {exc}"
    try:
      serial_activity_registry.finish_control("ser2", control_mode)
    except Exception as cleanup_exc:
      failure = f"{failure}; control ownership cleanup failed: {cleanup_exc}"
    with auxiliary_stop_state_lock:
      if auxiliary_stop_active_request_id == request_id:
        auxiliary_stop_active_request_id = None
      auxiliary_stop_owner_result = None
      auxiliary_stop_owner_result_event.clear()
      auxiliary_stop_injected_event.clear()
      auxiliary_stop_acknowledgement_deadline = None
      try:
        _settle_main_controller_auxiliary_stop_request_locked(
          request_id,
          False,
        )
      except Exception as settlement_exc:
        failure = (
          f"{failure}; main-controller auxiliary stop retry failed: "
          f"{settlement_exc}"
        )
    auxiliary_serial_event_queue.put(("failed", request_id, failure))
  return True


def _request_auxiliary_stop(on_reserved=None):
  if on_reserved is not None and not callable(on_reserved):
    raise TypeError("auxiliary stop reservation callback must be callable")
  if _auxiliary_stop_not_required():
    return AUXILIARY_STOP_NOT_REQUIRED, None
  with auxiliary_stop_state_lock:
    request_id = _reserve_auxiliary_stop_request_locked(on_reserved)
    already_dispatched = (
      auxiliary_stop_active_request_id == request_id
    )
  if already_dispatched:
    return AUXILIARY_STOP_DISPATCHED, request_id

  if _try_dispatch_auxiliary_stop():
    return AUXILIARY_STOP_DISPATCHED, request_id
  with auxiliary_stop_state_lock:
    if auxiliary_stop_active_request_id == request_id:
      return AUXILIARY_STOP_DISPATCHED, request_id
    if auxiliary_stop_pending_request_id == request_id:
      return AUXILIARY_STOP_PENDING, request_id
  return AUXILIARY_STOP_NOT_REQUIRED, None


def start_send_serial_thread(
  command,
  *,
  exchange,
  live_jog=False,
  completion_callback=None,
  controller_recovery=False,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if completion_callback is not None and not callable(completion_callback):
    raise TypeError("completion_callback must be callable")
  if not isinstance(controller_recovery, bool):
    raise TypeError("controller_recovery must be boolean")
  if not callable(exchange):
    raise TypeError("serial exchange must be callable")
  if (
    controller_recovery
    and exchange is not _exchange_controller_correction
  ):
    raise TypeError(
      "controller recovery requires the position-correction exchange"
    )
  if write_started_event is not None and not all(
    callable(getattr(write_started_event, method, None))
    for method in ("set", "is_set")
  ):
    raise TypeError("write_started_event must satisfy the event contract")
  if write_cancellation_boundary is not None:
    if not isinstance(
      write_cancellation_boundary,
      SerialWriteCancellationBoundary,
    ):
      raise TypeError("write cancellation boundary is invalid")
    if write_started_event is None:
      raise TypeError(
        "write cancellation boundary requires a write-start event"
      )
  if application_closing.is_set():
    logger.warning("Serial command rejected during application shutdown")
    return False
  if controller_correction_requested.is_set() and not controller_recovery:
    logger.warning("Serial command rejected until controller correction completes")
    return False
  inherited_transport = _transfer_main_serial_reservation()
  if not inherited_transport and not serial_lock.acquire(blocking=False):
    logger.warning("Serial command already in progress; command rejected")
    return False
  try:
    activity_lease = serial_activity_registry.lease("ser")
  except SerialActivityRejected as exc:
    if inherited_transport:
      _restore_main_serial_reservation()
    else:
      serial_lock.release()
    logger.warning("Serial command rejected: %s", exc)
    return False
  except Exception:
    if inherited_transport:
      _restore_main_serial_reservation()
    else:
      serial_lock.release()
    raise
  serial_result_pending.set()
  if live_jog:
    live_jog_stop_requested.clear()
    live_serial_result_pending.set()

  try:
    thread = threading.Thread(
      target=run_send_serial_safe,
      args=(
        command,
        exchange,
        live_jog,
        completion_callback,
        activity_lease,
        write_started_event,
        write_cancellation_boundary,
      ),
      daemon=True,
    )
    thread.start()
  except Exception:
    serial_result_pending.clear()
    if live_jog:
      live_serial_result_pending.clear()
      live_jog_stop_requested.clear()
    if inherited_transport:
      _restore_main_serial_reservation()
    else:
      serial_lock.release()
    activity_lease.close()
    raise
  return True


def _try_dispatch_controller_correction():
  with controller_correction_state_lock:
    if not controller_correction_requested.is_set():
      return False
    if application_closing.is_set() or RUN['offlineMode']:
      return False
    serial_port = RUN.get('ser')
    if (
      serial_port is None
      or not getattr(serial_port, "is_open", False)
      or serial_transport_quarantined(serial_port)
    ):
      return False
    if serial_lock.locked() or motion_request_registry.active:
      return False
    binding = _current_main_controller_identity(serial_port)
    if binding is None or not isinstance(
      binding.json_client,
      JsonMainControllerClient,
    ):
      logger.error("Controller correction requires JSON ownership")
      return False
    request_lease = _acquire_motion_request(
      "Controller correction",
      allow_position_recovery=True,
      requires_kinematics=False,
    )
    if request_lease is None:
      return False
    try:
      started = start_send_serial_thread(
        "CP\n",
        completion_callback=lambda controller_position: _complete_controller_correction(
          request_lease,
          controller_position,
        ),
        controller_recovery=True,
        exchange=_exchange_controller_correction,
      )
    except Exception:
      _finish_motion_request(request_lease)
      logger.exception("Unable to start controller correction")
      return False
    if not started:
      _finish_motion_request(request_lease)
      return False
    return True


def _complete_controller_correction(request_lease, controller_position):
  if isinstance(controller_position, JointMotionExchangeResult):
    controller_position = controller_position.position
  if controller_position is not None and not isinstance(
    controller_position,
    PositionResponse,
  ):
    raise RuntimeError(
      "controller correction returned an invalid position result"
    )
  try:
    with controller_correction_state_lock:
      if (
        controller_position is not None
        and not controller_position_resynchronization_required.is_set()
      ):
        controller_correction_requested.clear()
      else:
        controller_correction_requested.set()
  finally:
    _finish_motion_request(request_lease)


def _request_controller_correction():
  if application_closing.is_set() or RUN['offlineMode']:
    return False
  _clear_deferred_joint_adjustments()
  with controller_correction_state_lock:
    controller_correction_requested.set()
  return _try_dispatch_controller_correction()


def run_send_serial_safe(
  command,
  exchange,
  live_jog=False,
  completion_callback=None,
  activity_lease=None,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  serial_event_queue.put(
    (
      "started",
      command,
      None,
      None,
      live_jog,
      completion_callback,
      activity_lease,
    )
  )
  try:
    response = exchange(
      command,
      write_started_event=write_started_event,
      write_cancellation_boundary=write_cancellation_boundary,
    )
    serial_event_queue.put(
      (
        "completed",
        command,
        response,
        None,
        live_jog,
        completion_callback,
        activity_lease,
      )
    )
  except Exception as exc:
    serial_event_queue.put(
      (
        "failed",
        command,
        None,
        str(exc),
        live_jog,
        completion_callback,
        activity_lease,
      )
    )


def _invalidate_joint_motion_state(reason):
  if not isinstance(reason, str) or not reason.strip():
    reason = "controller state became uncertain"
  else:
    reason = reason.strip()
  _require_controller_position_resynchronization()
  pending_discarded = joint_motion_dispatcher.invalidate(reason)
  deferred_discarded = deferred_joint_adjustments.pending
  _clear_deferred_joint_adjustments()
  if pending_discarded or deferred_discarded:
    logger.warning("Pending joint target discarded because controller state is unknown")


def _apply_serial_motion_response(response, command=None):
  if isinstance(response, PositionResponse):
    if position_response_is_physical_estop(response):
      return response
    applied_position = displayPosition(response.raw, parsed=response)
    if not isinstance(applied_position, PositionResponse):
      raise ProtocolResponseError("JSON position response could not be applied")
    return applied_position
  if not isinstance(response, JointMotionExchangeResult):
    raise ProtocolResponseError("JSON motion exchange returned an invalid result")
  source_opcode = _motion_command_source_opcode(command)
  motion_name = {
    "CP": None,
    "LC": "Live Cartesian",
    "LJ": "Live joint",
    "LT": "Live tool",
    "MJ": "Cartesian",
    "ML": "Linear",
    "MA": "Arc",
    "MC": "Circle",
    "MS": "Spline",
    "MV": "Vision",
    "RJ": "Joint",
    "JT": "Tool-frame",
  }.get(source_opcode)
  if source_opcode not in (
    "CP", "LC", "LJ", "LT", "MA", "MC", "MJ", "ML", "MS", "MV", "RJ", "JT",
  ):
    raise ProtocolResponseError(
      "typed JSON motion response has an unsupported source command"
    )
  operation_name = (
    "Controller position correction"
    if source_opcode == "CP"
    else f"{motion_name} motion"
  )
  if response.confirmed_position_unchanged:
    message = f"{operation_name} rejected: {response.error}"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
    return None

  position = response.position
  if position_response_is_physical_estop(position):
    return position
  applied_position = displayPosition(response.response, parsed=position)
  if applied_position is None or not isinstance(
    applied_position,
    PositionResponse,
  ):
    position_error = (
      "JSON controller position-correction position could not be applied"
      if source_opcode == "CP"
      else f"JSON {motion_name.lower()}-motion position could not be applied"
    )
    raise ProtocolResponseError(
      position_error
    )
  if response.error is not None:
    message = f"{operation_name} failed: {response.error}"
    logger.error(message)
    _set_application_status(message, "Alarm.TLabel")
  return applied_position


def _event_poll_callback(poll_name):
  if not isinstance(poll_name, str) or poll_name not in EVENT_POLL_CALLBACK_NAMES:
    logger.error("Unable to resolve unknown event poll: %r", poll_name)
    return None
  callback_name = EVENT_POLL_CALLBACK_NAMES[poll_name]
  callback = globals().get(callback_name)
  if not callable(callback):
    logger.error(
      "Unable to resolve event poll callback %s for %s",
      callback_name,
      poll_name,
    )
    return None
  return callback


def _schedule_event_poll(poll_name):
  if application_closing.is_set():
    with event_poll_retry_lock:
      event_poll_retry_pending.clear()
    return False
  callback = _event_poll_callback(poll_name)
  if callback is None:
    return False
  try:
    root.after(EVENT_POLL_INTERVAL_MS, callback)
  except (RuntimeError, tk.TclError):
    with event_poll_retry_lock:
      event_poll_retry_pending.add(poll_name)
    logger.exception(f"Unable to schedule {poll_name} event polling")
    return False
  with event_poll_retry_lock:
    event_poll_retry_pending.discard(poll_name)
  return True


def _retry_failed_event_polls(excluded_poll_name):
  if (
    not isinstance(excluded_poll_name, str)
    or excluded_poll_name not in EVENT_POLL_CALLBACK_NAMES
  ):
    logger.error(
      "Unable to retry event polls with invalid exclusion: %r",
      excluded_poll_name,
    )
    return False
  with event_poll_retry_lock:
    pending = tuple(event_poll_retry_pending)
  retried = False
  for poll_name in pending:
    if poll_name == excluded_poll_name:
      continue
    if _schedule_event_poll(poll_name):
      retried = True
  return retried


def _reschedule_event_poll(poll_name):
  _schedule_event_poll(poll_name)
  _retry_failed_event_polls(poll_name)


def _poll_serial_events():
  try:
    while True:
      try:
        event = serial_event_queue.get_nowait()
      except Empty:
        break
      if not isinstance(event, tuple) or len(event) != 7:
        raise RuntimeError("serial worker emitted an invalid event")
      (
        event_type,
        command,
        response,
        error,
        live_jog,
        completion_callback,
        activity_lease,
      ) = event
      if completion_callback is not None and not callable(completion_callback):
        raise RuntimeError("serial worker emitted an invalid completion callback")
      if activity_lease is not None and not callable(
        getattr(activity_lease, "close", None)
      ):
        raise RuntimeError("serial worker emitted an invalid activity lease")

      if event_type == "started":
        cmdSentEntryField.delete(0, 'end')
        cmdSentEntryField.insert(0, _motion_command_display_text(command))
        if live_jog:
          _set_application_status("LIVE JOG IN PROGRESS", "OK.TLabel")
        continue

      if event_type not in ("completed", "failed"):
        raise RuntimeError(f"serial worker emitted an unknown event: {event_type!r}")

      applied_position = None
      structured_response = None
      try:
        if event_type == "failed":
          message = f"Serial command failed: {error}"
          logger.error(message)
          _set_application_status(message, "Alarm.TLabel")
          _invalidate_joint_motion_state(message)
        else:
          if isinstance(response, JointMotionExchangeResult):
            structured_response = response
          applied_position = _apply_serial_motion_response(response, command)
          if applied_position is not None and not isinstance(
            applied_position,
            PositionResponse,
          ):
            raise RuntimeError(
              "serial response application returned an invalid position result"
            )
          if applied_position is not None and live_jog:
            RUN['VR_angles'] = [
              finite_number(CAL[f'J{axis}AngCur'], f"J{axis} angle")
              for axis in range(1, 7)
            ]
            setStepMonitorsVR()
            if (
              not applied_position.speed_violation
              and getattr(structured_response, "error", None) is None
            ):
              _set_application_status("SYSTEM READY", "OK.TLabel")
      except Exception as exc:
        message = f"Unable to apply serial worker result: {exc}"
        logger.exception(message)
        _invalidate_joint_motion_state(message)
      finally:
        if live_jog:
          RUN['liveJog'] = False
        serial_result_pending.clear()
        live_serial_result_pending.clear()
        live_jog_stop_requested.clear()
        try:
          if serial_lock.locked():
            serial_lock.release()
          else:
            logger.error("Serial result arrived without transport ownership")
        finally:
          if activity_lease is not None and activity_lease.close() is not True:
            logger.error("Serial result reused a released activity lease")

        if completion_callback is not None:
          try:
            callback_result = (
              structured_response
              if structured_response is not None
              and (
                structured_response.confirmed_position_unchanged
                or position_response_is_physical_estop(
                  structured_response.position
                )
                or applied_position is structured_response.position
              )
              else applied_position
            )
            completion_callback(callback_result)
          except Exception:
            logger.exception("Unable to apply a serial completion callback")
        if (
          applied_position is not None
          and applied_position.speed_violation
        ):
          if deferred_joint_adjustments.pending:
            logger.warning(
              "Deferred joint target discarded after a controller speed violation"
          )
          _clear_deferred_joint_adjustments()
          deferred_dispatch = DeferredJointDispatchOutcome.BLOCKED
        else:
          deferred_dispatch = _try_dispatch_deferred_joint_adjustments(
            allow_current_generation=True,
          )
        if (
          applied_position is not None
          and not applied_position.speed_violation
          and getattr(structured_response, "error", None) is None
          and _motion_command_source_opcode(command) not in ("Z7", "Z8", "Z9")
          and deferred_dispatch is DeferredJointDispatchOutcome.IDLE
          and not joint_motion_dispatcher.active
          and not motion_request_registry.active
          and not application_closing.is_set()
        ):
          _set_application_status("SYSTEM READY", "OK.TLabel")
  except Exception:
    logger.exception("Unable to apply a serial worker result on the Tk event thread")
  finally:
    try:
      try:
        _apply_main_controller_idle_stop_results()
      except Exception:
        logger.exception(
          "Unable to apply an idle main-controller event result"
        )
      try:
        _try_start_main_controller_idle_stop_reader()
      except Exception:
        logger.exception(
          "Unable to supervise idle main-controller events"
        )
    finally:
      _reschedule_event_poll("serial")


def _poll_manual_controller_events():
  try:
    with manual_controller_cleanup_lock:
      pending_cleanup = manual_controller_cleanup_pending
    if pending_cleanup is not None:
      pending_request = pending_cleanup.request
      if not _retry_manual_controller_cleanup():
        detail = (
          pending_cleanup.last_error
          or "cleanup retry failed without details"
        )
        _set_manual_controller_status(
          f"CONTROLLER I/O CLEANUP PENDING: {detail}",
          "Alarm.TLabel",
        )
        return
      settlement_action = pending_cleanup.settlement_action
      connection_trusted = _manual_controller_connection_trusted(
        pending_request
      )
      if (
        connection_trusted
        and settlement_action in ("dispatch", "dispatch-ready")
      ):
        deferred_dispatch = _try_dispatch_deferred_joint_adjustments(
          allow_current_generation=True,
        )
        if (
          settlement_action == "dispatch-ready"
          and deferred_dispatch is DeferredJointDispatchOutcome.IDLE
          and not joint_motion_dispatcher.active
          and not motion_request_registry.active
          and not application_closing.is_set()
        ):
          _set_manual_controller_status("SYSTEM READY", "OK.TLabel")

    while True:
      try:
        event = manual_controller_event_queue.get_nowait()
      except Empty:
        break
      request, _ = _manual_controller_operation()
      if not isinstance(event, ManualControllerResult):
        raise RuntimeError("manual controller worker emitted an invalid result")
      result = event
      if request.request_id != result.request_id:
        raise RuntimeError(
          "manual controller worker result ownership is invalid"
        )
      command_is_write = controller_modbus_command_is_write(
        request.command
      )
      if result.unpositioned_stop_observed and (
        RUN.get('estopActive') is not True
        or RUN.get('mainControllerStopPositionUnavailable') is not True
      ):
        raise RuntimeError("manual controller unpositioned-stop evidence is invalid")
      physical_estop_received = result.unpositioned_stop_observed
      terminal_classification = None

      if result.outcome in ("completed", "rejected"):
        terminal_classification = (
          classify_controller_modbus_terminal_response(
            request.command,
            result.value,
          )
        )
        if terminal_classification != result.outcome:
          raise RuntimeError(
            "manual controller terminal classification is invalid"
          )
      elif result.outcome == "indeterminate":
        if not command_is_write:
          raise RuntimeError(
            "manual controller read result cannot be indeterminate"
          )
        if not result.serial_write_started:
          raise RuntimeError(
            "manual controller write uncertainty lacks write admission"
          )
      else:
        if result.serial_write_started and command_is_write:
          raise RuntimeError(
            "manual controller write failure lost indeterminate state"
          )
        try:
          classify_controller_modbus_terminal_response(
            request.command,
            result.value,
          )
        except ProtocolResponseError:
          pass
        else:
          raise RuntimeError(
            "manual controller framed terminal was reported as failed"
          )

      application_error = None
      settlement_presentation = None
      try:
        if physical_estop_received:
          if not result.serial_write_started:
            feedback = (
              "Physical E-stop received before command transmission; "
              "command not sent"
            )
          elif (
            command_is_write
            and (
              result.outcome == "indeterminate"
              or terminal_classification == "indeterminate"
            )
          ):
            feedback = (
              "Physical E-stop received; external write outcome unknown "
              f"({result.value}); "
              "reconnect and verify external device state"
            )
          elif command_is_write and terminal_classification == "completed":
            feedback = (
              "Physical E-stop received after external write completion "
              f"({result.value}); "
              "reconnect before further commands"
            )
          elif command_is_write and terminal_classification == "rejected":
            feedback = (
              "Physical E-stop received; external write rejected "
              f"({result.value}); "
              "reconnect before further commands"
            )
          elif terminal_classification == "rejected":
            feedback = (
              "Physical E-stop received; controller request rejected: "
              f"{result.value}; reconnect before further commands"
            )
          elif terminal_classification == "completed":
            feedback = (
              "Physical E-stop received after controller response: "
              f"{result.value}; reconnect before further commands"
            )
          else:
            feedback = (
              "Physical E-stop received; controller response ownership "
              "closed"
            )
          status = (
            "PHYSICAL E-STOP RECEIVED; CONTROLLER RECONNECTION REQUIRED"
          )
          style = "Alarm.TLabel"
        elif result.outcome == "completed":
          feedback = result.value
          status = "CONTROLLER I/O COMPLETE"
          style = "OK.TLabel"
        elif result.outcome == "rejected":
          feedback = f"Controller request rejected: {result.value}"
          status = feedback
          style = "Alarm.TLabel"
        elif result.outcome == "indeterminate":
          feedback = (
            f"Controller write outcome unknown: {result.value}; "
            "reconnect and verify external device state"
          )
          status = (
            "CONTROLLER WRITE OUTCOME UNKNOWN; RECONNECTION REQUIRED"
          )
          style = "Alarm.TLabel"
        else:
          feedback = f"Manual controller command failed: {result.value}"
          status = feedback
          style = "Alarm.TLabel"
        settlement_presentation = ManualControllerPresentation(
          feedback,
          status,
          style,
        )
        _set_manual_controller_feedback(feedback)
        _set_manual_controller_status(status, style)
      except Exception as exc:
        application_error = exc

      connection_trusted = (
        RUN.get('ser') is request.serial_port
        and getattr(request.serial_port, "is_open", False)
        and not serial_transport_quarantined(request.serial_port)
      )
      if application_error is not None:
        detail = _manual_controller_error_detail(
          application_error,
          "result application failed without details",
        )
        message = f"Unable to apply manual controller result: {detail}"
        settlement_presentation = ManualControllerPresentation(
          message,
          message,
          "Alarm.TLabel",
        )
      elif (
        not connection_trusted
        and not physical_estop_received
        and result.outcome != "indeterminate"
      ):
        settlement_presentation = ManualControllerPresentation(
          (
            "Controller connection lost during result settlement "
            f"({result.value}); reconnect required"
          ),
          "CONTROLLER CONNECTION LOST; RECONNECTION REQUIRED",
          "Alarm.TLabel",
        )
      try:
        _set_manual_controller_feedback(
          settlement_presentation.feedback
        )
        _set_manual_controller_status(
          settlement_presentation.status,
          settlement_presentation.style,
        )
      except Exception:
        logger.exception(
          "Unable to render the final manual controller presentation"
        )
      close_required = (
        physical_estop_received
        or result.outcome == "indeterminate"
        or application_error is not None
        or not connection_trusted
      )
      if close_required:
        _invalidate_joint_motion_state(
          "manual controller exchange ended without a trusted connection"
        )
      cleanup_error = None
      try:
        settlement_action = "none"
        if not close_required:
          settlement_action = (
            "dispatch-ready"
            if result.outcome == "completed"
            else "dispatch"
          )
        _release_manual_controller_operation(
          close_required=close_required,
          close_context=(
            "manual controller physical E-stop response"
            if physical_estop_received
            else (
              "manual controller indeterminate external write"
              if result.outcome == "indeterminate"
              else "manual controller result settlement"
            )
          ),
          settlement_action=settlement_action,
          settlement_presentation=settlement_presentation,
        )
      except Exception as exc:
        cleanup_error = exc

      if cleanup_error is not None:
        deferred_dispatch = DeferredJointDispatchOutcome.BLOCKED
        detail = _manual_controller_error_detail(
          cleanup_error,
          "cleanup failed without details",
        )
        message = f"Controller I/O cleanup pending: {detail}"
        logger.error(
          message,
          exc_info=(
            type(cleanup_error),
            cleanup_error,
            cleanup_error.__traceback__,
          ),
        )
        _render_manual_controller_rejection(message)
      else:
        connection_trusted = (
          RUN.get('ser') is request.serial_port
          and getattr(request.serial_port, "is_open", False)
          and not serial_transport_quarantined(request.serial_port)
        )
        if not connection_trusted:
          deferred_dispatch = DeferredJointDispatchOutcome.BLOCKED
        else:
          deferred_dispatch = _try_dispatch_deferred_joint_adjustments(
            allow_current_generation=True,
          )

      if application_error is not None:
        detail = _manual_controller_error_detail(
          application_error,
          "result application failed without details",
        )
        message = f"Unable to apply manual controller result: {detail}"
        logger.error(
          message,
          exc_info=(
            type(application_error),
            application_error,
            application_error.__traceback__,
          ),
        )
        try:
          _render_manual_controller_rejection(message)
        except Exception:
          logger.exception(
            "Unable to render a manual controller application failure"
          )
      elif (
        cleanup_error is None
        and result.outcome == "completed"
        and not physical_estop_received
        and connection_trusted
        and deferred_dispatch is DeferredJointDispatchOutcome.IDLE
        and not joint_motion_dispatcher.active
        and not motion_request_registry.active
        and not application_closing.is_set()
      ):
        _set_manual_controller_status("SYSTEM READY", "OK.TLabel")
  except Exception as exc:
    logger.exception(
      "Unable to apply a manual controller result on the Tk event thread"
    )
    with manual_controller_state_lock:
      request = manual_controller_active_request
      activity_lease = manual_controller_activity_lease
    operation_active = request is not None or activity_lease is not None
    if operation_active:
      try:
        _invalidate_joint_motion_state(
          "manual controller worker result ownership became invalid"
        )
      except Exception:
        logger.exception(
          "Unable to invalidate motion after an invalid manual result"
        )
      try:
        released_request = _release_manual_controller_operation(
          close_required=True,
          close_context="invalid manual controller worker result",
        )
        if isinstance(released_request, ManualControllerRequest):
          request = released_request
      except Exception:
        logger.exception(
          "Unable to release invalid manual controller result ownership"
        )
    detail = _manual_controller_error_detail(
      exc,
      "manual controller result handling failed",
    )
    message = f"Manual controller command failed: {detail}"
    logger.error(message)
    try:
      _render_manual_controller_rejection(message)
    except Exception:
      logger.exception(
        "Unable to render an invalid manual controller result"
      )
  finally:
    _reschedule_event_poll("manual-controller")


def _poll_auxiliary_serial_events():
  try:
    while True:
      try:
        event = auxiliary_serial_event_queue.get_nowait()
      except Empty:
        break
      if (
        not isinstance(event, tuple)
        or len(event) != 3
        or event[0] not in ("started", "completed", "failed")
        or isinstance(event[1], bool)
        or not isinstance(event[1], int)
        or event[1] <= 0
        or not isinstance(event[2], str)
        or not event[2]
      ):
        raise RuntimeError("auxiliary serial worker emitted an invalid event")

      event_type, request_id, value = event
      release_stop_barrier = False
      with program_stop_state_lock:
        current_request_id = RUN.get('programStopRequestId')
        if event_type == "started":
          if current_request_id == request_id:
            _set_program_stop_status("pending")
        elif event_type == "completed":
          if current_request_id == request_id:
            RUN['programStopRequestId'] = None
            _set_program_stop_status("completed")
            release_stop_barrier = True
        else:
          message = f"Auxiliary stop failed: {value}"
          logger.error(message)
          if current_request_id == request_id:
            if RUN.get('estopActive'):
              _set_program_stop_status("pending")
            else:
              RUN['programStopRequestId'] = None
              _set_program_stop_status("failed")
              release_stop_barrier = True
      if release_stop_barrier:
        _clear_manual_auxiliary_stop_barrier_if_settled()
      if event_type == "started":
        cmdSentEntryField.delete(0, 'end')
        cmdSentEntryField.insert(0, value)
      elif event_type == "completed":
        cmdRecEntryField.delete(0, 'end')
        cmdRecEntryField.insert(0, value)
  except Exception:
    logger.exception("Unable to apply an auxiliary serial result on the Tk event thread")
  finally:
    _reschedule_event_poll("auxiliary-serial")
    try:
      _apply_main_controller_stop_events()
    except Exception:
      logger.exception(
        "Unable to apply a main-controller stop on the Tk event thread"
      )
    try:
      _apply_program_stop_status_events()
    except Exception:
      logger.exception(
        "Unable to apply a program-stop status on the Tk event thread"
      )
    try:
      _try_dispatch_controller_correction()
    except Exception:
      logger.exception(
        "Unable to dispatch controller correction on the Tk event thread"
      )
    try:
      _try_dispatch_auxiliary_stop()
    except Exception:
      logger.exception(
        "Unable to dispatch auxiliary stop on the Tk event thread"
      )
    try:
      _ensure_startup_auxiliary_cleanup()
    except Exception:
      logger.exception(
        "Unable to supervise auxiliary startup cleanup on the Tk event thread"
      )


def _poll_manual_auxiliary_events():
  global manual_auxiliary_active_request

  try:
    while True:
      try:
        result = manual_auxiliary_event_queue.get_nowait()
      except Empty:
        break
      if not isinstance(result, ManualAuxiliaryResult):
        raise RuntimeError("manual auxiliary worker emitted an invalid result")
      with manual_auxiliary_state_lock:
        request = manual_auxiliary_active_request
        if (
          not isinstance(request, ManualAuxiliaryRequest)
          or request.request_id != result.request_id
        ):
          raise RuntimeError(
            "manual auxiliary worker result ownership is invalid"
          )
        manual_auxiliary_active_request = None

      if result.outcome == "completed":
        cmdRecEntryField.delete(0, 'end')
        cmdRecEntryField.insert(0, result.value)
        CAL[request.calibration_key] = request.calibration_value
        if _retain_calibration_persistence_retry():
          _set_manual_auxiliary_status(
            "AUXILIARY COMMAND COMPLETE",
            "OK.TLabel",
          )
        else:
          _set_manual_auxiliary_status(
            "AUXILIARY COMMAND COMPLETE; SETTINGS SAVE DEFERRED",
            "Warn.TLabel",
          )
      else:
        with manual_auxiliary_state_lock:
          discarded = len(manual_auxiliary_request_queue)
          manual_auxiliary_request_queue.clear()
        message = f"Manual auxiliary command failed: {result.value}"
        if discarded:
          message = (
            f"{message}; {discarded} queued command(s) discarded"
          )
        logger.error(message)
        _set_manual_auxiliary_feedback(message)
        _set_manual_auxiliary_status(message, "Alarm.TLabel")
  except Exception as exc:
    logger.exception(
      "Unable to apply a manual auxiliary result on the Tk event thread"
    )
    with manual_auxiliary_state_lock:
      manual_auxiliary_active_request = None
      discarded = len(manual_auxiliary_request_queue)
      manual_auxiliary_request_queue.clear()
    _close_serial_port('ser2', "invalid manual auxiliary worker result")
    detail = _manual_auxiliary_error_detail(
      exc,
      "manual auxiliary result handling failed",
    )
    message = f"Manual auxiliary command failed: {detail}"
    if discarded:
      message = f"{message}; {discarded} queued command(s) discarded"
    logger.error(message)
    _set_manual_auxiliary_feedback(message)
    _set_manual_auxiliary_status(
      message,
      "Alarm.TLabel",
    )
  finally:
    _reschedule_event_poll("manual-auxiliary")
    if application_closing.is_set():
      try:
        with manual_auxiliary_state_lock:
          discarded = len(manual_auxiliary_request_queue)
          manual_auxiliary_request_queue.clear()
        if discarded:
          logger.warning(
            "Discarded queued manual auxiliary commands during shutdown"
          )
      except Exception:
        logger.exception(
          "Unable to discard manual auxiliary requests during shutdown"
        )
    else:
      try:
        if _manual_auxiliary_program_active():
          _reject_queued_manual_auxiliary_requests(
            "AUXILIARY COMMANDS REJECTED WHILE PROGRAM IS RUNNING"
          )
        elif (
          serial_activity_registry.active("ser2")
          or auxiliary_serial_lock.locked()
        ):
          _reject_queued_manual_auxiliary_requests(
            "AUXILIARY COMMANDS REJECTED WHILE TRANSPORT IS BUSY"
          )
        else:
          _try_dispatch_manual_auxiliary_request()
      except Exception:
        logger.exception(
          "Unable to dispatch a queued manual auxiliary command"
        )


def _poll_gcode_storage_events():
  try:
    _ensure_gcode_storage_cleanup()
    while True:
      try:
        result = gcode_storage_event_queue.get_nowait()
      except Empty:
        break
      if isinstance(result, GCodeStorageCleanupResult):
        _apply_gcode_storage_cleanup_result(result)
      else:
        _apply_gcode_storage_result(result)
  except Exception:
    logger.exception(
      "Unable to apply a G-code storage result on the Tk event thread"
    )
  finally:
    _reschedule_event_poll("gcode-storage")


def _poll_xbox_auxiliary_events():
  try:
    while True:
      try:
        event = xbox_auxiliary_event_queue.get_nowait()
      except Empty:
        break
      if (
        not isinstance(event, tuple)
        or len(event) != 5
        or event[0] not in ("completed", "rejected", "failed")
        or isinstance(event[1], bool)
        or not isinstance(event[1], int)
        or event[1] <= 0
        or event[2] not in XBOX_AUXILIARY_PENDING_KEYS
        or not isinstance(event[3], bool)
        or not isinstance(event[4], str)
        or not event[4].strip()
      ):
        raise RuntimeError("Xbox auxiliary worker emitted an invalid event")

      event_type, request_id, state_name, target_state, value = event
      pending_name = XBOX_AUXILIARY_PENDING_KEYS[state_name]
      if RUN.get(pending_name) != request_id:
        logger.warning(
          "Ignoring a stale Xbox auxiliary result for %s",
          state_name,
        )
        continue
      current_state = RUN.get(state_name)
      if not isinstance(current_state, bool) or target_state is current_state:
        raise RuntimeError("Xbox auxiliary result conflicts with confirmed state")
      value = value.strip()
      RUN[pending_name] = None
      if event_type == "completed":
        RUN[state_name] = target_state
        continue

      if event_type == "failed":
        RUN[state_name] = None
        message = f"Xbox auxiliary command failed: {value}"
        style = "Alarm.TLabel"
        logger.error(message)
      else:
        message = f"Xbox auxiliary command rejected: {value}"
        style = "Warn.TLabel"
        logger.warning(message)
      _set_application_status(message, style)
  except Exception:
    logger.exception("Unable to apply an Xbox auxiliary result on the Tk event thread")
  finally:
    _reschedule_event_poll("xbox-auxiliary")


def _poll_virtual_motion_events():
  try:
    while True:
      try:
        event = virtual_motion_event_queue.get_nowait()
      except Empty:
        break
      if not isinstance(event, tuple) or len(event) != 2:
        raise RuntimeError("virtual motion worker emitted an invalid event")
      event_type, value = event
      if event_type == "error" and isinstance(value, str):
        ErrorHandler(value)
      elif (
        event_type == "program-completion"
        and isinstance(value, tuple)
        and len(value) == 4
        and callable(value[0])
        and isinstance(value[1], MotionRequestLease)
        and isinstance(value[2], bool)
        and (value[3] is None or callable(value[3]))
      ):
        (
          completion_callback,
          request_lease,
          succeeded,
          settlement_callback,
        ) = value
        _finish_settled_motion_request(
          completion_callback,
          request_lease,
          succeeded,
          settlement_callback,
        )
      elif (
        event_type == "offline-live-terminal"
        and isinstance(value, VirtualMotionOperation)
      ):
        _settle_offline_live_jog(value)
      elif event_type == "motion-released" and value is None:
        _try_dispatch_controller_correction()
        _try_dispatch_deferred_joint_adjustments(
          allow_current_generation=True,
        )
      else:
        raise RuntimeError("virtual motion worker emitted an invalid event")
  except Exception:
    logger.exception("Unable to apply a virtual-motion result on the Tk event thread")
  finally:
    _reschedule_event_poll("virtual-motion")


def _current_joint_positions():
  return _controller_joint_positions_from_values(CAL)


def _controller_joint_positions_from_values(values):
  return tuple(
    finite_number(values[key], label)
    for key, label in (
      ('J1AngCur', 'J1 current angle'),
      ('J2AngCur', 'J2 current angle'),
      ('J3AngCur', 'J3 current angle'),
      ('J4AngCur', 'J4 current angle'),
      ('J5AngCur', 'J5 current angle'),
      ('J6AngCur', 'J6 current angle'),
      ('J7PosCur', 'J7 current position'),
      ('J8PosCur', 'J8 current position'),
      ('J9PosCur', 'J9 current position'),
    )
  )


def _controller_joint_calibration_from_values(values):
  negative_limits = tuple(
    finite_number(values[f'J{axis}NegLim'], f'J{axis} negative limit')
    for axis in range(1, 7)
  ) + (0.0, 0.0, 0.0)
  positive_limits = tuple(
    finite_number(values[f'J{axis}PosLim'], f'J{axis} positive limit')
    for axis in range(1, 7)
  ) + tuple(
    finite_number(values[key], key)
    for key in ('J7PosLim', 'J8length', 'J9length')
  )
  steps_per_unit = [
    finite_number(values[f'J{axis}StepDeg'], f'J{axis} steps per degree')
    for axis in range(1, 7)
  ]
  for axis in range(7, 10):
    rotation = finite_number(values[f'J{axis}rotation'], f'J{axis} rotation')
    steps = finite_number(values[f'J{axis}steps'], f'J{axis} steps')
    if rotation <= 0:
      raise MotionInputError(f"J{axis} rotation must be positive")
    steps_per_unit.append(
      controller_ratio(steps, rotation, f"J{axis} steps per unit")
    )
  return ControllerJointCalibration(
    negative_limits=negative_limits,
    positive_limits=positive_limits,
    steps_per_unit=tuple(steps_per_unit),
  )


def _validate_controller_pose(values):
  calibration = _controller_joint_calibration_from_values(values)
  return calibration.validate_positions(
    _controller_joint_positions_from_values(values)
  )


def _current_controller_joint_calibration():
  return _controller_joint_calibration_from_values(CAL)


def _current_joint_motion_profile():
  checkSpeedVals()
  speed_type = speedOption.get()
  if speed_type == "mm per Sec":
    speedOption.set("Percent")
    speedEntryField.delete(0, 'end')
    speedEntryField.insert(0, "50")
    speed_prefix = "Sp"
  elif speed_type == "Seconds":
    speed_prefix = "Ss"
  elif speed_type == "Percent":
    speed_prefix = "Sp"
  else:
    raise MotionInputError(f"Unsupported joint speed type: {speed_type!r}")

  wrist_config = RUN.get('WC')
  if wrist_config not in ("N", "F"):
    wrist_config = (
      "F" if finite_number(CAL['J5AngCur'], "J5 angle") > 0 else "N"
    )
    RUN['WC'] = wrist_config

  loop_mode = ''.join(
    str(CAL[f'J{axis}OpenLoopVal'].get())
    for axis in range(1, 7)
  )
  return MotionProfile(
    speed_prefix=speed_prefix,
    speed=speedEntryField.get(),
    acceleration=ACCspeedField.get(),
    deceleration=DECspeedField.get(),
    ramp=ACCrampField.get(),
    wrist_config=wrist_config,
    loop_mode=loop_mode,
  )


def _canonical_json_message_text(message):
  frame = encode_message(message)
  if (
    type(frame) is not bytes
    or not frame.endswith(b"\n")
    or frame.endswith(b"\r\n")
  ):
    raise ProtocolResponseError(
      "canonical JSON message encoding returned an invalid frame"
    )
  try:
    return frame[:-1].decode("ascii")
  except UnicodeDecodeError as exc:
    raise ProtocolResponseError(
      "canonical JSON message encoding returned non-ASCII data"
    ) from exc


def _json_fixed_point_text(values, field_name):
  if type(values) is not tuple:
    raise ProtocolResponseError(f"{field_name} must be an immutable tuple")
  encoded = []
  for value in values:
    if isinstance(value, bool) or not isinstance(value, int):
      raise ProtocolResponseError(f"{field_name} contains an invalid value")
    negative = value < 0
    magnitude = -value if negative else value
    whole, fraction = divmod(magnitude, 1000)
    text = str(whole)
    if fraction:
      text += "." + f"{fraction:03d}".rstrip("0")
    if negative:
      text = "-" + text
    encoded.append(text)
  return tuple(encoded)


def _json_joint_position_response(
  response,
  position,
  *,
  speed_violation=False,
  debug="",
  flag="",
):
  if type(position) is not JsonMainPositionResult:
    raise ProtocolResponseError("JSON joint position result is invalid")
  if type(speed_violation) is not bool:
    raise ProtocolResponseError("JSON speed-limited state is invalid")
  if (
    not isinstance(debug, str)
    or not debug.isascii()
    or "\r" in debug
    or "\n" in debug
  ):
    raise ProtocolResponseError("JSON controller debug value is invalid")
  if (
    not isinstance(flag, str)
    or not flag.isascii()
    or "\r" in flag
    or "\n" in flag
  ):
    raise ProtocolResponseError("JSON controller position flag is invalid")
  joint_text = _json_fixed_point_text(
    position.robot_joints_millidegrees,
    "JSON robot joint positions",
  )
  external_text = _json_fixed_point_text(
    position.external_axes_milliunits,
    "JSON external-axis positions",
  )
  cartesian_text = (
    _json_fixed_point_text(
      position.cartesian_micrometers,
      "JSON Cartesian translation",
    )
    + _json_fixed_point_text(
      position.orientation_millidegrees,
      "JSON Cartesian orientation",
    )
  )
  return PositionResponse(
    raw=response,
    joint_text=joint_text,
    joints=position.robot_joints_degrees,
    cartesian_text=cartesian_text,
    cartesian=(
      position.cartesian_translation_millimeters
      + position.orientation_degrees
    ),
    external_text=external_text,
    external=position.external_axes,
    speed_violation=speed_violation,
    debug=debug,
    flag=flag,
  )


def _json_joint_motion_target_parameters(
  target,
  telemetry_enabled,
  trace_configuration_fingerprint=None,
):
  if type(telemetry_enabled) is not bool:
    raise MotionInputError("JSON joint telemetry selection is invalid")
  if type(target) is not JointMotionCommand:
    raise MotionInputError("JSON joint target is invalid")
  timing = target.timing
  if type(timing) is not CommandTiming or not isinstance(timing.mode, str):
    raise MotionInputError("JSON joint motion timing is invalid")
  if (
    type(target.robot_joints_degrees) is not tuple
    or type(target.external_axes_units) is not tuple
    or type(target.loop_modes) is not tuple
    or len(target.robot_joints_degrees) != 6
    or len(target.external_axes_units) != 3
    or len(target.loop_modes) != 6
  ):
    raise MotionInputError("JSON joint target axis count is invalid")
  speed_mode = {
    "p": "percent",
    "s": "seconds",
    "m": "millimeters_per_second",
  }.get(timing.mode)
  wrist_configuration = {
    "A": "automatic",
    "N": "near",
    "F": "far",
  }.get(
    target.wrist_configuration
    if isinstance(target.wrist_configuration, str)
    else None
  )
  if speed_mode is None or wrist_configuration is None:
    raise MotionInputError("JSON joint motion profile is unsupported")
  if any(type(value) is not bool for value in target.loop_modes):
    raise MotionInputError("JSON joint loop modes are invalid")
  if trace_configuration_fingerprint is not None:
    try:
      validate_main_configuration_fingerprint(
        trace_configuration_fingerprint,
        "JSON joint trace configuration fingerprint",
      )
    except JsonCommandSchemaError as exc:
      raise MotionInputError(str(exc)) from exc
  if trace_configuration_fingerprint is not None and telemetry_enabled:
    raise MotionInputError(
      "JSON traced joint motion cannot enable live telemetry"
    )
  return {
    "robot_joints_degrees": target.robot_joints_degrees,
    "external_axes_units": target.external_axes_units,
    "speed_mode": speed_mode,
    "speed_value": timing.speed,
    "acceleration_percent": timing.acceleration,
    "deceleration_percent": timing.deceleration,
    "ramp_percent": timing.ramp,
    "wrist_configuration": wrist_configuration,
    "loop_modes": target.loop_modes,
    "telemetry_enabled": telemetry_enabled,
    "trace_configuration_fingerprint": trace_configuration_fingerprint,
  }


def _json_joint_motion_parameters(
  command,
  telemetry_enabled,
  trace_configuration_fingerprint=None,
):
  snapshot = joint_motion_dispatcher.current_exchange_snapshot(command)
  if snapshot is None:
    raise MotionQueueFault(
      "JSON joint motion requires an active exchange snapshot"
    )
  profile = snapshot.profile
  if type(profile) is not MotionProfile:
    raise MotionInputError("JSON joint dispatcher profile is invalid")
  timing_mode = {
    "Sp": "p",
    "Ss": "s",
  }.get(profile.speed_prefix)
  if timing_mode is None:
    raise MotionInputError("JSON joint dispatcher speed mode is unsupported")
  return _json_joint_motion_target_parameters(
    JointMotionCommand(
      tuple(snapshot.target_positions[:6]),
      tuple(snapshot.target_positions[6:]),
      CommandTiming(
        timing_mode,
        profile.speed,
        profile.acceleration,
        profile.deceleration,
        profile.ramp,
      ),
      profile.wrist_config,
      tuple(value == "1" for value in profile.loop_mode),
    ),
    telemetry_enabled,
    trace_configuration_fingerprint,
  )


def _json_cartesian_motion_parameters(command, telemetry_enabled=False):
  if type(telemetry_enabled) is not bool:
    raise MotionInputError("JSON Cartesian telemetry selection is invalid")
  target = parse_cartesian_motion_command(command)
  if type(target) is not CartesianMotionCommand:
    raise MotionInputError("Cartesian command parser returned an invalid target")
  speed_mode = {
    "p": "percent",
    "s": "seconds",
    "m": "millimeters_per_second",
  }.get(target.timing.mode)
  wrist_configuration = {
    "A": "automatic",
    "N": "near",
    "F": "far",
  }.get(target.wrist_configuration)
  if speed_mode is None or wrist_configuration is None:
    raise MotionInputError("JSON Cartesian motion profile is unsupported")
  return {
    "translation_millimeters": target.translation_millimeters,
    "orientation_degrees": target.orientation_degrees,
    "external_axes_units": target.external_axes_units,
    "speed_mode": speed_mode,
    "speed_value": target.timing.speed,
    "acceleration_percent": target.timing.acceleration,
    "deceleration_percent": target.timing.deceleration,
    "ramp_percent": target.timing.ramp,
    "wrist_configuration": wrist_configuration,
    "loop_modes": target.loop_modes,
    "telemetry_enabled": telemetry_enabled,
  }


def _json_tool_jog_parameters(command):
  target = parse_tool_jog_command(command)
  if type(target) is not ToolJogCommand:
    raise MotionInputError("tool-frame command parser returned an invalid target")
  speed_mode = {
    "p": "percent",
    "s": "seconds",
  }.get(target.timing.mode)
  wrist_configuration = {
    "A": "automatic",
    "N": "near",
    "F": "far",
  }.get(target.wrist_configuration)
  if speed_mode is None or wrist_configuration is None:
    raise MotionInputError("JSON tool-frame jog profile is unsupported")
  return {
    "axis": target.axis,
    "direction": target.direction,
    "distance": target.distance,
    "speed_mode": speed_mode,
    "speed_value": target.timing.speed,
    "acceleration_percent": target.timing.acceleration,
    "deceleration_percent": target.timing.deceleration,
    "ramp_percent": target.timing.ramp,
    "wrist_configuration": wrist_configuration,
    "loop_modes": target.loop_modes,
  }


def _json_motion_write_admission(
  write_started_event,
  write_cancellation_boundary,
):
  if write_started_event is None and write_cancellation_boundary is None:
    return None

  def admit():
    if write_cancellation_boundary is None:
      if write_started_event is not None:
        write_started_event.set()
      return True
    with write_cancellation_boundary.write_reservation():
      if write_cancellation_boundary.is_set():
        return False
      # Admission is the uncertainty boundary: a later write failure can
      # represent a partial controller frame and therefore requires recovery.
      if write_started_event is not None:
        write_started_event.set()
      return True

  return admit


def _json_joint_motion_failure_detail(terminal, motion_name="joint"):
  if (
    not isinstance(motion_name, str)
    or not motion_name
    or motion_name != motion_name.strip()
  ):
    raise ProtocolResponseError("JSON motion name is invalid")
  failure = terminal.failure
  if failure is None:
    return (
      f"controller returned a non-completed JSON {motion_name}-motion response "
      f"without an error: {terminal.response.status}"
    )
  message = " ".join(failure.message.split())
  return (
    f"controller {terminal.response.status} JSON {motion_name} motion: "
    f"{failure.code}: {message}"
  )


def _json_joint_motion_terminal_result(
  terminal,
  stop_context,
  stop_already_published,
  motion_name="joint",
  positionless_rejection_codes=(
    "joint_limit_violation",
    "position_not_representable",
  ),
):
  raw = _canonical_json_message_text(terminal.response)
  if terminal.response.status == "completed":
    result = terminal.parsed_result
    position = _json_joint_position_response(
      raw,
      result.position,
      speed_violation=result.speed_limited,
      debug=result.controller_debug,
      flag=(
        CONTROLLER_ESTOP_EVENT_FLAG
        if stop_already_published
        else ""
      ),
    )
    if stop_already_published:
      _publish_main_controller_stop_position_upgrade(
        stop_context,
        position,
      )
    return JointMotionExchangeResult(
      response=raw,
      position=position,
      error=(
        "controller reported a JSON emergency stop alongside completed motion"
        if stop_already_published
        else None
      ),
    )

  failure = terminal.failure
  detail = _json_joint_motion_failure_detail(terminal, motion_name)
  position_result = None
  if failure is not None and "position" in failure.details:
    position_result = parse_main_motion_position_result(
      failure.details["position"]
    )
  if position_result is None:
    if (
      not stop_already_published
      and failure is not None
      and failure.code in positionless_rejection_codes
    ):
      return JointMotionExchangeResult(
        response=raw,
        position=None,
        error=detail,
        confirmed_position_unchanged=True,
      )
    raise ProtocolResponseError(detail)

  flag = ""
  if stop_already_published or failure.code == "emergency_stop":
    flag = CONTROLLER_ESTOP_EVENT_FLAG
  elif failure.code == "encoder_collision":
    flag = "EC" + "".join(
      "1" if active else "0"
      for active in failure.details["axes"]
    )
  position = _json_joint_position_response(
    raw,
    position_result,
    flag=flag,
  )
  if stop_already_published:
    _publish_main_controller_stop_position_upgrade(
      stop_context,
      position,
    )
  elif failure.code == "emergency_stop":
    _publish_main_controller_stop(stop_context, position)
  return JointMotionExchangeResult(
    response=raw,
    position=position,
    error=detail,
  )


def _json_controller_correction_terminal_result(
  terminal,
  stop_context,
  stop_already_published,
):
  raw = _canonical_json_message_text(terminal.response)
  if terminal.response.status == "completed":
    result = terminal.parsed_result
    if not isinstance(result, JsonMainPositionResult):
      raise ProtocolResponseError(
        "JSON position-correction result has an invalid type"
      )
    position_flag = result.motion_fault
    if stop_already_published and not position_flag:
      position_flag = CONTROLLER_ESTOP_EVENT_FLAG
    position = _json_joint_position_response(
      raw,
      result,
      speed_violation=result.speed_limited,
      debug=result.controller_debug,
      flag=position_flag,
    )
    reported_stop = (
      stop_already_published
      or position_response_is_physical_estop(position)
    )
    if stop_already_published:
      stop_position = position
      if not position_response_is_physical_estop(stop_position):
        stop_position = _json_joint_position_response(
          raw,
          result,
          speed_violation=result.speed_limited,
          debug=result.controller_debug,
          flag=CONTROLLER_ESTOP_EVENT_FLAG,
        )
      _publish_main_controller_stop_position_upgrade(
        stop_context,
        stop_position,
      )
    return JointMotionExchangeResult(
      response=raw,
      position=position,
      error=(
        "controller reported a JSON emergency stop during position correction"
        if reported_stop
        else None
      ),
    )

  failure = terminal.failure
  if failure is None:
    raise ProtocolResponseError(
      "controller returned a non-completed JSON position correction "
      f"without an error: {terminal.response.status}"
    )
  detail = (
    f"controller {terminal.response.status} JSON position correction: "
    f"{failure.code}: {' '.join(failure.message.split())}"
  )
  if (
    terminal.response.status != "failed"
    or failure.code != "encoder_state_unavailable"
  ):
    raise ProtocolResponseError(detail)
  position_result = parse_main_motion_position_result(
    failure.details["position"]
  )
  axes = failure.details["axes"]
  flag = "EC" + "".join("1" if active else "0" for active in axes)
  position = _json_joint_position_response(raw, position_result, flag=flag)
  if stop_already_published:
    stop_position = _json_joint_position_response(
      raw,
      position_result,
      flag=CONTROLLER_ESTOP_EVENT_FLAG,
    )
    _publish_main_controller_stop_position_upgrade(
      stop_context,
      stop_position,
    )
  return JointMotionExchangeResult(
    response=raw,
    position=position,
    error=detail,
  )


def _validate_json_joint_motion_event(delivery, motion_name="joint"):
  if type(delivery) is not JsonEventDelivery:
    raise ProtocolResponseError(
      f"JSON {motion_name}-motion event delivery is invalid"
    )
  event = delivery.event
  if (
    type(event) is not Event
    or event.event != "emergency_stop"
    or len(event.data) != 1
    or frozenset(event.data) != frozenset(("asserted",))
    or event.data.get("asserted") is not True
  ):
    raise ProtocolResponseError(
      f"unexpected JSON {motion_name}-motion event: {event.event}"
    )
  return True


def _json_live_jog_contract(command):
  command = _canonicalize_main_serial_command(command)
  opcode = command[:2]
  command_name, motion_name = {
    "LC": ("live_cart_jog", "live Cartesian"),
    "LJ": ("live_joint_jog", "live joint"),
    "LT": ("live_tool_jog", "live tool"),
  }.get(opcode, (None, None))
  if command_name is None:
    raise MotionInputError("JSON live jog requires an LC, LJ, or LT command")
  timing = parse_command_timing(command)
  vector_match = re.match(r"^(?:LC|LJ|LT)V([0-9]+)S", command)
  loop_match = re.search(r"Lm([01]{6})\n\Z", command)
  if timing is None or timing.mode != "p" or vector_match is None:
    raise MotionInputError("JSON live-jog command profile is invalid")
  if loop_match is None:
    raise MotionInputError("JSON live-jog loop modes are invalid")
  vector = int(vector_match.group(1))
  axis_group, direction_bit = divmod(vector, 10)
  if opcode == "LJ":
    axis = axis_group
  else:
    axis = {
      1: "x",
      2: "y",
      3: "z",
      4: "rz",
      5: "ry",
      6: "rx",
    }.get(axis_group)
  if axis is None:
    raise MotionInputError("JSON live-jog axis is invalid")
  # LT bit 0 creates a positive frame offset whose IK result is negative TCP travel.
  direction = "positive" if direction_bit == 1 else "negative"
  wrist_configuration = {
    "A": "automatic",
    "N": "near",
    "F": "far",
  }.get(parse_motion_wrist_config(command))
  if wrist_configuration is None:
    raise MotionInputError("JSON live-jog wrist configuration is invalid")
  return command_name, motion_name, {
    "axis": axis,
    "direction": direction,
    "speed_mode": "percent",
    "speed_value": timing.speed,
    "acceleration_percent": timing.acceleration,
    "deceleration_percent": timing.deceleration,
    "ramp_percent": timing.ramp,
    "wrist_configuration": wrist_configuration,
    "loop_modes": tuple(value == "1" for value in loop_match.group(1)),
    "telemetry_enabled": False,
    "lease_milliseconds": JSON_LIVE_MOTION_LEASE_MAXIMUM_MILLISECONDS,
  }


def _publish_json_live_jog_stop(stop_context, command_name, source):
  return _publish_main_controller_unpositioned_stop(
    stop_context,
    JsonMainControllerPhysicalStop(command_name, source),
  )


def _exchange_json_live_jog(
  command,
  binding,
  stop_context,
  write_started_event,
):
  command_name, motion_name, parameters = _json_live_jog_contract(command)
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError("persistent JSON live jog lacks a valid client")
  request = getattr(client, f"request_{command_name}")
  response_timeout = JSON_LIVE_MOTION_RESPONSE_TIMEOUT_SECONDS
  motion_ticket = control_ticket = settlement_deadline = next_renewal = None
  live_write_admitted_at = None
  accepted = settling = stop_published = False
  terminal = None

  def admit_live_write():
    nonlocal live_write_admitted_at
    if live_jog_stop_requested.is_set():
      raise SerialActivityRejected("live jog stopped before transmission")
    live_write_admitted_at = time.monotonic()
    if write_started_event is not None:
      write_started_event.set()
    return True

  def live_renewal_deadline():
    if live_write_admitted_at is None:
      raise ProtocolResponseError("JSON live-jog write admission time is missing")
    return live_write_admitted_at + JSON_LIVE_MOTION_RENEWAL_INTERVAL_SECONDS

  try:
    try:
      motion_ticket = request(
        **parameters,
        timeout=response_timeout,
        write_admission=admit_live_write,
      )
    except SerialActivityRejected as exc:
      detail = str(exc)
      return JointMotionExchangeResult(
        detail, None, detail, confirmed_position_unchanged=True
      )
    while terminal is None:
      delivery = client.pop_delivery()
      if delivery is None:
        if client.poll():
          continue
        if not accepted or control_ticket is not None:
          continue
        if settling:
          if time.monotonic() >= settlement_deadline:
            raise ProtocolResponseError(
              f"JSON {motion_name} jog terminal settlement timed out"
            )
          continue
        if live_jog_stop_requested.is_set():
          control_ticket = client.request_stop_live_motion(
            motion_ticket,
            timeout=response_timeout,
          )
          settling = True
          continue
        if time.monotonic() >= next_renewal:
          try:
            control_ticket = client.request_renew_live_motion(
              motion_ticket,
              timeout=response_timeout,
              write_admission=admit_live_write,
            )
          except SerialActivityRejected:
            control_ticket = client.request_stop_live_motion(
              motion_ticket,
              timeout=response_timeout,
            )
            settling = True
        continue

      if type(delivery) is JsonTelemetryDelivery:
        raise ProtocolResponseError(
          f"JSON {motion_name} jog received unsolicited telemetry"
        )
      if type(delivery) is JsonEventDelivery:
        _validate_json_joint_motion_event(delivery, f"{motion_name} jog")
        if not stop_published:
          _publish_json_live_jog_stop(
            stop_context,
            command_name,
            "emergency_stop_event",
          )
          stop_published = True
        continue
      if type(delivery) is not JsonResponseDelivery:
        raise ProtocolResponseError(
          f"JSON {motion_name} jog received an unknown delivery type"
        )

      if delivery.ticket is motion_ticket:
        if control_ticket is not None:
          raise ProtocolResponseError(
            f"JSON {motion_name} jog terminal preceded control settlement"
          )
        if delivery.response.status == "accepted":
          if accepted:
            raise ProtocolResponseError(
              f"JSON {motion_name} jog received duplicate acceptance"
            )
          accepted = True
          next_renewal = live_renewal_deadline()
          continue
        failure = delivery.response.error
        if (
          failure is not None
          and failure.code == "emergency_stop_active"
          and not stop_published
        ):
          _publish_json_live_jog_stop(
            stop_context,
            command_name,
            "emergency_stop_active",
          )
          stop_published = True
        terminal = client.take_terminal(motion_ticket)
        client.acknowledge_terminal(motion_ticket)
        if terminal.response is not delivery.response:
          raise ProtocolResponseError(
            f"JSON {motion_name} jog terminal ownership changed"
          )
        continue

      if delivery.ticket is not control_ticket:
        raise ProtocolResponseError(
          f"JSON {motion_name} jog received a response for another request"
        )
      control_command = control_ticket.command
      control_terminal = client.take_terminal(control_ticket)
      client.acknowledge_terminal(control_ticket)
      control_ticket = None
      if control_terminal.response is not delivery.response:
        raise ProtocolResponseError(
          f"JSON {motion_name} jog control ownership changed"
        )
      if control_terminal.response.status == "completed":
        if control_command == "renew_live_motion":
          next_renewal = live_renewal_deadline()
        else:
          settlement_deadline = time.monotonic() + response_timeout
        continue
      failure = control_terminal.failure
      if failure is not None and failure.code == "emergency_stop_active":
        if not stop_published:
          _publish_json_live_jog_stop(
            stop_context,
            command_name,
            "emergency_stop_active",
          )
          stop_published = True
        settling = True
        settlement_deadline = time.monotonic() + response_timeout
        continue
      if (
        failure is not None
        and (
          failure.code == "no_live_motion"
          or (
            control_command == "renew_live_motion"
            and failure.code == "control_lease_expired"
          )
        )
      ):
        settling = True
        settlement_deadline = time.monotonic() + response_timeout
        continue
      raise ProtocolResponseError(
        _json_joint_motion_failure_detail(
          control_terminal,
          f"{motion_name} jog {control_command}",
        )
      )

    while True:
      delivery = client.pop_delivery()
      if delivery is None:
        polled = client.poll()
        if not polled and not client.has_unread_input:
          break
        continue
      if type(delivery) is JsonEventDelivery:
        _validate_json_joint_motion_event(delivery, f"{motion_name} jog")
        if not stop_published:
          _publish_json_live_jog_stop(
            stop_context,
            command_name,
            "emergency_stop_event",
          )
          stop_published = True
        continue
      raise ProtocolResponseError(
        f"JSON {motion_name} jog received post-terminal non-event data"
      )
    if client.release_reader() is not True:
      raise ProtocolResponseError(
        f"JSON {motion_name} jog reader ownership was not released"
      )

    result = _json_joint_motion_terminal_result(
      terminal,
      stop_context,
      stop_published,
      motion_name=f"{motion_name} jog",
      positionless_rejection_codes=(),
    )
  except BaseException:
    cleanup_required = motion_ticket is not None or client.quarantined
    if motion_ticket is None:
      try:
        motion_ticket = client.pending_motion_ticket
      except BaseException:
        cleanup_required = True
      else:
        cleanup_required = motion_ticket is not None or cleanup_required
    if cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON live-jog failure cleanup",
      )
    raise

  if position_response_is_physical_estop(result.position):
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON live-jog physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON live-jog physical-stop quarantine",
      )
  return result


def _exchange_live_jog(
  command,
  *,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if write_cancellation_boundary is not None:
    raise MotionInputError("live jog does not accept a write-cancellation boundary")
  serial_port = RUN.get('ser')
  try:
    command = _canonicalize_main_serial_command(command)
    binding = _current_main_controller_identity(serial_port)
    if binding is None or not isinstance(
      binding.json_client,
      JsonMainControllerClient,
    ):
      raise ProtocolResponseError("JSON live jog lost controller ownership")
    return _exchange_json_live_jog(
      command,
      binding,
      _capture_main_controller_stop_context(serial_port),
      write_started_event,
    )
  finally:
    if (
      RUN.get('ser') is serial_port
      and not getattr(serial_port, "is_open", False)
    ):
      _require_main_controller_identity_cleanup(
        serial_port,
        "live-jog controller exchange cleanup",
      )


def _format_main_controller_diagnostic(command_name, result):
  if command_name == "set_encoders":
    return "Done"
  if command_name == "test_limit_switches":
    values = tuple(int(value) for value in result)
  elif command_name == "read_encoders":
    values = result
  else:
    raise MotionInputError("controller diagnostic command is invalid")
  return "   ".join(
    f"J{axis} = {value}"
    for axis, value in enumerate(values, start=1)
  )


def _json_controller_diagnostic_failure_detail(terminal):
  failure = terminal.failure
  if failure is None:
    return (
      "controller returned a non-completed JSON diagnostic response "
      f"without an error: {terminal.response.status}"
    )
  return (
    f"controller {terminal.response.status} JSON diagnostic: "
    f"{failure.code}: {' '.join(failure.message.split())}"
  )


def _exchange_json_controller_diagnostic(
  command_name,
  binding,
  response_timeout,
  write_started_event,
  write_cancellation_boundary,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "persistent JSON diagnostic lacks a valid client"
    )
  request = {
    "read_encoders": client.request_read_encoders,
    "set_encoders": client.request_set_encoders,
    "test_limit_switches": client.request_test_limit_switches,
  }.get(command_name)
  if request is None:
    raise MotionInputError("controller diagnostic command is invalid")
  ticket = None
  try:
    ticket = request(
      timeout=response_timeout,
      write_admission=_json_motion_write_admission(
        write_started_event,
        write_cancellation_boundary,
      ),
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      _capture_main_controller_stop_context(client.serial_port),
      False,
      command_name=command_name,
      motion_name="controller diagnostic",
    )
  except BaseException:
    if (
      ticket is not None
      or client.quarantined
      or (
        write_started_event is not None
        and write_started_event.is_set()
      )
    ):
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON controller diagnostic failure cleanup",
      )
    raise
  if stop_published:
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON controller diagnostic physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON controller diagnostic physical-stop cleanup",
      )
    raise ProtocolResponseError(
      "physical E-stop interrupted the JSON controller diagnostic"
    )
  if terminal.response.status != "completed":
    raise ProtocolResponseError(
      _json_controller_diagnostic_failure_detail(terminal)
    )
  return _format_main_controller_diagnostic(
    command_name,
    terminal.parsed_result,
  )


def _exchange_main_controller_diagnostic(
  command_name,
  *,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if command_name not in {
    "read_encoders",
    "set_encoders",
    "test_limit_switches",
  }:
    raise MotionInputError("controller diagnostic command is invalid")
  serial_port = RUN.get('ser')
  binding = _current_main_controller_identity(serial_port)
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError(
      "JSON controller diagnostic lost controller ownership"
    )
  return _exchange_json_controller_diagnostic(
    command_name,
    binding,
    SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
    write_started_event,
    write_cancellation_boundary,
  )


def _await_json_joint_motion_terminal(
  client,
  ticket,
  stop_context,
  telemetry_enabled,
  command_name="move_joints",
  motion_name="joint",
  stop_publication_callback=None,
  retain_failed_modbus_terminal=False,
  telemetry_measurement=None,
):
  if type(telemetry_enabled) is not bool:
    raise MotionInputError(
      f"JSON {motion_name}-motion telemetry selection is invalid"
    )
  if stop_publication_callback is not None and not callable(
    stop_publication_callback
  ):
    raise MotionInputError(
      f"JSON {motion_name}-motion stop callback is invalid"
    )
  if type(retain_failed_modbus_terminal) is not bool:
    raise MotionInputError(
      f"JSON {motion_name}-motion terminal-retention selection is invalid"
    )
  if telemetry_measurement is not None and not isinstance(
    telemetry_measurement,
    JointTelemetryMeasurement,
  ):
    raise MotionInputError(
      f"JSON {motion_name}-motion telemetry measurement is invalid"
    )
  terminal = None
  stop_published = False
  while terminal is None:
    delivery = client.pop_delivery()
    if delivery is None:
      if not client.poll():
        time.sleep(JSON_SERIAL_DEFAULT_POLL_INTERVAL_SECONDS)
      continue
    if type(delivery) is JsonTelemetryDelivery:
      if not telemetry_enabled:
        raise ProtocolResponseError(
          f"JSON {motion_name} motion received unsolicited telemetry"
        )
      received_at_ns = time.monotonic_ns()
      sample = parse_main_joint_position_telemetry(delivery.telemetry)
      raw = _canonical_json_message_text(delivery.telemetry)
      accepted = joint_motion_dispatcher.publish_position_telemetry(
        raw,
        sample.robot_joints_degrees,
      )
      if telemetry_measurement is not None:
        telemetry_measurement.observe(
          delivery.telemetry.seq,
          delivery.sequence_contiguous,
          raw,
          accepted,
          received_at_ns,
        )
      continue
    if type(delivery) is JsonEventDelivery:
      _validate_json_joint_motion_event(delivery, motion_name)
      if not stop_published:
        _publish_main_controller_unpositioned_stop(
          stop_context,
          JsonMainControllerPhysicalStop(
            command_name,
            "emergency_stop_event",
          ),
        )
        if stop_publication_callback is not None:
          stop_publication_callback()
        stop_published = True
      continue
    if type(delivery) is not JsonResponseDelivery:
      raise ProtocolResponseError(
        f"JSON {motion_name} motion received an unknown delivery type"
      )
    if delivery.ticket is not ticket:
      raise ProtocolResponseError(
        f"JSON {motion_name} motion received a response for another request"
      )
    if delivery.response.status == "accepted":
      continue
    terminal_received_at_ns = time.monotonic_ns()
    terminal_physical_stop = (
      delivery.response.error is not None
      and delivery.response.error.code == "emergency_stop_active"
    )
    if terminal_physical_stop and not stop_published:
      _publish_main_controller_unpositioned_stop(
        stop_context,
        JsonMainControllerPhysicalStop(
          command_name,
          "emergency_stop_active",
        ),
      )
      if stop_publication_callback is not None:
        stop_publication_callback()
      stop_published = True
    terminal = client.take_terminal(ticket)
    if telemetry_measurement is not None:
      telemetry_measurement.observe_terminal(terminal_received_at_ns)
    retain_terminal = (
      retain_failed_modbus_terminal
      and terminal.response.status == "failed"
      and terminal.failure is not None
      and terminal.failure.code == "modbus_error"
    )
    if not retain_terminal:
      client.acknowledge_terminal(ticket)
    if terminal.response is not delivery.response:
      raise ProtocolResponseError(
        f"JSON {motion_name}-motion terminal ownership changed during settlement"
      )
    if terminal_physical_stop:
      raise ProtocolResponseError(
        _json_joint_motion_failure_detail(terminal, motion_name)
      )

  while True:
    delivery = client.pop_delivery()
    if delivery is None:
      polled = client.poll()
      if not polled and not client.has_unread_input:
        break
      continue
    if type(delivery) is JsonEventDelivery:
      _validate_json_joint_motion_event(delivery, motion_name)
      if not stop_published:
        _publish_main_controller_unpositioned_stop(
          stop_context,
          JsonMainControllerPhysicalStop(
            command_name,
            "emergency_stop_event",
          ),
        )
        if stop_publication_callback is not None:
          stop_publication_callback()
        stop_published = True
      continue
    raise ProtocolResponseError(
      f"JSON {motion_name} motion received post-terminal non-event data"
    )
  if client.release_reader() is not True:
    raise ProtocolResponseError(
      f"JSON {motion_name}-motion reader ownership was not released"
    )
  return terminal, stop_published


def _exchange_json_controller_correction(
  binding,
  response_timeout,
  write_started_event,
  write_cancellation_boundary,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "persistent JSON position correction lacks a valid client"
    )
  stop_context = _capture_main_controller_stop_context(client.serial_port)
  stop_observed = threading.Event()
  ticket = None
  stop_published = False
  try:
    ticket = client.request_correct_position(
      timeout=response_timeout,
      write_admission=_json_motion_write_admission(
        write_started_event,
        write_cancellation_boundary,
      ),
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      False,
      command_name="correct_position",
      motion_name="position correction",
      stop_publication_callback=stop_observed.set,
    )
    result = _json_controller_correction_terminal_result(
      terminal,
      stop_context,
      stop_published,
    )
    if position_response_is_physical_estop(result.position):
      if not stop_published:
        stop_observed.set()
        _publish_main_controller_stop(stop_context, result.position)
      stop_published = True
  except BaseException:
    cleanup_required = ticket is not None or client.quarantined
    if ticket is None:
      try:
        cleanup_required = bool(client.pending_tickets) or cleanup_required
      except BaseException:
        cleanup_required = True
    if stop_observed.is_set():
      try:
        quarantine_serial_transport(
          client.serial_port,
          "JSON position-correction physical E-stop requires reconnection",
        )
      finally:
        _require_main_controller_identity_cleanup(
          client.serial_port,
          "JSON position-correction physical-stop failure cleanup",
        )
    elif cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON position-correction failure cleanup",
      )
    raise

  if stop_published:
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON position-correction physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON position-correction physical-stop cleanup",
      )
  return result


def _exchange_controller_correction(
  command,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if _canonicalize_main_serial_command(command) != "CP\n":
    raise MotionInputError("controller correction command is invalid")
  serial_port = RUN.get('ser')
  binding = _current_main_controller_identity(serial_port)
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError(
      "persistent JSON position correction lost controller ownership"
    )
  return _exchange_json_controller_correction(
    binding,
    SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
    write_started_event,
    write_cancellation_boundary,
  )


def _json_position_failure_response(terminal):
  failure = terminal.failure
  if failure is None:
    raise ProtocolResponseError(
      "controller returned a non-completed JSON position response "
      f"without an error: {terminal.response.status}"
    )
  if terminal.response.status != "failed":
    raise ProtocolResponseError(
      "controller rejected JSON position refresh: "
      f"{failure.code}: {' '.join(failure.message.split())}"
    )
  if failure.code == "controller_alarm":
    alarm = failure.details.get("controller_alarm")
    if not isinstance(alarm, str) or not alarm.startswith("E"):
      raise ProtocolResponseError(
        "JSON position refresh returned an invalid controller alarm"
      )
    return alarm
  if failure.code == "position_unavailable":
    raise ProtocolResponseError(
      "controller position is unavailable; reconnect required"
    )
  raise ProtocolResponseError(
    "controller failed JSON position refresh: "
    f"{failure.code}: {' '.join(failure.message.split())}"
  )


def _exchange_json_completed_request(
  binding,
  request,
  parameters,
  response_timeout,
  write_started_event,
  command_name,
  operation_name,
  result_type=None,
  completed_stop_event=None,
  write_cancellation_boundary=None,
  cancelled_physical_stop=False,
  return_modbus_terminal=False,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      f"persistent JSON {operation_name} lacks a valid client"
    )
  if not callable(request):
    raise MotionInputError(f"JSON {operation_name} request is invalid")
  if type(parameters) is not dict:
    raise MotionInputError(f"JSON {operation_name} parameters are invalid")
  if result_type is not None and not isinstance(result_type, type):
    raise MotionInputError(f"JSON {operation_name} result type is invalid")
  if completed_stop_event is not None and not all(
    callable(getattr(completed_stop_event, method, None)) for method in ("set", "is_set")
  ):
    raise MotionInputError(f"JSON {operation_name} stop event is invalid")
  if type(cancelled_physical_stop) is not bool:
    raise MotionInputError(
      f"JSON {operation_name} cancelled-stop selection is invalid"
    )
  if type(return_modbus_terminal) is not bool:
    raise MotionInputError(f"JSON {operation_name} terminal-return selection is invalid")
  ticket = None
  stop_context = _capture_main_controller_stop_context(client.serial_port)
  stop_observed = (
    threading.Event() if completed_stop_event is None else completed_stop_event
  )
  try:
    ticket = request(
      **parameters,
      timeout=response_timeout,
      write_admission=_json_motion_write_admission(
        write_started_event,
        write_cancellation_boundary,
      ),
    )
    return_modbus_write_terminal = (
      return_modbus_terminal
      and command_name in (
        "modbus_write_coil",
        "modbus_write_register",
      )
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      False,
      command_name=command_name,
      motion_name=operation_name,
      stop_publication_callback=stop_observed.set,
      retain_failed_modbus_terminal=return_modbus_write_terminal,
    )
    failure = terminal.failure
    if (
      cancelled_physical_stop
      and not stop_published
      and terminal.response.status == "cancelled"
      and failure is not None
      and failure.code == "emergency_stop"
    ):
      stop_observed.set()
      _publish_main_controller_unpositioned_stop(
        stop_context,
        JsonMainControllerPhysicalStop(
          command_name,
          "emergency_stop_event",
        ),
      )
      stop_published = True
    returned_cancelled_modbus_write = (
      return_modbus_write_terminal
      and terminal.response.status == "cancelled"
      and failure is not None
      and failure.code == "emergency_stop"
    )
    returned_rejected_modbus_write = (
      return_modbus_write_terminal
      and terminal.response.status == "rejected"
    )
    if stop_published and not (
      terminal.response.status == "completed"
      and (
        completed_stop_event is not None
        or return_modbus_write_terminal
      )
    ) and not (
      returned_cancelled_modbus_write
      or returned_rejected_modbus_write
    ):
      raise ProtocolResponseError(
        f"physical E-stop interrupted JSON {operation_name}"
      )
    if terminal.response.status != "completed" and not (
      (
        return_modbus_terminal
        and terminal.response.status == "failed"
        and failure is not None
        and failure.code == "modbus_error"
      )
      or returned_cancelled_modbus_write
      or returned_rejected_modbus_write
    ):
      if failure is None:
        raise ProtocolResponseError(
          f"controller returned a non-completed JSON {operation_name} response "
          f"without an error: {terminal.response.status}"
        )
      raise ProtocolResponseError(
        f"controller {terminal.response.status} JSON {operation_name}: "
        f"{failure.code}: {' '.join(failure.message.split())}"
      )
    result = terminal.parsed_result
    if (
      terminal.response.status == "completed"
      and result_type is not None
      and not isinstance(result, result_type)
    ):
      raise ProtocolResponseError(
        f"JSON {operation_name} result has an invalid type"
      )
  except BaseException:
    cleanup_required = (
      ticket is not None
      or client.quarantined
      or (
        write_started_event is not None
        and write_started_event.is_set()
      )
    )
    if ticket is None:
      try:
        cleanup_required = bool(client.pending_tickets) or cleanup_required
      except BaseException:
        cleanup_required = True
    if stop_observed.is_set():
      try:
        quarantine_serial_transport(
          client.serial_port,
          f"JSON {operation_name} physical E-stop requires reconnection",
        )
      finally:
        _require_main_controller_identity_cleanup(
          client.serial_port,
          f"JSON {operation_name} physical-stop failure cleanup",
        )
    elif cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port, f"JSON {operation_name} failure cleanup",
      )
    raise
  return terminal


def _exchange_json_main_command(
  command_name,
  parameters,
  *,
  response_timeout=SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
  write_started_event=None,
  write_cancellation_boundary=None,
  completed_stop_event=None,
  result_type=None,
  return_terminal=False,
):
  if not isinstance(command_name, str) or not command_name:
    raise MotionInputError("JSON main-controller command is invalid")
  if type(parameters) is not dict:
    raise MotionInputError("JSON main-controller parameters are invalid")
  if type(return_terminal) is not bool:
    raise MotionInputError("JSON terminal selection is invalid")
  binding = _current_main_controller_identity(RUN.get('ser'))
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError(
      "JSON main-controller ownership is unavailable"
    )
  client = binding.json_client
  terminal = _exchange_json_completed_request(
    binding,
    partial(client.request_command, command_name, parameters),
    {},
    response_timeout,
    write_started_event,
    command_name,
    command_name.replace("_", " "),
    result_type,
    completed_stop_event=completed_stop_event,
    write_cancellation_boundary=write_cancellation_boundary,
    cancelled_physical_stop=True,
  )
  return terminal if return_terminal else terminal.parsed_result


def _exchange_main_controller_modbus_read(
  command, *, response_timeout=SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
  write_started_event=None, write_cancellation_boundary=None, completed_stop_event=None,
):
  opcode, slave_id, address, _ = parse_controller_modbus_command(command)
  command_name = {
    "BA": "modbus_read_holding_register", "BH": "modbus_read_holding_register",
    "BB": "modbus_read_coil", "BC": "modbus_read_discrete_input",
    "BD": "modbus_read_input_register"}.get(opcode)
  if command_name is None:
    raise MotionInputError("Modbus read opcode is unsupported")
  serial_port = RUN.get('ser')
  if serial_port is None:
    raise ConnectionError("Modbus read requires a main connection")
  binding = _current_main_controller_identity(serial_port)
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError("Modbus read lost controller identity")
  client = binding.json_client
  terminal = _exchange_json_completed_request(
    binding, partial(client.request_modbus_read, command_name),
    {"slave_id": slave_id, "address": address},
    response_timeout, write_started_event, command_name, "Modbus read",
    completed_stop_event=completed_stop_event,
    write_cancellation_boundary=write_cancellation_boundary,
    cancelled_physical_stop=True,
    return_modbus_terminal=True,
  )
  if terminal.response.status != "completed":
    raise ProtocolResponseError(
      f"controller failed JSON Modbus read: {terminal.failure.code}: "
      f"{' '.join(terminal.failure.message.split())}"
    )
  if type(terminal.parsed_result) is not int:
    raise ProtocolResponseError("controller returned an invalid Modbus read result")
  return parse_controller_modbus_response(command, str(terminal.parsed_result))


def _exchange_main_controller_modbus_write(
  command,
  *,
  response_timeout=SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
  write_started_event=None,
  write_cancellation_boundary=None,
  completed_stop_event=None,
):
  opcode, slave_id, address, value = parse_controller_modbus_command(command)
  command_name = {
    "BE": "modbus_write_coil",
    "SC": "modbus_write_coil",
    "BF": "modbus_write_register",
    "SO": "modbus_write_register",
  }.get(opcode)
  if command_name is None:
    raise MotionInputError("Modbus write opcode is unsupported")
  binding = _current_main_controller_identity(RUN.get('ser'))
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError("Modbus write lost controller identity")
  client = binding.json_client
  terminal = _exchange_json_completed_request(
    binding,
    partial(client.request_modbus_write, command_name),
    {"slave_id": slave_id, "address": address, "value": value},
    response_timeout,
    write_started_event,
    command_name,
    "Modbus write",
    write_cancellation_boundary=write_cancellation_boundary,
    completed_stop_event=completed_stop_event,
    cancelled_physical_stop=True,
    return_modbus_terminal=True,
  )
  if terminal.response.status == "cancelled":
    if terminal.failure is None or terminal.failure.code != "emergency_stop":
      raise ProtocolResponseError(
        "controller returned an invalid cancelled Modbus-write terminal"
    )
    return "ER" if opcode in ("BE", "BF") else "-2"
  if terminal.response.status == "rejected":
    return "ER" if opcode in ("BE", "BF") else "-2"
  if terminal.response.status == "failed":
    if terminal.failure is None or terminal.failure.code != "modbus_error":
      raise ProtocolResponseError(
        "controller returned an invalid Modbus-write failure terminal"
      )
    return "Modbus Error" if opcode in ("BE", "BF") else "-1"
  return "Write Success" if opcode in ("BE", "BF") else "1"


def _exchange_main_controller_modbus_wait(
  command,
  *,
  response_timeout,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  if not isinstance(command, str):
    raise MotionInputError("Modbus wait command is invalid")
  match = re.fullmatch(
    r"W(?P<kind>[HJK])A(?P<slave>[0-9]+)B(?P<address>[0-9]+)"
    r"C(?P<expected>[0-9]+)D(?P<timeout>[0-9]+)\n",
    command,
  )
  if match is None:
    raise MotionInputError("Modbus wait command framing is invalid")
  timeout_seconds = _main_modbus_wait_timeout_seconds(match.group("timeout"))
  command_name = {
    "H": "wait_modbus_holding_register",
    "J": "wait_modbus_coil",
    "K": "wait_modbus_discrete_input",
  }[match.group("kind")]
  result = _exchange_json_main_command(
    command_name,
    {
      "slave_id": int(match.group("slave")),
      "address": int(match.group("address")),
      "expected": int(match.group("expected")),
      "timeout_seconds": timeout_seconds,
    },
    response_timeout=response_timeout,
    write_started_event=write_started_event,
    write_cancellation_boundary=write_cancellation_boundary,
  )
  if type(result) is not JsonScalarResult:
    raise ProtocolResponseError(
      "controller returned an invalid Modbus wait result"
    )
  expected = int(match.group("expected"))
  if result.value != expected:
    raise ProtocolResponseError(
      "controller Modbus wait result does not match the requested state"
    )
  return "Done"


def _exchange_main_controller_wait(
  command, wait_seconds, *, response_timeout,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  wait_seconds, encoded_wait = _main_timed_wait_seconds(wait_seconds)
  if command != f"WTS{encoded_wait}\n":
    raise MotionInputError("controller wait command does not match its duration")
  serial_port = RUN.get('ser')
  if serial_port is None:
    raise ConnectionError("controller wait requires a main connection")
  binding = _current_main_controller_identity(serial_port)
  if binding is None or not isinstance(
    binding.json_client,
    JsonMainControllerClient,
  ):
    raise ProtocolResponseError(
      "controller wait lost the bound main-controller identity"
    )
  terminal = _exchange_json_completed_request(
    binding,
    getattr(binding.json_client, "request_controller_wait", None),
    {"seconds": wait_seconds},
    response_timeout,
    write_started_event,
    "controller_wait",
    "controller wait",
    write_cancellation_boundary=write_cancellation_boundary,
    cancelled_physical_stop=True,
  )
  return terminal.parsed_result


def _exchange_json_configuration_acknowledgement(
  binding,
  command_name,
  parameters,
  response_timeout,
  write_started_event,
):
  client = binding.json_client
  request_name = {
    "config_ext_axis": "request_config_ext_axis",
    "set_position": "request_set_position",
    "update_params": "request_update_params",
  }.get(command_name)
  if request_name is None:
    raise MotionInputError("JSON configuration command is invalid")
  _exchange_json_completed_request(
    binding,
    getattr(client, request_name, None),
    parameters,
    response_timeout,
    write_started_event,
    command_name,
    "configuration",
  )
  return True


def _exchange_external_axis_zero(
  command,
  *,
  expected_serial_port,
  expected_binding,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  axis = {"Z7\n": 7, "Z8\n": 8, "Z9\n": 9}.get(command)
  if axis is None:
    raise MotionInputError("external-axis zero command is invalid")
  binding = _current_main_controller_identity(expected_serial_port)
  if binding is None or binding is not expected_binding:
    raise ProtocolResponseError("external-axis zero lost controller identity")
  client = expected_binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "JSON external-axis zero lost controller ownership"
    )
  if write_cancellation_boundary is None:
    stop_context = _capture_main_controller_stop_context(client.serial_port)
    stop_event = threading.Event()
    terminal = _exchange_json_completed_request(
      binding,
      getattr(client, "request_zero_external_axis", None),
      {"axis": axis},
      SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
      write_started_event,
      f"zero_j{axis}",
      f"external-axis {axis} zero",
      JsonMainPositionResult,
      completed_stop_event=stop_event,
    )
    result = terminal.parsed_result
    event_stop = stop_event.is_set()
    reported_stop = event_stop or result.motion_fault in CONTROLLER_PHYSICAL_ESTOP_FLAGS
    try:
      if event_stop and result.motion_fault.startswith("EC"):
        logger.error(
          "External-axis zero also reported controller fault %s",
          result.motion_fault,
        )
      raw = _canonical_json_message_text(terminal.response)
      position_flag = (
        CONTROLLER_ESTOP_EVENT_FLAG
        if event_stop
        else result.motion_fault
      )
      position = _json_joint_position_response(
        raw, result, speed_violation=result.speed_limited,
        debug=result.controller_debug, flag=position_flag,
      )
    except BaseException:
      if reported_stop:
        try:
          quarantine_serial_transport(
            client.serial_port,
            "JSON external-axis zero physical E-stop requires reconnection",
          )
        finally:
          _require_main_controller_identity_cleanup(
            client.serial_port,
            "JSON external-axis zero physical-stop translation cleanup",
          )
      raise
    if reported_stop:
      try:
        if event_stop:
          _publish_main_controller_stop_position_upgrade(
            stop_context, position,
          )
        else:
          _publish_main_controller_stop(stop_context, position)
      finally:
        try:
          quarantine_serial_transport(
            client.serial_port,
            "JSON external-axis zero physical E-stop requires reconnection",
          )
        finally:
          _require_main_controller_identity_cleanup(
            client.serial_port,
            "JSON external-axis zero physical-stop quarantine",
          )
    return position
  raise MotionInputError("JSON external-axis zero rejects cancellation")


def _exchange_json_controller_position(binding, response_timeout):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "persistent JSON position refresh lacks a valid client"
    )
  ticket = None
  write_started = threading.Event()
  stop_observed = threading.Event()
  stop_context = _capture_main_controller_stop_context(client.serial_port)
  try:
    ticket = client.request_position_disposition(
      timeout=response_timeout,
      write_admission=_json_motion_write_admission(write_started, None),
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      False,
      command_name="get_position_disposition",
      motion_name="position refresh",
      stop_publication_callback=stop_observed.set,
    )
    if terminal.response.status == "completed":
      result = terminal.parsed_result
      raw = _canonical_json_message_text(terminal.response)
      position_flag = result.motion_fault
      if stop_published and not position_flag:
        position_flag = CONTROLLER_ESTOP_EVENT_FLAG
      position = _json_joint_position_response(
        raw,
        result,
        speed_violation=result.speed_limited,
        debug=result.controller_debug,
        flag=position_flag,
      )
      if stop_published:
        stop_position = position
        if not position_response_is_physical_estop(stop_position):
          stop_position = _json_joint_position_response(
            raw,
            result,
            speed_violation=result.speed_limited,
            debug=result.controller_debug,
            flag=CONTROLLER_ESTOP_EVENT_FLAG,
          )
        _publish_main_controller_stop_position_upgrade(
          stop_context,
          stop_position,
        )
      elif position_response_is_physical_estop(position):
        _publish_main_controller_stop(stop_context, position)
        stop_published = True
      response = position
    else:
      response = _json_position_failure_response(terminal)
  except BaseException:
    if stop_observed.is_set():
      try:
        quarantine_serial_transport(
          client.serial_port,
          "JSON position-refresh physical E-stop requires reconnection",
        )
      finally:
        _require_main_controller_identity_cleanup(
          client.serial_port,
          "JSON position-refresh physical-stop failure cleanup",
        )
    elif ticket is not None or client.quarantined or write_started.is_set():
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON position-refresh failure cleanup",
      )
    raise

  if stop_published:
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON position-refresh physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON position-refresh physical-stop cleanup",
      )
  return response


def _exchange_main_controller_position():
  serial_port = RUN.get('ser')
  try:
    binding = _current_main_controller_identity(serial_port)
    if binding is None or not isinstance(
      binding.json_client,
      JsonMainControllerClient,
    ):
      raise ProtocolResponseError(
        "JSON position refresh lost controller ownership"
      )
    return _exchange_json_controller_position(
      binding,
      SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
    )
  finally:
    if (
      RUN.get('ser') is serial_port
      and serial_port is not None
      and not getattr(serial_port, "is_open", False)
    ):
      _require_main_controller_identity_cleanup(
        serial_port,
        "position-refresh controller exchange cleanup",
      )


def _set_motion_trace_arm_display():
  arm = globals().get("motion_trace_arm")
  button = globals().get("captureNextJointMoveBut")
  if not isinstance(arm, JsonMainMotionTraceArm) or button is None:
    return False
  armed = arm.armed
  button.config(
    text=(
      "Cancel next joint capture"
      if armed
      else "Capture next joint move"
    ),
  )
  return armed


def _schedule_motion_trace_arm_display():
  application_root = globals().get("root")
  if application_root is None:
    return False
  try:
    application_root.after(0, _set_motion_trace_arm_display)
  except Exception:
    logger.exception("Unable to schedule motion-trace control refresh")
    return False
  return True


def _schedule_motion_trace_status(message, style):
  application_root = globals().get("root")
  if application_root is None:
    return False
  try:
    application_root.after(
      0,
      partial(_set_application_status, message, style),
    )
  except Exception:
    logger.exception("Unable to schedule motion-trace status")
    return False
  return True


def _toggle_next_joint_motion_trace():
  arm = globals().get("motion_trace_arm")
  if not isinstance(arm, JsonMainMotionTraceArm):
    raise RuntimeError("motion-trace arm state is unavailable")
  if arm.armed:
    arm.cancel()
    _set_motion_trace_arm_display()
    _set_application_status(
      "JOINT MOTION CAPTURE CANCELLED",
      "Warn.TLabel",
    )
    return False
  binding = _current_main_controller_identity(RUN.get('ser'))
  if (
    binding is None
    or not isinstance(binding.json_client, JsonMainControllerClient)
  ):
    _set_application_status(
      "JOINT MOTION CAPTURE REQUIRES A READY MAIN CONTROLLER",
      "Alarm.TLabel",
    )
    return False
  if joint_motion_dispatcher.active:
    _set_application_status(
      "WAIT FOR THE CURRENT JOINT MOVE BEFORE ARMING CAPTURE",
      "Warn.TLabel",
    )
    return False
  try:
    joint_motion_visualization.clear_actual()
  except Exception:
    logger.exception("Unable to clear the obsolete encoder-sample display")
    _set_application_status(
      "JOINT MOTION CAPTURE NOT ARMED: ENCODER DISPLAY COULD NOT BE CLEARED",
      "Alarm.TLabel",
    )
    return False
  arm.arm()
  _set_motion_trace_arm_display()
  _set_application_status(
    "NEXT MANUAL JOINT MOVE WILL BE CAPTURED",
    "OK.TLabel",
  )
  return True


def _motion_trace_controller_identity(binding):
  identity = binding.identity
  return {
    "asset_tag": identity.asset_tag,
    "controller_hardware_id": identity.controller_hardware_id,
    "driver_model": identity.driver_model,
    "protocol_capabilities": identity.protocol_capabilities,
    "robot_model": identity.robot_model,
    "robot_version": identity.robot_version,
    "serial_number": identity.serial_number,
  }


def _fail_json_motion_trace_session(binding, message):
  try:
    quarantine_serial_transport(binding.json_client.serial_port, message)
  finally:
    _require_main_controller_identity_cleanup(
      binding.json_client.serial_port,
      "motion-trace protocol failure cleanup",
    )
  raise ProtocolResponseError(message)


def _retrieve_json_joint_motion_trace(
  binding,
  motion_request_id,
  motion_parameters,
  host_times_ns,
):
  client = binding.json_client
  session = client.session_binding
  _schedule_motion_trace_status(
    "RETRIEVING JOINT MOTION CAPTURE",
    "Warn.TLabel",
  )
  assembly = JsonMainMotionTraceAssembly(
    motion_request_id=motion_request_id,
    source_session_id=session.session_id,
    configuration_fingerprint=binding.configuration_fingerprint,
  )
  page_index = 0
  while True:
    terminal = _exchange_json_completed_request(
      binding,
      client.request_motion_trace,
      {
        "motion_request_id": motion_request_id,
        "page_index": page_index,
      },
      SERIAL_BASE_RESPONSE_TIMEOUT_SECONDS,
      None,
      "get_motion_trace",
      "motion-trace retrieval",
    )
    page = terminal.parsed_result
    if type(page) is JsonMainMotionTraceNoCaptureResult:
      if page_index != 0 or page.source_motion_request_id != motion_request_id:
        _fail_json_motion_trace_session(
          binding,
          "controller motion-trace absence does not match the requested motion"
        )
      logger.error(
        "Controller returned no capture for traced motion request %s",
        motion_request_id,
      )
      _schedule_motion_trace_status(
        "JOINT MOTION CAPTURE WAS NOT AVAILABLE",
        "Alarm.TLabel",
      )
      return None
    if type(page) is not JsonMainMotionTracePageResult:
      _fail_json_motion_trace_session(
        binding,
        "controller returned an invalid motion-trace page"
      )
    try:
      complete = assembly.accept(page)
    except Exception as exc:
      try:
        _fail_json_motion_trace_session(
          binding,
          "controller motion-trace page assembly failed",
        )
      except ProtocolResponseError as protocol_error:
        raise protocol_error from exc
    if complete:
      break
    page_index += 1

  host_times_ns["retrieved"] = time.time_ns()
  artifact = assembly.artifact(
    controller_identity=_motion_trace_controller_identity(binding),
    measurement_scale=binding.configuration.motion_trace_scale,
    motion_parameters=motion_parameters,
    host_times_ns=host_times_ns,
  )
  try:
    artifact_path = write_main_motion_trace_artifact(
      os.path.join("logs", "motion-traces"),
      artifact,
    )
  except (OSError, TypeError, ValueError):
    logger.exception(
      "Unable to finalize motion-trace artifact for request %s",
      motion_request_id,
    )
    _schedule_motion_trace_status(
      "JOINT MOTION CAPTURE COULD NOT BE SAVED",
      "Alarm.TLabel",
    )
    return None
  logger.info("Motion trace saved to %s", artifact_path)
  _schedule_motion_trace_status(
    f"JOINT MOTION CAPTURE SAVED: {artifact_path}",
    "OK.TLabel",
  )
  return artifact_path


def _exchange_json_joint_motion_request(
  parameters,
  binding,
  stop_context,
  response_timeout,
  telemetry_enabled,
  write_admission,
  trace_host_times_ns=None,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "persistent JSON joint motion lacks a valid client"
    )
  if type(parameters) is not dict:
    raise MotionInputError("JSON joint motion parameters are invalid")
  if (
    type(telemetry_enabled) is not bool
    or parameters.get("telemetry_enabled") is not telemetry_enabled
  ):
    raise MotionInputError("JSON joint motion telemetry contract is invalid")
  trace_fingerprint = parameters.get("trace_configuration_fingerprint")
  trace_requested = trace_fingerprint is not None
  if trace_requested != (trace_host_times_ns is not None):
    raise MotionInputError("JSON joint motion trace context is invalid")
  telemetry_measurement = ordinary_joint_telemetry_measurement(
    telemetry_enabled, trace_requested
  )
  if telemetry_measurement is not None:
    if write_admission is not None:
      raise MotionInputError("measured joint motion has conflicting admission")
  ticket = None
  try:
    if telemetry_measurement is not None:
      telemetry_measurement.admit(time.monotonic_ns())
    ticket = client.request_move_joints(
      **parameters,
      timeout=response_timeout,
      write_admission=write_admission,
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      telemetry_enabled,
      telemetry_measurement=telemetry_measurement,
    )
    result = _json_joint_motion_terminal_result(
      terminal,
      stop_context,
      stop_published,
    )
  except BaseException:
    cleanup_required = ticket is not None or client.quarantined
    if ticket is None:
      try:
        ticket = client.pending_joint_motion_ticket
      except BaseException:
        cleanup_required = True
      else:
        cleanup_required = ticket is not None or cleanup_required
    if cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON joint-motion failure cleanup",
      )
    raise

  if telemetry_measurement is not None:
    try:
      if (
        terminal.response.status == "completed"
        and result.error is None
        and not position_response_is_physical_estop(result.position)
      ):
        logger.info(
          "Joint telemetry measurement: %s",
          json.dumps(
            telemetry_measurement.finalize(ticket.request_id),
            sort_keys=True,
            separators=(",", ":"),
          ),
        )
      else:
        logger.info(
          "Joint telemetry measurement omitted for request %s: "
          "terminal did not qualify",
          ticket.request_id,
        )
    except Exception:
      # Local measurement diagnostics cannot invalidate a settled motion.
      logger.exception(
        "Unable to finalize joint telemetry measurement for request %s",
        ticket.request_id,
      )

  if position_response_is_physical_estop(result.position):
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON joint-motion physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON joint-motion physical-stop quarantine",
      )
  if trace_requested:
    trace_host_times_ns["terminal"] = time.time_ns()
    try:
      trace_retrieval_eligible = main_motion_trace_retrieval_eligible(
        terminal,
        stop_published or position_response_is_physical_estop(result.position),
      )
      if trace_retrieval_eligible:
        _retrieve_json_joint_motion_trace(
          binding,
          ticket.request_id,
          parameters,
          trace_host_times_ns,
        )
      elif not (
        stop_published or position_response_is_physical_estop(result.position)
      ):
        logger.warning(
          "Motion trace skipped for ineligible terminal on request %s",
          ticket.request_id,
        )
        _schedule_motion_trace_status(
          "JOINT MOTION CAPTURE SKIPPED AFTER TERMINAL",
          "Alarm.TLabel",
        )
    except Exception:
      # Local diagnostic failures preserve the terminal; transport loss remains
      # a controller failure so connection cleanup reaches the motion caller.
      logger.exception(
        "Unable to retrieve motion trace for settled request %s",
        ticket.request_id,
      )
      _schedule_motion_trace_status(
        "JOINT MOTION CAPTURE COULD NOT BE RETRIEVED",
        "Alarm.TLabel",
      )
      if (
        _current_main_controller_identity(client.serial_port) is not binding
        or client.closed
        or client.closing
        or client.quarantined
      ):
        raise
  return result


def _exchange_json_joint_motion(
  command,
  binding,
  stop_context,
  response_timeout,
  telemetry_enabled,
):
  arm = globals().get("motion_trace_arm")
  if not isinstance(arm, JsonMainMotionTraceArm):
    raise RuntimeError("motion-trace arm state is unavailable")
  reservation = (
    arm.reserve(binding.configuration_fingerprint)
    if arm.armed
    else None
  )
  trace_host_times_ns = None
  write_admission = None
  trace_fingerprint = None
  ordinary_telemetry_enabled = telemetry_enabled
  trace_admission_cancelled = False
  if reservation is not None:
    telemetry_enabled = False
    trace_fingerprint = reservation.configuration_fingerprint
    trace_host_times_ns = {"armed": reservation.armed_at_ns}

    def admit_trace_write():
      nonlocal trace_admission_cancelled
      if not arm.consume(reservation):
        trace_admission_cancelled = True
        return False
      trace_host_times_ns["admitted"] = time.time_ns()
      _schedule_motion_trace_arm_display()
      return True

    write_admission = admit_trace_write
  try:
    return _exchange_json_joint_motion_request(
      _json_joint_motion_parameters(
        command,
        telemetry_enabled,
        trace_fingerprint,
      ),
      binding,
      stop_context,
      response_timeout,
      telemetry_enabled,
      write_admission,
      trace_host_times_ns,
    )
  except JsonSessionAdmissionError:
    if not trace_admission_cancelled:
      raise
  # A refused write admission proves that no motion frame started. Cancellation
  # therefore downgrades safely to the ordinary manual request.
  return _exchange_json_joint_motion_request(
    _json_joint_motion_parameters(
      command,
      ordinary_telemetry_enabled,
      None,
    ),
    binding,
    stop_context,
    response_timeout,
    ordinary_telemetry_enabled,
    None,
  )


def _exchange_json_program_joint_motion(
  command,
  binding,
  stop_context,
  response_timeout,
  write_started_event,
  write_cancellation_boundary,
):
  target = parse_joint_motion_command(command)
  return _exchange_json_joint_motion_request(
    _json_joint_motion_target_parameters(
      target,
      False,
    ),
    binding,
    stop_context,
    response_timeout,
    False,
    _json_motion_write_admission(
      write_started_event,
      write_cancellation_boundary,
    ),
  )


def _exchange_json_cartesian_motion(
  command,
  binding,
  stop_context,
  response_timeout,
  write_started_event,
  write_cancellation_boundary,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "JSON Cartesian motion lacks a valid client"
    )
  if isinstance(command, ProgramJsonCartesianMotion):
    command_name = command.command_name
    motions = tuple(
      _json_cartesian_motion_parameters(segment)
      for segment in command.motion_commands
    )
    if command_name == "move_arc":
      params = {
        "motion": motions[0],
        "midpoint_translation_millimeters": command.control_points[0],
      }
    elif command_name == "move_circle":
      params = {
        "motion": motions[0],
        "center_translation_millimeters": command.control_points[0],
        "plane_translation_millimeters": command.control_points[1],
      }
    elif command_name == "move_spline":
      params = {
        "segments": [
          {
            "motion": motion,
            "rounding_millimeters": rounding,
          }
          for motion, rounding in zip(
            motions,
            command.roundings_millimeters,
          )
        ]
      }
    else:
      raise MotionInputError("program JSON Cartesian command is unsupported")
  else:
    command_name = {
      "MJ": "move_cartesian",
      "ML": "move_linear",
      "MV": "move_vision",
    }.get(command[:2])
    if command_name is None:
      raise MotionInputError("Cartesian motion opcode is unsupported")
    motion = _json_cartesian_motion_parameters(command)
    params = motion
  if command_name == "move_linear":
    match = re.search(r"Rnd(?P<value>[^W]+)W", command)
    if match is None:
      raise MotionInputError("linear motion rounding is missing")
    rounding_millimeters = finite_number(
      match.group("value"),
      "linear motion rounding",
    )
    if rounding_millimeters != 0.0:
      raise MotionInputError("linear motion rounding must equal zero")
    params = {
      "motion": motion,
      "rounding_millimeters": rounding_millimeters,
      "disable_wrist_rotation": False,
    }
  elif command_name == "move_vision":
    match = re.search(r"Vr(?P<value>[^L]+)Lm", command)
    if match is None:
      raise MotionInputError("vision motion rotation is missing")
    params = {
      "motion": motion,
      "vision_rotation_degrees": finite_number(
        match.group("value"),
        "vision motion rotation",
      ),
    }
  write_admission = _json_motion_write_admission(
    write_started_event,
    write_cancellation_boundary,
  )
  ticket = None
  try:
    ticket = client.request_command(
      command_name,
      params,
      timeout=response_timeout,
      write_admission=write_admission,
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      False,
      command_name=command_name,
      motion_name=command_name.replace("_", " "),
    )
    result = _json_joint_motion_terminal_result(
      terminal,
      stop_context,
      stop_published,
      motion_name=command_name.replace("_", " "),
      positionless_rejection_codes=(
        "kinematics_unreachable",
        "joint_limit_violation",
        "position_not_representable",
      ),
    )
  except BaseException:
    cleanup_required = ticket is not None or client.quarantined
    if ticket is None:
      try:
        cleanup_required = bool(client.pending_tickets) or cleanup_required
      except BaseException:
        cleanup_required = True
    if cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON Cartesian-motion failure cleanup",
      )
    raise

  if position_response_is_physical_estop(result.position):
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON Cartesian-motion physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON Cartesian-motion physical-stop quarantine",
      )
  return result


def _exchange_json_tool_jog(
  command,
  binding,
  stop_context,
  response_timeout,
  write_started_event,
  write_cancellation_boundary,
):
  client = binding.json_client
  if not isinstance(client, JsonMainControllerClient):
    raise ProtocolResponseError(
      "persistent JSON tool-frame jog lacks a valid client"
    )
  params = _json_tool_jog_parameters(command)
  write_admission = _json_motion_write_admission(
    write_started_event,
    write_cancellation_boundary,
  )
  ticket = None
  try:
    ticket = client.request_jog_tool(
      **params,
      timeout=response_timeout,
      write_admission=write_admission,
    )
    terminal, stop_published = _await_json_joint_motion_terminal(
      client,
      ticket,
      stop_context,
      False,
      command_name="jog_tool",
      motion_name="tool-frame jog",
    )
    result = _json_joint_motion_terminal_result(
      terminal,
      stop_context,
      stop_published,
      motion_name="tool-frame jog",
      positionless_rejection_codes=(
        "kinematics_unreachable",
        "joint_limit_violation",
        "position_not_representable",
      ),
    )
  except BaseException:
    cleanup_required = ticket is not None or client.quarantined
    if ticket is None:
      try:
        ticket = client.pending_tool_jog_ticket
      except BaseException:
        cleanup_required = True
      else:
        cleanup_required = ticket is not None or cleanup_required
    if cleanup_required:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON tool-frame jog failure cleanup",
      )
    raise

  if position_response_is_physical_estop(result.position):
    try:
      quarantine_serial_transport(
        client.serial_port,
        "JSON tool-frame jog physical E-stop requires reconnection",
      )
    finally:
      _require_main_controller_identity_cleanup(
        client.serial_port,
        "JSON tool-frame jog physical-stop quarantine",
      )
  return result


def _exchange_cartesian_motion(
  command,
  *,
  write_started_event=None,
  write_cancellation_boundary=None,
):
  serial_port = RUN.get('ser')
  try:
    command = _canonicalize_main_serial_command(command)
    binding = _current_main_controller_identity(serial_port)
    response_timeout = _controller_response_timeout(command)
    if binding is None or not isinstance(
      binding.json_client,
      JsonMainControllerClient,
    ):
      raise ProtocolResponseError(
        "JSON Cartesian motion lost controller ownership"
      )
    return _exchange_json_cartesian_motion(
      command,
      binding,
      _capture_main_controller_stop_context(serial_port),
      response_timeout,
      write_started_event,
      write_cancellation_boundary,
    )
  finally:
    if (
      RUN.get('ser') is serial_port
      and not getattr(serial_port, "is_open", False)
    ):
      _require_main_controller_identity_cleanup(
        serial_port,
        "Cartesian-motion controller exchange cleanup",
      )


